\section{A trigonometric formula for the signature in genus 2}\label{genre2}
Let us now start our investigation of the asymptotic behavior of the signature function. The first result of this paper is the following trigonometric formula for the signature in genus $2$.

\begin{Theorem}\label{sigma2}
  For $0<q<p$ coprime odd integers, we have
\begin{equation}\nonumber \sigma_2({{\textstyle\frac q p}})= \frac {1-p^2}{6p^2} +
  \frac 1 {4p^2}\sum_{n=1,\, \mathrm{ odd}}^{p-2}\frac{f(n,p,q)}{\sin^3(\frac{n\pi}{2p})\sin^2(\frac{qn\pi}{p})}
\end{equation}
where 
\begin{eqnarray*} f(n,p,q)&=(3p-3)\sin(\frac{(2q-1)n\pi}{2p})+(p+1)\sin(\frac{(2q-3)n\pi}{2p})\\
&+(p-1)\sin(\frac{(2q+3)n\pi}{2p})+(3p+3)\sin(\frac{(2q+1)n\pi}{2p}).
\end{eqnarray*}
\end{Theorem}

\begin{proof}
By a finite Fourier transform over $\Z/2p\Z$, we can write for $m\in\Z$ :
\begin{equation}\label{FFT}
  (-1)^{\lfloor m/p\rfloor}=
  \frac 1 p
  \sum_{n=1,\text{ odd}}^{2p-1}\frac{\sin(\pi n(2m+1)/2p)}{\sin(\pi n/2p)}
  =\frac 1 p  \sum_{n=1,\text{ odd}}^{2p-1} \frac {t^{2m+1}-t^{-2m-1}}{t-t^{-1}}
    \Big|_{t=e^{\frac {i\pi n}{2p}}~.
      }
\end{equation}
In the sequel, we set $\O_p=\{1,3,\ldots,2p-1\}$ and $\O_p^+=\{1,3,\ldots,p\}$. Using Formula \eqref{FFT} for each sign $\epsilon_{j+1}=(-1)^{\lfloor q(j+1)/p\rfloor}$ and plugging it into the formula of Lemma \ref{triplepsilon}, we get 
\begin{equation}\nonumber\sigma_2({\textstyle{\frac q p}})\,\,
  =\sum_{(j,k,\ell)\in T_p} \epsilon_{j+1}\epsilon_{k+1}\epsilon_{\ell+1}
  =\frac1 {p^3} \sum_{(a,b,c)\in \O_p^3}\psi(a,b,c)\end{equation} 
where
\begin{equation}
\psi(a,b,c)=\!\!\!\!\sum\limits_{(j,k,l)\in T_p}\!\!\!\!
\frac{(x^{2q(j+1)+1}-x^{-2q(j+1)-1})(y^{2q(k+1)+1}-y^{-2q(k+1)-1})(z^{2q(\ell+1)+1}-z^{-2q(\ell+1)-1})}{(x-x^{-1})(y-y^{-1})(z-z^{-1})}\nonumber
\end{equation}
with $x=e^{\frac{i\pi a}{2p}}$,  $y=e^{\frac{i\pi b}{2p}}$ and $z=e^{\frac{i\pi c}{2p}}$.

The function $\psi$ is clearly symmetric in its three variables and satisfies also $\psi(2p-a,b,c)=\psi(a,b,c)$. We can hence rewrite $\sigma_2(\frac q p)$  as 
\begin{equation}\label{eq4n}\sigma_2({\textstyle{\frac q p}})=
  \frac1 {p^3}
  \sum_{a,b,c\in \O_p^+} 2^{m_a+m_b+m_c}\psi(a,b,c)\end{equation}
where $m_a=1$ if $a\ne p$ and $m_p=0$.

In order to compute $\psi(a,b,c)$, we rewrite it as follows:
\begin{equation} \psi(a,b,c)= \sum\limits_{\epsilon,\mu,\nu=\pm 1}\epsilon\mu\nu \frac{ x^{\epsilon}y^{\mu}z^{\nu}F(x^{2q\epsilon},y^{2q\mu},z^{2q\nu})}{(x-x^{-1})(y-y^{-1})(z-z^{-1})}\label{eq5n}
\end{equation} where $F$ is the polynomial defined by $F(X,Y,Z)=\sum_{(j,k,l)\in T_p}X^{j+1}Y^{k+1}Z^{\ell +1}$.

The computation of $F(x^{2q\epsilon},y^{2q\mu},z^{2q\nu})$ is simplified by the following observation:  we have $$F(X,Y,Z)=X^pY^p F(X^{-1}, Y^{-1},Z)~,$$ since the involution $(j,k,\ell ) \mapsto (p-2-j,p-2-k,\ell)$ preserves the set $T_p$. Therefore, since $F$ is symmetric in its three variables,  whenever $F(X,Y,Z)$ is evaluated at numbers $X=x^{2q}$, $Y=y^{2q}$, and $Z=z^{2q}$
satisfying $X^p=Y^p=Z^p=-1$, then for  any $\epsilon,\mu,\nu=\pm 1$, we have that $F(X^\epsilon, Y^\mu,Z^\nu)$ is equal to either $F(X,Y,Z)$ (when $\epsilon\mu\nu =1$) or to  $F(X^{-1}, Y^{-1},Z^{-1})= \overline {F(X,Y,Z)}$ (when $\epsilon\mu\nu =-1$).
\begin{Remark}\label{rk33}{\em For later use, we note the following special case: when $F(x^{2q},y^{2q},z^{2q})$ happens to be real, then $F(x^{2q\epsilon},y^{2q\mu},z^{2q\nu})$ 
    does not depend at all on $\epsilon,\mu$, or $\nu$, and formula \eqref{eq5n} for $\psi(a,b,c)$ simply becomes $\psi(a,b,c)=F(x^{2q},y^{2q},z^{2q})$.}
    \end{Remark}

