\Big( \frac{1}{\sqrt{R}} F_R(t_1), \ldots, \frac{1}{\sqrt{R}} F_R(t_m)\Big) \stackrel{d}{\to}
\big( \cG(t_1), \ldots, \cG(t_m)\big), \quad \mbox{as $R \to \infty$},
\]
where $\stackrel{d}{\to}$ denotes convergence in distribution.
By Cram\'er-Wold theorem, we have to show that for any $b_1,\ldots , b_m\in\bR$, 
\begin{equation}
\label{XR-conv}
X_R:=\frac{1}{\sqrt{R}}\sum_{j=1}^m b_j F_R(t_j)
\stackrel{d}{\to}
\sum_{j=1}^m b_j \cG_{t_j}\sim N(0,\tau^2), \quad \mbox{as $R \to \infty$},
\end{equation}
where $\tau^2={\rm Var}\big(\sum_{j=1}^m b_j \cG_{t_j}\big)$,
that is
$X_R/\tau\stackrel{d}{\to} N(0,1)$ as $R \to \infty$.
By Theorem \ref{main1}.(ii), 
\[
\tau_R^2:={\rm Var}(X_R)=\frac{1}{R} \sum_{j,k=1}^{m}b_j b_k \bE[F_R(t_j) F_R(t_k)]
\to \tau^2, \quad \mbox{as $R \to \infty$}.
\]
Therefore, it is enough to prove that $X_R/\tau_R \stackrel{d}{\to} N(0,1)$ as $R\to \infty$.
We will prove something stronger, namely, if $Z \sim N(0,1)$, then
\begin{equation}
\label{fdd}
d_{TV}\left(\frac{X_R}{\tau_R},Z \right) \leq C R^{-1/2},
\end{equation}
where $C>0$ is a constant that depends on $(t_1,\ldots,t_m)$ and $(b_1,\ldots,b_m)$.

\begin{lemma}
\label{lemA2-HNV}
