\begin{equation}\label{def:xi_delta}
 \xi_\delta\defeq N{e^{-\delta a^2g_N}} 
\end{equation}
and note that $\xi_1=\xi$.
Consider the sets
\begin{align}
\begin{split}
\label{eq:defLell}
\mathcal{L}_{L} \defeq \bigcup_{i=0}^{\lceil 2N/L\rceil} \widetilde{B}\Bigl((iL/2,0),L\Bigr),
\cL^\prime_L\defeq \tB_{10ML}\cup \cL_L, \text{ and }
\cL^{\prime\prime}_L=\cL^{\prime\prime}_L(\delta)\defeq\cL^\prime_L\setminus \tB_{ \xi_\delta}.
\end{split}
\end{align}
For any compact and connected $K\subset \tB_\xi$, define $\mathbb{P}^K_{\ba,L,\delta}$ as the law of
$(\varphi_x + \ba\,\overline{h}_{L}(x))_{x\in \tilde \Z^2\setminus K}$ under $\mathbb{P}^K_N$, where $\overline{h}_{L}(x)=P_x(H_{\mathcal{L}^{\prime\prime}_{L}} < H_K)$.
Then, as in \cite[(6.17)]{drewitz_critical_2023}, a change of measure via the Cameron-Martin formula yields
\begin{equation}
\label{eq:proof2point3}
\P^K_N\bigl(A(K,\ba,N)\bigr)
\ge 
\P^K_{\ba,L,\delta}\bigl(A(K,\ba,N)\bigr)
\exp\Biggl\{-\frac{\ba^{2}\capacity_N^K(\mathcal{L}^{\prime\prime}_{L}) + 1/e}{2\,\P^K_{\ba,L,\delta}(A(K,\ba,N))}\Biggr\}.
\end{equation} 
From now on take (cf.~\eqref{eq:ML_choice_ub})
\begin{equation}\label{eq:ML_choices}
 L=\frac{N}{a^2\log(N)} \text{ and }M=\frac{a^2\log(N)}{\log(a^2\log(N))^2}.
\end{equation}
