\begin{lemma} \label{lem:cap_ll}
There exists $\Cl[c]{delta_dist}\in(0,1)$ such that for all $\eta\in(0,1)$, $a^2\in(0,1)$ and $N\geq 1$ such that $a^2\log(N)\geq \Cr{lb}$, we have that with $L,M$ chosen as in \eqref{eq:ML_choices} and with $\delta=\Cr{delta_dist}$ , 
\begin{equation}\label{eq:cap_ll}
 \sup_K \capacity_N^K(\mathcal{L}^{\prime\prime}_{L}(\delta))\leq 
 (1+\eta) {\capacity_{\R^2}^{\tau}([0,1])},
\end{equation}
where the supremem is over all compact and connected $K\subset \tB_\xi$. 
\end{lemma}
\begin{lemma} \label{lem:li_connect}
Let $K\subset \tB_\xi$ be compact and connected. For all $\eta\in(0,1)$, $a^2\in(0,1)$ and $N\geq 1$ such that $a^2\log(N)\geq \Cr{lb}$, we have that with $L,M$ chosen as in \eqref{eq:ML_choices}, $\delta$ chosen as in \eqref{lem:cap_ll},
\begin{equation} \label{eq:li_connect}
 \P^K_{\ba,L,\delta}(A(K,\ba,N))\geq 1-\eta.
\end{equation}
\end{lemma}
Before presenting the proofs of Lemma \ref{lem:cap_ll} and \ref{lem:li_connect} , first note that by combining these lemmas with \eqref{eq:proof2point1}, \eqref{eq:lb_crit_cost} and \eqref{eq:proof2point3}, one obtains
\begin{equation*}
 \theta((1-\eta)\ba,N)\geq c(1-\eta)\theta(0,\xi)
 \exp\left\{-(1+\eta)\frac{\ba^2}{2} \capacity_{\R^2}^{\tau}([0,1])\right\},
\end{equation*}
from which \eqref{eq:prop_lb_asymp} follows using the fact that $\ba^2=\log(N/\xi)$ and a change of variable in $\eta$.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:li_connect}]
We follow the proof of \cite[Lemma 6.4]{drewitz_critical_2023}.
Let $\tau$ be an independent exponential random variable of rate $N^{-2}$. By the definitions of
$\P^K_{\ba,L,\Cr{delta_dist}}$ and $A(K,\ba,N)$, we have that
\begin{equation}
\label{eq:proof2point6}
\begin{aligned}
\P^K_{\ba,L,\Cr{delta_dist}}(A(K,\ba,N))
&\ge \mathbb{P}^K_N\bigl(K \leftrightarrow \partial B_N \text{ in } \{x\in \tilde\Z^2\setminus K : 
\varphi_x \ge \ba(1-\eta - h_{K}(x) - \overline{h}_{L}(x))\}\bigr)
\\
&\ge \mathbb{P}^K_N\bigl(K \leftrightarrow \partial B_N\text{ in } 
\{x\in \mathcal{L}'_{L}\cap \tilde\Z^2\setminus K : \varphi_x \ge -2\eta\ba\}\bigr),
\end{aligned}
\end{equation}
since for all $x\in \mathcal{L}'_{L}$, we have by \eqref{eq:defLell}, \cite[(2.51)]{lawler_random_2010} and the tail of exponential distribution that,
\begin{align*}
 h_{K}(x) + \overline{h}_{L}(x)
&= P_x(H_{K}<\infty) + P_x(H_{\mathcal{L}''_{L}}<H_{K})
=P_x(H_{K\cup \mathcal{L}''_{L}}<\infty)\\
&\ge P_x(H_{B(x,2\xi_{\Cr{delta_dist}})^{c}}<L^2)P(\tau>L^2) \geq (1-ce^{-c^\prime L^2/\xi_{\Cr{delta_dist}}^2}) e^{-L^2/N^2} \\
&\geq (1-ce^{-c^\prime \frac{e^{2\Cr{delta_dist}\ba}}{\ba^2}}) e^{-\frac{1}{\ba^2}} \geq 1-\eta ,
\end{align*}
where the last inequality holds upon taking $a^2\log(N)\geq \Cr{lb}(\eta)$ with $\Cr{lb}(\eta)$ large enough.
It's easy to see that there exists an integer $1\leq p\leq cM$ and a set of vertices $(z_0,z_1,\dots ,z_p)\subset \Z^2$ (which corresponds to the collection of vertices constructed in \cite[(7.14)]{drewitz_critical_2023}) such that,
 \begin{align} \label{eq:defS}
 \begin{split}
 &\begin{array}{r} 
 B(z_0,L/2)\subset B((3ML,0),L), \partial B_{3ML}\subset\bigcup_{i=1}^pB(z_i,L/4),
 \end{array} \\[0.3em] 
 &\begin{array}{r}
 B(z_i,L/4) \cap \partial B_{3ML}\neq \emptyset,
 d(z_i,B_\xi)\geq 2ML \text{ and } B(z_i,L/2)\subset B(z_{i-1},L) \text{ for all }i\in\{1,\dots,p\}.
 \end{array} \\[0.3em] 
 \end{split}
 \end{align}
We next define a suitable event implementing the desired connection in \eqref{eq:proof2point6}, which will be similar to the one illustrated in \cite[Figure 1]{drewitz_critical_2023}. 
The main difference from the setting of \cite{drewitz_critical_2023} is that the multiplicative scales $\sigma, \sigma'$ used there are replaced by substantially larger ones, and additional care is required for connection between $K$ to $\partial B_{\sqrt{\sigma'}\ell}$ due to the presence of a positive killing measure on our graph.
Let $u=(\eta \ba)^2$ and $\mathcal{P}=\{z_0,\dots ,z_p\}\cup \bigcup_{i=6M}^{\lceil 2N/L \rceil}(iL/2,0) $. By \eqref{eqcouplingintergff}, there exists a coupling $\P^K_N\otimes \bar\P^K_N$ of $\varphi$ under $\P^K_N$ with $\mathcal{I}^{2u}$ under $\bar\P^K_N$ such that $\{ \varphi \geq -2\eta \ba \} \supset \mathcal{I}^{2u}$, and $\I^{2u}$ splits as $\I^{2u}=\I^{u,1}\cup\I^{u,2}$ into two independent interlacement sets at level $u$. 
We denote by $\text{LocUniq}_{u,L}^{(2)}(x)$ the event from \eqref{def:local_uniqueness} with $\lambda = \frac{N}{Le^{\Cr{lu_lambda}^{-1}\log(N/L)}}$, defined for the interlacements $\I^{u,2}$. We define $\I^{u,1}_{-}$ as the set of vertices visited by trajectories of the interlacement associated with $\I^{u,1}$ whose backward parts are killed on $K$. Let $\I^{u,1,L}_{-}$ be the set of vertices in $\I^{u,1}_{-}$ visited before the first exit time from $B_{4ML}$. Consider the (good) event
\begin{equation}
\label{eq:lb15}
G= \Big\{\I^{u,1,L}_{-}\cap\I^{u,2}\cap\bigcup_{i=0}^pB(z_i,L/2)\neq\emptyset\Big\} \cap \bigcap_{x\in \mathcal{P}} \big( \big\{ \text{LocUniq}^{(2)}_{u,L}(x)\big\} \cap \{\I^{u,2} \cap B(x,L/2) \neq \emptyset\} \big).
\end{equation}
We also define, for all $s\in [0,1]$,
\[
G_s'=\Big\{\exists\,i\in \{0,\dots,p\}:\,\capacity_N^K(\I^{u,1,L}_{-}\cap B(z_i,L/2))\geq s\, \capacity_N^K(B(z_i,L/2))\Big\}.
\]
It then follows from the same reasoning as for \cite[(7.16)]{drewitz_critical_2023} that,
\begin{equation}
\label{eq:lb16}
\P^K_{\ba,L,\Cr{delta_dist}}(A(K,\ba,N))\geq \bar\P^K_N(G)\geq \bar\E^K_N\big[ \bar\P^K_N(G\,|\,\I^{u,1})1_{G_s'}\big].
\end{equation}
We will bound $ \bar\P^K_N(G_s')$ for a suitable $s$ and $ \bar\P^K_N(G\,|\,\I^{u,1})$ on $G_s'$ separately from below.

