\begin{equation} \label{eq:inf-sa-exact}
\mathrm{vol}(\IB_{\infty,\beta}^n)
=2^{d_n}(2\pi)^{\beta n(n-1)/4}\prod_{j=0}^{n-1}\frac{\Gamma( 1+j\frac{\beta}{2})^2\Gamma( (j+1)\frac{\beta}{2} )}{\Gamma( 2+(n+j-1)\frac{\beta}{2} )\Gamma( j\frac{\beta}{2} )}.
\end{equation}
For general $1\le p\le \infty$, exact volumes are unknown and instead their asymptotic behavior has been studied. Saint Raymond \cite{SR84} derived $A(p)>0$ such that, for $\beta\in\{1,2\}$, 
\begin{equation} \label{eq:sim-asym}
\lim_{n\to \infty}n^{1/2+1/p}\mathrm{vol}(B_{p,\beta}^n)^{1/\beta n^2}
=\sqrt{\frac{2\pi}{\beta}}e^{3/4}A(p)
\end{equation}
and determined $A(2)=e^{-1/4}$ and $A(\infty)=\frac{1}{2}$. Gu\'{e}don and Paouris \cite{GP07} showed that $\mathrm{vol}(B_{p,4}^n)^{1/4 n^2}$ and $\mathrm{vol}(\mathbb{B}_{p,\beta}^n)^{1/d_n}, \beta\in\{1,2,4\}$ are of the same order $n^{-1/2-1/p}$. Kabluchko, Prochno and Thäle \cite{KPT20a} determined
\begin{equation} \label{eq:delta}
A(p)
=\frac{1}{2}\bigg(\frac{p\sqrt{\pi}\Gamma(\frac{p}{2})}{\sqrt{e}\Gamma(\frac{p+1}{2})}\bigg)^{1/p}
\end{equation}
and moreover showed in \cite{KPT20b} that, for $\beta\in \{1,2,4\}$,
\begin{equation} \label{eq:sim-sym}
 \lim_{n\to \infty}n^{1/2+1/p}\mathrm{vol}(\mathbb{B}_{p,\beta}^n)^{1/d_n}
 =\sqrt{\frac{4\pi}{\beta}}e^{3/4}A(p).
\end{equation}
We remark that one way to see that $A(p)$ is decreasing in $p$ is to observe that the same is true for the normalized volume $\mathrm{vol}(n^{1/p}\mathbb{B}_{p,\beta}^n)$. Recently, Dadoun, Fradelizi, Gu\'{e}don and Zitt \cite[Remark 4.8]{DFG+23} showed \eqref{eq:sim-asym} for $\beta=4$. Thus, the asymptotics in \eqref{eq:sim-asym} and \eqref{eq:sim-sym} hold in all cases $\beta\in \{1,2,4\}$ and $1\le p\le \infty$.

In case of $p<\infty$, the quantity $A(p)$ in \eqref{eq:delta} can be expressed as 
\[
A(p)
=\frac{1}{2}\Big(\frac{p\sqrt{\pi}\Gamma(\frac{p}{2})}{\sqrt{e}\Gamma(\frac{p+1}{2})}\Big)^{1/p}
=\frac{1}{2}\Big(\frac{1}{\sqrt{e}\alpha_p}\Big)^{1/p},
\]
where $\alpha_p=\int_{\mathbb{R}} |x|^p\mathrm{d}\mu_p(x)$ is the $p$-th absolute moment of the Ullman distribution $\mu_p$ which has density
\begin{equation} \label{eq:ullman-1}
f_p(x)
= \frac{p}{\pi}\int_{|x|}^1 \frac{t^{p-1}}{\sqrt{t^2-x^2}}\mathrm{d} t, \qquad x\in [-1,1].
\end{equation}

Our main contribution is the following asymptotic expansion for the logarithmic volume $\ln \mathrm{vol}(\mathbb{B}_{p,\beta}^n)$. Recall that the differential entropy of a probability measure $\mu$ on $\mathbb{R}$ is
\[
\mathrm{Ent}(\mu)
= -\int_{\mathbb{R}}\ln(f(x))f(x)\mathrm{d} x, 
\]
whenever $\mu$ admits a Lebesgue density $f$ and $\mathrm{Ent}(\mu)=-\infty$ otherwise.

\begin{equation} \label{eq:sim-asym}
\lim_{n\to \infty}n^{1/2+1/p}\vol(B_{p,\beta}^n)^{1/\beta n^2}
=\sqrt{\frac{2\pi}{\beta}}e^{3/4}A(p)
\end{equation}

\begin{equation} \label{eq:sim-sym}
	\lim_{n\to \infty}n^{1/2+1/p}\vol(\bpb)^{1/d_n}
	=\sqrt{\frac{4\pi}{\beta}}e^{3/4}A(p).
\end{equation}

