theorem.content:
[\cite{HooshKoh2025}]
A nontrivial finite group $G$ satisfies the strong CFS property if and only if $G$ is either
\begin{itemize} 
  \item a cyclic group of prime order, or
  \item one of the four groups $C_4$, $C_2^2$, $C_2^3$, or $C_3^2$.
\end{itemize}

ref_dict.lemma:main:
\begin{lemma}
\label{lemma:main}
Let $H$ be a proper subgroup of a finite group $G$ with $\lvert H\rvert \ge 5$.
Choose $h_0\in H$ with $h_0\neq e$ and choose $g\in G\setminus H$.
Let $h_1$ be an element of $H$ not in the set
$\{e,h_0,h_0^{-1}\}$,
and set
\[
H'= H\setminus\{e,h_0\}.
\]
Define
\begin{equation}\label{equ:subset-not-factor}
A= H'\cup\{g,h_1g\}.
\end{equation}
Then $\lvert A\rvert = \lvert H\rvert$ and $A$ is not a left factor of $G$.
\end{lemma}

ref_dict.lemma:groups of order 8:
\begin{lemma}
\label{lemma:groups of order 8}
Let $G$ be a group of order $8$, and let $a,b\in G$ be two elements of order $4$ with $\langle a\rangle\neq\langle b\rangle$.
Then
\[
  A = \{a,a^2,a^3,b\}
\]
is not a left factor of $G$.
\end{lemma}

ref_dict.lemma:small subset:
\begin{lemma}
\label{lemma:small subset}
\begin{enumerate}[label=\textup{(\roman*)}]\!
    \item Let $G$ be a group of even order, and let $a\in G$, $a\neq e$. 
    The subset $\{e,a\}$ is a factor of $G$ if and only if the order of $a$ is even.
    \item Let $G$ be an elementary abelian $2$-group.
    Every subset of size $4$ is a factor of $G$.
    \item\,Let $G$ be an elementary abelian $3$-group.
    Every subset of size $3$ is a factor of $G$.
\end{enumerate}
\end{lemma}

post_theorem_intro_text:
The authors of \cite{HooshKoh2025} used Cayley graph arguments to constrain the possible orders of $G$, 
reducing the classification to an examination of about twenty concrete groups. In this paper, we offer a 
streamlined proof of the "only if" direction, which breaks down into four independent steps:
\begin{enumerate}[label=(\arabic*)]
  \item Analysis of groups with "large" proper subgroups (Lemma \ref{lemma:main});
  \item Groups of even order containing elements of odd order (Lemma \ref{lemma:small subset});
  \item Investigation of groups of order $8$ (Lemma \ref{lemma:groups of order 8});
  \item A direct check for the three remaining groups: $D_4$, $C_8$, and $C_9$.
\end{enumerate}

\vspace{1ex}
\noindent\textbf{Notation.} Throughout, $G$ is a finite group with identity $e$. For any $A \subseteq G$ and $x \in G$, we denote $Ax = \{ax \mid a \in A\}$. We write $\langle g \rangle$ for the cyclic subgroup generated by $g$. A subset $A$ is a \textit{left factor} if $G = \bigsqcup_{b \in B} Ab$ for some $B \subseteq G$. 

With these conventions in place, we turn in Section \ref{section:lemmas} to our lemmas, 
and then in Section \ref{section:proof theorem} to the completion of the proof.

