However, determining whether a given algebra satisfies these finiteness conditions remains a challenging problem in general. In this paper, we investigate these finiteness conditions in module categories and derived categories for two important classes of algebras, namely, gentle algebras introduced in \cite{AH81,AS-tilting-cotilting-equ} and their generalizations, skew-gentle algebras first defined in \cite{GeissdelaPena}. The representation theory of these algebras has been extensively studied, and both their module categories and derived categories admit rich and explicit combinatorial structures. Recent developments have shown that geometric surface models provide an effective framework for describing these structures for gentle algebras; see, for example, \cite{B16, HKK17, OPS18, LP20, BC21, CJS22, JSW23, C25}, as well as for skew-gentle algebras; see, for example, \cite{AB22, LSV22, QZZ22, HZZ23, AP24, CK24, BSW24}. More precisely, indecomposable objects in their module and derived categories can be interpreted as curves on a marked surface, while morphisms correspond to intersections of curves, Auslander--Reiten translations are realized by suitable rotations, and certain categorical reductions can be described by cutting the surface. This geometric perspective has proved to be particularly powerful in studying homological and representation-theoretic properties of (skew-)gentle algebras.

A finite-dimensional algebra is said to be \emph{$\tau$-tilting finite} (see Definition~\ref{def::tau-tilt-finite}) if it admits only finitely many $\tau$-tilting modules up to isomorphism. Our first main result provides a characterization of $\tau$-tilting finiteness for skew-gentle algebras, extending and generalizing the result for gentle algebras established in \cite{P19}.

\begin{Def}\label{def::tau-tilt-finite}
A finite-dimensional $\Bbbk$-algebra $A$ is called \emph{$\tau$-tilting finite} if it admits only finitely many $\tau$-tilting modules up to isomorphisms, and \emph{$\tau$-tilting infinite} otherwise.
\end{Def}

\begin{theorem}\label{theo::main-result-skew-gentle}
Let $A$ be a skew-gentle algebra. Then, $A$ is $\tau$-tilting finite if and only if $A$ is representation-finite, or equivalently, $A$ admits no band.
\end{theorem}

A finite-dimensional algebra is said to be \emph{$\tau$-tilting finite} (see Definition~\ref{def::tau-tilt-finite}) if it admits only finitely many $\tau$-tilting modules up to isomorphism. Our first main result provides a characterization of $\tau$-tilting finiteness for skew-gentle algebras, extending and generalizing the result for gentle algebras established in \cite{P19}.

To prove Theorem \ref{thm::1.1}, we make use of the complete classification of indecomposable modules over a skew-gentle algebra in terms of asymmetric and symmetric strings and bands (Section \ref{section:skew-gentle}). This classification was first obtained in \cite{CB-skew-gentle} for the local algebra $\Bbbk \langle \epsilon, \alpha \mid \epsilon^2=\epsilon,\ \alpha^2=0 \rangle$, and was subsequently extended to arbitrary clannish algebras in \cite{CB-skew-gentle-2}, see also \cite{B91,Deng00,Hansper-thesis}.

\begin{theorem}[Theorem \ref{Thm:siltingdiscreteforskewgentle}]\label{Thm:Amain3}
Let $A$ be a graded skew-gentle algebra with surface model $(S,O,\eta,\Delta)$. Consider the following conditions.
 \begin{enumerate}
 \item $\per(A)$ is silting-discrete.
 \item $S$ is of genus $0$ and $\# O\le 1$. Moreover, $\omega_\eta(\gamma)\neq 0$ for any simple closed curve $\gamma$.
 \item $S$ is of genus $0$ and 
 \[ \sum_{j\in J}m_j\not=2 \mbox{ for all $J\subset\{1,2,\ldots,b\}$,} \] 
 where $m_i=\omega_\eta(\partial_i)+2$ for $1\le i\le b$. 
 \end{enumerate}
 Then (1) implies (2), and (2) is equivalent to (3).
\end{theorem}
To prove Theorem \ref{Thm:Amain3}, we use a similar strategy
as for Theorem \ref{thm::1.2}. However, since the endomorphism algebra of a silting object in the derived category of a graded skew-gentle algebra may no longer be skew-gentle, we cannot directly apply Theorem \ref{thm::1.1} to prove the converse direction of the above theorem by showing that the endomorphism algebra of any silting object is $\tau$-tilting finite. That is, we cannot prove that condition $(2)$ implies condition $(1)$. Nevertheless, we still expect the three conditions in Theorem \ref{Thm:Amain3} to be equivalent.

We now show that the existence of a minimal band implies that the algebra is $\tau$-tilting infinite. We begin by recalling that each path algebra of extended Dynkin type is $\tau$-tilting infinite, see, for example, \cite[Theorem 3.1]{Ada-rad-square-0}.
\begin{lemma}\label{lem::S_1}
Let $\mathbf{S}_1:=\Bbbk Q/I$ be the skew-gentle algebra given by
$$
Q: \quad \vcenter{\xymatrix@C=0.8cm@R=0.3cm{
&&&&\circ\ar@{-}[r]&\cdots\ar@{-}[r]&\circ\ar@{-}[dr]&\\
1\ar@(ld,lu)^{\epsilon}\ar@{-}[r]&2\ar@{-}[r]&\cdots\ar@{-}[r] &n\ar[ur]^-{\alpha}&&&&\circ\\
&&&&\circ\ar[ul]^-{\beta}\ar@{-}[r]&\cdots\ar@{-}[r]&\circ\ar@{-}[ur]&
}}
$$
with $I=\langle \{\beta\alpha\}\cup\{ \epsilon^2-\epsilon\} \rangle$, that is $\mathsf{S}=\{\epsilon\}$. Then, $\mathbf{S}_1$ is $\tau$-tilting infinite.
\end{lemma}
\begin{proof}
If $n=1$, then $\mathbf{S}_1$ is isomorphic to the bound quiver algebra $\mathbf{S}^s_1$ given by 
$$
\vcenter{\xymatrix@C=0.9cm@R=0.5cm{
&\circ\ar@{-}[r]\ar@{.}[dd]&\circ\ar@{-}[r]&\cdots\ar@{-}[r]&\circ\ar@{-}[dr]&\\
e_1\ar[ur]^-{\alpha_1}&&e_2\ar[ul]_-{\alpha_2}&&&\circ\\
&\circ\ar[ul]^-{\beta_1}\ar[ur]_-{\beta_2}\ar@{-}[r]&\circ\ar@{-}[r]&\cdots\ar@{-}[r]&\circ\ar@{-}[ur]&
}}
$$
with $\beta_1\alpha_1=\beta_2\alpha_2$. Set $A:=e\mathbf{S}^s_1e$ with $e:=1-e_1-e_2$. Then, $A$ is $\tau$-tilting infinite since it is a path algebra of type $\tilde{\mathbb{A}}$. We conclude that $\mathbf{S}_1$ is $\tau$-tilting infinite.

\begin{lemma}\label{lem::S_2}
Let $\mathbf{S}_2:=\Bbbk Q/I$ be the skew-gentle algebra given by
$$
Q: \quad \xymatrix@C=1cm{1\ar@(ld,lu)^{\epsilon_1}\ar@{-}[r]&2\ar@{-}[r]&3\ar@{-}[r]&\cdots\ar@{-}[r] &n\ar@(ru,rd)^{\epsilon_n}}\quad (n\ge 2)
$$
with $I=\langle \epsilon^2_1 - \epsilon_1, \epsilon^2_2 - \epsilon_2 \rangle$ that is $\mathsf{S}=\{\epsilon_1, \epsilon_n\}$. Then, $\mathbf{S}_2$ is $\tau$-tilting infinite.
\end{lemma}
\begin{proof}
It is obvious that $\mathbf{S}_2$ is isomorphic to a hereditary algebra of type $\widetilde{\mathbb{D}}_{n+1}$, that is, the path algebra with any choice of orientation given by 
$$
\xymatrix@C=0.7cm@R=0.1cm{
1^+\ar@{-}[dr]&&&&&n^+\ar@{-}[dl]\\
&2&3\ar@{-}[r]\ar@{-}[l]&\cdots&n-1\ar@{-}[l]&\\
1^-\ar@{-}[ur]&&&&&n^-\ar@{-}[ul]
}.
$$
It is $\tau$-tilting infinite as shown in \cite[Theorem 3.1]{Ada-rad-square-0}.
\end{proof}

Now we are ready to state our main result in this section.
\begin{theorem}\label{theo::main-result-skew-gentle}
Let $A$ be a skew-gentle algebra. Then, $A$ is $\tau$-tilting finite if and only if $A$ is representation-finite, or equivalently, $A$ admits no band.
\end{theorem}
\begin{proof}
($\Leftarrow$) If $A$ admits no band, then it is representation-finite and hence $A$ is $\tau$-tilting finite.

