\label{Thm}
Let $\Ga$ be a connected tetravalent graph, let $(M, H)$ be a maximal $(\frac{1}{2}, t)$-pair of $\Ga$ with $t\geq1$, and let $K=\mathrm{Core}_H(M)$. Take $u\in V(\Ga)$. Then one of the followings holds.
\begin{enumerate}[\rm(a)]
\item\label{Thmcase:t=3} $t=3$, $(H/K, M/K, H_u, M_u)=(A_{72}, A_{71}, S_4\times S_3, \mz_2)$, and $\Ga$ is a cover of $\Ga_K$.
\item\label{Thmcase:t=2} $t=2$, $(H/K, M/K, H_u, M_u)= (S_5, \AGL_1(5), A_4, \mz_2)$, and $\Ga$ is a cover of $\Ga_K\cong \K_{5, 5}-5\K_2$.
\item\label{Thmcase:t=1} $t=1$, and either $M$ is normal in $H$, or $M_u^{\Ga(u)}\cong\mz_2$ is non-normal in $H_u^{\Ga(u)}\cong D_8$ such that $K$ is semiregular on $V(\Ga)$ with $|V(\Ga_K)|\neq2^\ell$ for any integer $\ell\geq0$ and one of the followings holds:
\begin{enumerate}[\rm (c1)]
\item\label{Thmcase:t=1_cover} $K$ is the kernel of $H$ acting on $V(\Ga_K)$, $\Ga$ is a cover of $\Ga_K$, and the pair $(M/K, H/K)$ is a maximal $(\frac{1}{2}, 1)$-pair of $\Ga_K$;
\item\label{Thmcase:t=1_cycle} $K$ is the kernel of $M$ acting on $V(\Ga_K)$, $\Ga_K\cong C_r$ with $r=|V(\Ga_K)|$, and $M/K\cong D_{2r}$.
\end{enumerate}
\end{enumerate}
Moreover, examples for each of the above cases exist.,

theorem.content:
\label{thm:main}
For a skew-symmetrizable matrix $B$, the following are equivalent:
\begin{itemize}
\item[$(1)$] $B$ is of finite type.
\item[$(2)$] The $g$-fan $\mathcal{F}(B)$ is complete, that is, its support $|\mathcal{F}(B)|=\mathbb{R}^n$.
\item[$(3)$] The support $|\mathcal{F}(B)|$ contains all lattice points in $\mathbb{Z}^n$.
\end{itemize}

