 \noindent to be the Rees quotient semigroup of $I(n, \,p)$, where the elements in ${RQ}_{p}(n)$ can be regarded as the elements of $\mathcal{DORP}_{n}$ that possess a height of precisely $p$. If the product of two elements from ${RQ}_{p}(n)$ has a height that does not reach $p$, then the result is $\textbf{0}$; otherwise, it is an element of ${RQ}_{p}(n) \setminus \{\textbf{0}\}$.

\[F(n,r,p)=|\{\rho\in {DRP}_n : \, b(\rho)=r \text{ and } h( \rho)=p\}|\]
\noindent and
\[F(n,p)=|\{\rho\in {DRP}_n : \, h(\rho)=p\}|.\]

Let $\rho\in{DRP}_n$ be as expressed in \eqref{2}, where $b(\rho)=r$ and $h(\rho)=p$. Moreover, let $w=\min(\dom \, \rho)$. Note that $p\leq w\leq n - p + 1$, from the proof of Lemma \ref{rev}, and for all $x_i \in \dom \, \rho$ and $a_j \in \im \, \rho$, we have $ a_j\leq x_i$. To count the number of $\rho\in{DRP}_n$, we first choose the domain elements. Now, since $w\in \dom \, \rho$, we can choose the remaining $r-1$ elements from $[n]\setminus\{1,\ldots,w\}$, i.e., in ${n - w \choose r - 1}$ ways. Next, we partition the $r$ elements in the domain into $p$ convex (modulo $\dom \, \rho$) blocks in ${r - 1 \choose p - 1}$ ways. Then, we can choose the $p$ images from the set $\{1,\ldots,w\}$ in ${w \choose p}$ ways. Finally, taking the sum of the product: ${n-w\choose r-1} {r-1\choose p-1} {w\choose p}$, from $w=p$ to $w=n-p+1$ produces
\begin{align*} F(n,r,p)&=\sum_{w=p}^{n-p+1} {n-w\choose r-1} {r-1\choose p-1} {w\choose p}\\&=
{r-1\choose p-1}\sum_{w=p}^{n-p+1} {n-w\choose r-1} {w\choose p}
\\&=
{r-1 \choose p-1} {n+1 \choose r+p}, \quad (\text{by Lemma \ref{id}})
\end{align*}
\noindent as postulated.

The number of elements in ${DRP}_n$ of a fixed height $1\le p\le \lceil\frac{n}{2}\rceil$ is
\begin{equation}\label{coo} F(n,p)= \sum_{r=p}^{n-p+1}{r-1 \choose p-1} {n+1 \choose r+p}.\end{equation}
\end{corollary}
\begin{proof}
 We get the number by varying the width within the possible range which is $p\leq r\leq n-p+1$.
\end{proof}

We will now state the following lemma.
\begin{lemma} Let $F(n,p)$ be as in \eqref{coo} and let $a_{n} = \sum\limits_{p=2}^{\lceil\frac{n}{2} \rceil} F(n, p)$. Then
\[
a_{n} = \sum\limits_{p=2}^{\lceil\frac{n}{2} \rceil} \sum_{r=p}^{n-p+1} {r-1 \choose p-1} {n+1 \choose r+p}.
\]
\end{lemma}

\noindent\textbf{(ii.)} The result follows from Remark \ref{remm}.
\end{proof}
Next, we have the following theorem.
\begin{theorem} Let $\mathcal{DORP}_{n}$ be as defined in \eqref{qn1}. Then the number of convex vital elements of height $2 \leq p\leq \lceil \frac{n}{2} \rceil$ in $\mathcal{DORP}_{n}$ is \[(n+2)\left(\left\lceil \frac{n}{2} \right\rceil-1\right)-\left(\left\lceil \frac{n}{2} \right\rceil\left(\left\lceil \frac{n}{2} \right\rceil+1\right)-2\right).\]
\end{theorem}
\begin{proof} By summing the convex vital elements in Lemma \ref{nid}(i) over $2 \leq p \leq \lceil \frac{n}{2} \rceil,$ together with some algebraic manipulations, we obtain \[\sum_{p=2}^{\left\lceil \frac{n}{2} \right\rceil} (n - 2p + 2) = (n + 2)\left(\left\lceil \frac{n}{2} \right\rceil - 1\right) - \left(\left\lceil \frac{n}{2} \right\rceil\left(\left\lceil \frac{n}{2} \right\rceil + 1\right) - 2\right).\]
\end{proof}

\begin{lemma}\label{mminknp} For $0\leq p\le n-1$,
$W(p)$ is the minimum generating set of $I(n, \,p)$.
\end{lemma}
\begin{proof} The result follows from the fact that $G(p)$ is the minimum generating set of $\langle J^{*}_{p} \rangle$ by Lemma \ref{minnn}, and also from the fact that each minimum generating set of the ideal $I(n, \,p)$ must contain all the extreme convex vital elements below height $p$, as stated in Remark \ref{extr}.
\end{proof}
\begin{lemma}\label{ooknp} Let $W(p)$ be as defined in \eqref{w}. Then \[|W(p)|=\left\{
 \begin{array}{lll}
 1, & \hbox{if $p=0$;} \\
 2^{n}-1, & \hbox{if $p=1$;} \\
 (n-2)+\sum\limits_{r=p}^{n}{\binom{n}{r}}{\binom{r-1}{p-1}}, & \hbox{if $p \in \{2, \ldots, n-1\}$.}
 \end{array}
