	\end{example}

\begin{proposition}\label{prop:ch of sym}
		With notations as above, we have
		\begin{equation*}
			\ch_n(\Schur^m E)=\sum_{\nu\vdash n}\sum_{1\leq\bbb\leq\aaa_\nu}\E(\overleftarrow{\aaa_\nu},\overleftarrow{\bbb})\binom{r+m+|\bbb|-\nu_1-1}{r+|\aaa_\nu|-1}\,\ch^{(\nu)}(E) 
		\end{equation*}
		and
		\begin{equation*}
			k_n(\Schur^m E)=\sum_{\substack{\nu\vdash n \\ \nu_1=0}}\sum_{1\leq\bbb\leq\overleftarrow{\aaa_\nu}}\E(\overleftarrow{\aaa_\nu},\overleftarrow{\bbb})\binom{r+m+|\bbb|-1}{r+|\aaa_\nu|-1}\,k^{(\nu)}(E). 
		\end{equation*}
	\end{proposition}

\begin{thm}\label{thm:Chern}
		With notations as above, we have
		\[ \ch_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\D^\nu(\schur_\alpha))\,\ch^{(\nu)}(E). \]
	\end{thm}

\begin{thm}\label{thm:k}
		With notations as above,
		\[ k_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\D^\nu(\schur_\alpha))\,k^{(\nu)}(E). \]
	\end{thm}

post_theorem_intro_text:
Let us explain the formula above:
	\begin{itemize}
		\item the sum runs over all partitions $\nu=(1^{\nu_1},2^{\nu_2},\dots)$ of the number $n$;
		\item $\schur_\alpha$ is the Schur polynomial in $\rk(E)$ variables associated to the Young diagram $\alpha$;
		\item $\mathsf{D}^\nu(\schur_\alpha)$ is the $\nu$-\emph{derived symmetric polynomial} which we define in Section~\ref{section:D};
		\item $\rk\colon\mathbb{Q}[x_1,\dots,x_r]^{\mathfrak{S}_r}\to\mathbb{Q}$ is the function associating to each Schur polynomial the dimension of the corresponding irreducible polynomial $\GL(r)$-representation;
		\item $\ch^{(\nu)}(E)=\frac{\ch_1(E)^{\nu_1}}{\nu_1!}\frac{\ch_2(E)^{\nu_2}}{\nu_2!}\cdots$ are the divided powers of the Chern character coefficients.
	\end{itemize}

	The quantity $\mathsf{D}^{\nu}(\schur_\alpha)$, which is the new ingredient in the formula, is a purely combinatorial object which is easily computed in explicit examples, see Examples~\ref{example:2} and \ref{example:3} and Proposition~\ref{prop:ch of sym}.
	\medskip

	The proof of Theorem~\ref{thm:Chern} is simple and only uses standard properties of the Chern character, such as multiplicativity and additivity. To emphasise this aspect, thus making the proof more transparent, we undress it of all the superficial structures and reduce it to a statement about polynomials in countably many variables. This is the content of our key Lemma~\ref{key lemma}, from which all the results in the paper are deduced.
	\medskip

	Notice that this abstract point of view is not only an {\em exercice de style}. The same proof in fact ensures that the result holds in any category where suitable characteristic classes can be defined. For example, it holds for proper algebraic varieties and locally free sheaves over them. Similarly, it also holds for characteristic classes valued in a Chow ring, instead of a cohomology ring. 
	As an example of characteristic classes that differs from the Chern character, we also prove the analogous statement for the \emph{twisted Chern character} 
	\[ k(F)=\exp\left(-\frac{c_1(F)}{\rk(F)}\right)\ch(F) \]
	considered in \cite{Markman} as characteristic classes of projective bundles.

	\begin{thmB}[Theorem~\ref{thm:k}]
		For any $n\geq0$, the $n^{\operatorname{th}}$ twisted Chern character coefficient of $\Schur^\alpha E$ is
		\[ k_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\mathsf{D}^\nu(\schur_\alpha))\,k^{(\nu)}(E), \]
		where the sum may be taken over the partitions of $n$ into parts that are all strictly larger than $1$.
	\end{thmB}

	In our previous work \cite{DAFOa} we proved formulas expressing $k_2(\Schur^\alpha E)$ and $k_3(\Schur^\alpha E)$ as certain multiples of $k_2(E), k_3(E)$. Theorem B reinterprets those results as 
	\begin{align*}
		k_2(\Schur^\alpha E) = & \, \rk(\D_2(\schur_\alpha)) \, k_2(E)\, , \\
		k_3(\Schur^\alpha E) = & \, \rk(\D_3(\schur_\alpha)) \, k_3(E)\, ,
	\end{align*}
	and provides generalizations to all twisted Chern character coefficients $k_n$, see \S~\ref{section:k}.

	As already mentioned, concrete formulas for the Chern character of symmetric and exterior powers were found by Svrtan in \cite{Dragutin} and Manivel in \cite[Section~2]{Manivel}. We recover those formulas in Proposition~\ref{prop:ch of sym} and Proposition~\ref{prop:ch of wedge}, and extend them to twisted Chern characters.

	The formula for the first Chern class of a Schur bundle has long been folklore knowledge, and its first rigorous proof can be found in \cite{Rubei}. We present in Corollary~\ref{corollary:Rubei} an alternative short proof. 

	\subsection*{Plan of the paper}
	The technical core of the paper is contained in \S~\ref{section:key lemma}, where the Key Lemma is proved. In \S~\ref{section:symmetric functions} we recover some important facts about the ring of symmetric functions, that will be used in \S~\ref{section:applications}, where Theorems A and B are proved. Finally, in \S~\ref{section:Sym and Wedge} we prove formulas for Chern character and twisted Chern character of symmetric and exterior powers.

	\subsection*{Acknowledgements}
	We are glad to thank Laurent Manivel for comments on a first draft of the paper.
	This research has been partially funded by the European Union - NextGenerationEU under the
