Let $R$ be an integral domain, $1\neq q\in R^\times$ and ${\mathbf Q}:=(Q_{1},Q_2,\dots, Q_{\ell})\in R^\ell$. The non-degenerate cyclotomic Hecke algebras $\HH_{\ell,n}^R(q;\mathbf{Q})$ of type $G(\ell,1,n)$ with Hecke parameter $q$ and cyclotomic parameters $Q_{1},Q_2,\dots, Q_{\ell}$ were first introduced in \cite[Definition 3.1]{AK1}, \cite[Definition 4.1]{BM:cyc} and \cite[before Proposition 3.2]{C} as certain deformations of the group ring $R[W_{\ell,n}]$ of the complex reflection group $W_{\ell,n}$ of type $G(\ell,1,n)$. By definition, $\mathscr{H}_{\ell,n}=\HH_{\ell,n}^R(q;\mathbf{Q})$ is the unital associative $R$-algebra with generators $T_0,T_1,\dots,T_{n-1}$ and the following defining relations:
\begin{align}
&(T_0-Q_1)(T_0-Q_2)\cdots(T_0-Q_\ell)=0;\\
&T_0T_1T_0T_1=T_1T_0T_1T_0;\\
\label{nondegquadraticrela}&(T_i-q)(T_i+1)=0,\quad \forall\,1\leq i\leq n-1;\\
\label{nondegbraidrela1}&T_iT_j=T_jT_i,\ \ \forall\,1\leq i<j-1<n-1;\\
\label{nondegbraidrela2}&T_iT_{i+1}T_i=T_{i+1}T_iT_{i+1},\ \ \forall\,1\leq i<n-1.
\end{align}
If $\ell=1$ or $\ell=2$, then the cyclotomic Hecke algebra $\HH_{\ell,n}^R(q;\mathbf{Q})$ becomes the Iwahori-Hecke algebra of type $A_{n-1}$ or type $B_n$ respectively.

\begin{dfn}\label{ssf} For any $w\in \Sym_n$ and integers $0\leq c_1,c_2,\dots,c_n<\ell,$ we define
$$
\tau_{R}^{\rm{MM}}(\mL_1^{c_1}\mL_2^{c_2}\cdots \mL_n^{c_n}T_w):=\begin{cases}
1, &\text{if\ \,$w=1$\ and\ $c_1=c_2=\cdots=c_n=0$},\\
0, &\text{otherwise.}
\end{cases}
$$
We extend $\tau_{R}^{\rm{MM}}$ linearly to an $R$-linear function on $\HH_{\ell,n}$.
\end{dfn}
One can show directly that the $R$-linear function $\tau_{R}^{\rm{MM}}$ is symmetric, i.e., $\tau_{R}^{\rm{MM}}(xy)=\tau_{R}^{\rm{MM}}(yx)$, $\forall\,x,y\in \HH_{\ell,n}$, see \cite{MM} and \cite{HHL}. We call $\tau_R^{\rm{MM}}$ the {\bf{standard symmetrizing form}} on $\HH_{\ell,n}$. If furthermore, $(Q_{1},Q_2,\dots, Q_{\ell})\in (R^\times)^\ell$, then by a result of Malle-Mathas \cite{MM}, the $R$-linear function $\tau_{R}^{\rm{MM}}$ on $\HH_{\ell,n}$ is non-degenerate, which makes $\HH_{\ell,n}$ into a symmetric algebra over $R$.

We use $\P_{\ell,n}$ to denote the set of $\ell$-partitions of $n$. For each $\blam\in\P_{\ell,n}$, we use $\Std(\blam)$ to denote the set of standard $\blam$-tableaux. Each $\mathfrak{t}\in\Std(\blam)$ can be viewed as a bijective map
$\mathfrak{t}: [\blam]\rightarrow\{1,2,\dots,n\}$ from the Young diagram $[\blam]:=\{(r,c,l)\mid 1\leq l\leq\ell,\ r\geq 1,\ 1\leq c\leq\lam_r^{(l)}\}$ to $\{1,2,\dots,n\}$.

In \cite{DJM}, Dipper-James-Mathas constructed a cellular basis $\{\fm_{\mathfrak{s}\mathfrak{t}}\,|\, \mathfrak{s},\mathfrak{t}\in\Std(\blam),\ \blam\in\P_{\ell,n}\}$ for $\HH_{\ell,n}$
in the sense of \cite{GL}. This basis generalizes the well-known Murphy basis for the Iwahori-Hecke algebra associated to $\Sym_n$ (i.e., the level one case). We call it {\bf the Murphy basis for the non-degenerate cyclotomic Hecke algebra $\HH_{\ell,n}$}. When $\HH_{\ell,n}$ is semisimple, Mathas also constructed a seminormal basis $\{\mf_{\mathfrak{s}\mathfrak{t}}\,|\,\mathfrak{s},\mathfrak{t}\in\Std(\blam),\ \blam\in\P_{\ell,n}\}$ for $\HH_{\ell,n}$. We refer the readers to Sections 2.1 and 3.2 for their precise definitions.

\begin{dfn}\label{keydefn} Let $k\in\mathbb N,\ \blam=(\lambda^{(1)},\dots,\lambda^{(\ell)})\in\P_{\ell,k}$ and $\mathfrak{t}\in\Std(\blam)$.
Let $1\leq k(\mathfrak{t})\leq k$ be the unique integer such that
\begin{equation*}\label{ntDef}\mathfrak{t}^{-1}(k)=(\mathfrak{t}^{\blam})^{-1}(k(\mathfrak{t})).
\end{equation*}
For each integer $1\leq j\leq n$, we let $r(\mathfrak{t},j),\,c(\mathfrak{t},j)$ and $l(\mathfrak{t},j)$ be the integers such that
\begin{equation*}\label{coordinate}
\mathfrak{t}^{-1}(j)=(r(\mathfrak{t},j),c(\mathfrak{t},j),l(\mathfrak{t},j))\in [\blam].
\end{equation*}
\end{dfn}

The following theorem is the first main result of this paper.

