\subsection{Necessary and sufficient observability/controllability condition}
Finally, we obtain the following sharp and complete geometric characterization of observable regions.
\begin{theorem}\label{thm: main-ob}
Let $T>0$ and let $G\subset [0, T]\times \T$ be a measurable set. Then the following two statements are equivalent.
\begin{itemize}
 \item[(1)] The observability inequality \eqref{eq: wave-ob} holds on $G$;
 \item [(2)] $G$ satisfies \blackhyperref{def:GCC}{{\rm (GCC)}} and does not obey \blackhyperref{def:OSC}{$({\rm OSC})$} for any non-tirvial pair ($A, B$). 
\end{itemize}
\end{theorem}

\begin{proposition}[Unique continuation implies weak GCC]
Let $T>0$ and $G\in [0, T]\times \T$. Assume that the following unique continuation property holds
$$
\mbox{ Let u be a solution of \eqref{eq: wave-eq-0} and } u_t =0 \mbox{ a.e. in } G \Longrightarrow u \equiv 0. 
$$
Then $G$ satisfies the \blackhyperref{def:weakGCC}{{\rm (weak GCC)}}. 
\end{proposition}
\begin{proof}
We argue by contradiction. Suppose that $G$ does not satisfy the \blackhyperref{def:weakGCC}{({\rm weak GCC})}, there exists a subset $A\subset \T$ such that $\mbox{meas}_\R(A)>0$ and
\begin{align*}
\mbox{meas}_\R(G\cap L_{\eta\in A})=0 \quad \mbox{ or } \quad 
 \mbox{meas}_\R(G\cap L_{\xi\in A})=0.
\end{align*}
Without loss of generality, we only consider the case
\begin{align}\label{equ-ucp-wgcc-1}
\mbox{meas}_\R(G\cap L_{\eta\in A})=0. 
\end{align}
Since $A$ has positive measure, one can find a non-zero function $\phi$ such that
\begin{align}\label{equ-ucp-wgcc-2}
 \int_A \phi(x)\d x=0, \quad \int_A|\phi| \d x=\mbox{meas}_{\R}(A)>0. 
\end{align}
Set 
$$
u_{0x}=-u_1=\chi_A \phi.
$$
This is possible since $\int_\T u_{0,x}\d x =\int_A\phi \d x =0$. Then we have
$$
\partial_\xi u|_{t=0}=u_{0x}+u_1=0, \quad \partial_\eta u|_{t=0}=u_{0x}-u_1=2\chi_A\phi.
$$
It follows that
$$
\partial_\xi u=0 \quad \mbox{ on } [0,T]\times \T
$$
and
$$
\partial_\eta u= 0 \quad \mbox{ on } L_{\eta\in \T\backslash A}.
$$
Thus we have
$$
u_t=\frac{1}{2}(\partial_\xi u-\partial_\eta u)=0 \quad \mbox{ on } L_{\eta\in \T\backslash A}.
$$
Thanks to \eqref{equ-ucp-wgcc-1}, we see $G\subset L_{\eta\in \T\backslash A}$, and thus $u_t=0$ on $G$. By the UCP, we must have $\partial_\eta u|_{t=0}=2\chi_A\phi\equiv 0$, which leads a contradiction with \eqref{equ-ucp-wgcc-2}.
\end{proof}

\subsection{OSC and weak GCC imply unique continuation }\label{sec: OSC+WGCC>UCP}
In this sequel, we generalize the result in Proposition \ref{prop-ucp-S2}, which forms the following proposition.
\begin{proposition}[Weak GCC implies UCP up to $\mathcal{S}^2$]\label{prop-weakGCC-ucp-S2}
 Let $T>0$. Let $G\in [0, T]\times \T$ satisfy the \blackhyperref{def:weakGCC}{{\rm (weak GCC)}}.
 If $u$ solves the wave equation \eqref{eq: wave-eq-0} and $u_t = 0$ on $G$, then its initial state $(\partial_\xi u, \partial_\eta u)|_{t=0}$ belongs to the symmetry function pair class $\mathcal{S}^2$.
\end{proposition}
\begin{proof}
We use the same notation in the proof of Proposition \ref{prop-ucp-S2}. Recall that we have the relation \eqref{equ-xi-eta-exchange}, namely 
\begin{equation*} \partial_{\eta}u|_{\{t= 0\}\cap L_{\eta= \eta_0}}=\partial_{\eta}u(\xi_0,\eta_0)= \partial_{\xi}u|_{\{t= 0\}\cap L_{\xi\in \mathcal{U}_{\eta= \eta_0}}}
\end{equation*}
up to sets with zero measure.
Namely, the value of $\partial_{\eta}u(\xi_0,\eta_0)$ determines almost every value of $\partial_{\xi}u|_{\{t= 0\}\cap L_{\xi\in \mathcal{U}_{\eta= \eta_0}}}$. Since $G$ satisfies the \blackhyperref{def:weakGCC}{({\rm weak GCC})}, we know 
$$
\mbox{meas}_\R(\{t= 0\}\cap L_{\xi\in \mathcal{U}_{\eta= \eta_0}})>0.
$$
In other words, $\partial_{\xi}u|_{\{t= 0\}}$ equals to $\partial_{\eta}u(\xi_0,\eta_0)$ at least on a positive measure subset set of $\T$. Thus the set
$$
\mathcal{U}_{(\xi_0,\eta_0)}:=\{x_0\in \T: \partial_{\xi}u|_{\{t= 0,x=x_0\}}=\partial_{\eta}u(\xi_0,\eta_0)\}
$$
has positive measure. Repeating this process for other point $(\xi_0',\eta_0')\in [0,T]\times \T$, we shall find that, there exists a family sets $\mathcal{U}_\ell (\ell\in I)$, $I$ is a index set, such that
\begin{align}\label{equ-Ul-129}
 \mathcal{U}_\ell\cap \mathcal{U}_{\ell'}=\emptyset \mbox{ for } \ell\neq \ell', \quad \mbox{meas}_\R(\mathcal{U}_\ell)>0 \mbox{ for } \ell\in I , \quad \T=\cup_{\ell\in I}\mathcal{U}_\ell 
\end{align} 
and $\partial_{\xi}u|_{\{t= 0\}}$ is a constant on each $\mathcal{U}_\ell$.
One can show that, under the restrictions \eqref{equ-Ul-129}, the index set $I$ is at most countable, thus, after relabeling if necessary, $\{\mathcal{U}_\ell, \ell\ge 1\}$ is a weak decomposition of $\T$. Moreover, there exists a sequence of different numbers $\{s_\ell\}$ such that
$$
\partial_{\xi}u|_{\{t= 0\}}=s_\ell \mbox{ on } \mathcal{U}_\ell.
$$
Note that $\partial_{\xi}u|_{\{t= 0\}}\in L^2(\T)$, and $\mathcal{U}_\ell$ are disjoint for different $\ell$, we find
$$
\|\partial_{\xi}u|_{\{t= 0\}}\|_{L^2(\T)}^2=\sum_\ell |s_\ell|^2\mbox{meas}_\R(\mathcal{U}_\ell)<\infty.
$$
Thus we obtain
$$
\partial_{\xi}u|_{\{t= 0\}} = \sum_{\ell\geq 1} s_\ell \chi_{\mathcal{U}_\ell} \quad \mbox{ in } L^2(\T).
$$
Similarly, we can find a weak decomposition $\mathcal{V}_{\ell}(\ell\geq 1)$ such that
$$
\partial_{\eta}u|_{\{t= 0\}} = \sum_{\ell\geq 1} s_\ell \chi_{\mathcal{V}_\ell} \quad \mbox{ in } L^2(\T).
$$
In summary, we find that $(\partial_{\xi}u|_{\{t= 0\}}, \partial_{\eta}u|_{\{t= 0\}})\in \mathcal{S}^2$.
\end{proof}

The following theorem gives a sufficient and necessary condition of the observable set for the transport equation. We only state the result for \eqref{eq: transport-eq}, the reader easily figures out the the necessary modifications for \eqref{eq: transport-eq-2}.
\begin{theorem}\label{thm-tran-suff-nece}
Let $T>0$ and $G$ be a measurable subset of $[0,T]\times \T$ with positive measure. Then the observability inequality
\begin{align}\label{equ-tran-suff-necc-1}
 \|u_0\|^2_{L^2(\T)}\leq C\int_G|u(t,x)|^2\d x \d t 
\end{align}
holds with a positive constant $C>0$ for all solutions to the transport equation \eqref{eq: transport-eq} if and only if there exists a constant $c_0>0$ such that 
\begin{equation}\label{equ-tran-suff-necc-2}
\int_0^T\mathbf{1}_G(s,x- s)\d s\geq c_0 \quad \mbox{ for a.e. } x\in\T 
\end{equation}
\end{theorem}
\begin{proof}
The direction $\eqref{equ-tran-suff-necc-2}\Longrightarrow \eqref{equ-tran-suff-necc-1}$ follows clearly from Proposition \ref{prop: tran-eq-ob}. To show the inverse direction, namely $\eqref{equ-tran-suff-necc-1}\Longrightarrow \eqref{equ-tran-suff-necc-2}$, we use the contradiction argument. Suppose that \eqref{equ-tran-suff-necc-2} is not true, then for any $\varepsilon>0$, there exists a set $E_\varepsilon\subset \T$ with positive measure $|E_\varepsilon|>0$ such that
\begin{align}\label{equ-tran-suff-necc-3} 
\int_0^T\mathbf{1}_G(s,x- s)\d s<\varepsilon \quad \mbox{ for a.e. } x\in E_\varepsilon. 
\end{align}
Let $u_{0\varepsilon}(x)=1_{E_\varepsilon}(x)$. Then $u_{0\varepsilon}\in L^2(\T)$ and its support is contained in $E_\varepsilon$. Then, similar to the proof in Proposition \ref{prop: tran-eq-ob}, we have
\begin{align*}
\int_G|u(t,x)|^2\d x \d t =\int_{\T}|u_{0\varepsilon}(x)|^2\int_{\T}\mathbf{1}_G(t,x-t)\d t\d x\leq \varepsilon \|u_{0\varepsilon}\|^2_{L^2(\T)}. 
\end{align*}
Taking $\varepsilon>0$ small enough, say $\varepsilon=C/2$, we obtain a contradiction with \eqref{equ-tran-suff-necc-1}. 
\end{proof}
