\begin{example}\label{simple-ex}
Let $A$ be a finite simple group. The Schur multiplier $H_2(A;\mathbb{Z})$ has odd order precisely in the following cases:
\begin{itemize}
\item[(1).] Cyclic groups: $\mathbb{Z}/p$ with $p$ a prime number;
\item[(2).] Groups of Lie type (with $q=p^k$ for a prime number $p$ and positive $k$):
  \begin{itemize}
  \item Chevalley groups: 
     \begin{itemize} 
     \item[(Ch1).] linear groups $A_n(q)$ with $(n+1,q-1)$ odd and $(n, q)\neq (1, 4)$, $(2, 2)$, $(2, 4)$, $(3, 2)$; 
     \item[(Ch2).] orthogonal groups $B_n(q)$ with $n>1$, $q$ even and $(n, q)\neq (2, 2)$, $(3, 2)$; 
     \item[(Ch3).] symplectic groups $C_n(q)$ with $n>2$, $q$ even and $(n, q)\neq (3, 2)$; 
     \item[(Ch4).] orthogonal groups $D_n(q)$ with $n>3$, $(4,q^n-1)=1$ and $(n, q)\neq (4, 2)$; 
     \item[(Ch5).] $E_6(q)$; 
     \item[(Ch6).] $E_7(q)$ with $q$ even; 
     \item[(Ch7).] $E_8(q)$; 
     \item[(Ch8).] $F_4(q)$ with $q\neq 2$;
     \item[(Ch9).] $G_2(q)$ with $q\neq 4$;
     \end{itemize}
 \item Steinberg groups: 
   \begin{itemize} 
     \item[(S1).] unitary groups ${}^{2}A_n(q^2)$ with $n>1$, $(n+1,q+1)$ odd and $(n, q)\neq (3, 2)$, $(5,2)$; 
     \item[(S2).] orthogonal groups ${}^{2}D_n(q^2)$ with $n>3$, $(4,q^n+1)=1$; 
     \item[(S3).] ${}^{2}E_6(q^2)$ with $q\neq 2$;
     \item[(S4).] ${}^{3}D_4(q^3)$;
     \end{itemize}
 \item Suzuki groups: ${}^{2}B_2(2^{2n+1})$ with $n\geq 2$;
  \item Ree groups and Tits group: 
    \begin{itemize} 
     \item[(R1)] Ree groups ${}^{2}F_4(2^{2n+1})$ with $n\geq 1$; 
     \item[(R2)] Tits group ${}^{2}F_4(2)'$;
     \item[(R3)] Ree groups ${}^{2}G_2(3^{2n+1})$ with $n\geq 1$;
     \item[(R4)] the derived group ${}^{2}G_2(3)'$;
     \end{itemize}
     \end{itemize}
\item[(3).] Sporadic groups:
  \begin{itemize}
  \item Mathieu groups:   
     \begin{itemize} 
     \item[(M1)] $M_{11}$;
     \item[(M2)] $M_{23}$;
     \item[(M3)] $M_{24}$;
     \end{itemize}
  \item Janko groups:   
     \begin{itemize} 
     \item[(J1)] $J_{1}$;
     \item[(J2)] $J_{3}$;
     \item[(J3)] $J_{4}$;
     \end{itemize}
  \item Conway groups:   
     \begin{itemize} 
     \item[(C1)] $Co_{2}$;
     \item[(C2)] $Co_{3}$;
     \end{itemize}
  \item Fischer groups:
    \begin{itemize} 
     \item[(F1)] $Fi_{23}$;
     \item[(F2)] $Fi_{24}'$;
     \end{itemize}
  \item McLaughlin group: $McL$;
  \item Held group: $He$;
  \item O'Nan group: $O'N$;
  \item Harada-Norton group: $HN$;
  \item Lyons group: $Ly$;
  \item Thompson group: $Th$;
  \item Fischer-Griess Monster group, $M$.
   \end{itemize}
\end{itemize}
\end{example}

ref_dict.4-thm-intro:
\begin{theorem}\label{4-thm-intro}
Let \(M\) be an almost flat orientable \(4\)-manifold. Then \(M\) bounds a spin\(^c\) manifold. Furthermore, if \(M\) is spin, then \(M\) with any spin structure bounds a spin manifold.
\end{theorem}

ref_dict.G-thm-intro:
\begin{theorem}\label{G-thm-intro}
Let \(M\) be an almost flat oriented manifold with holonomy group \(G\).
If the Schur multiplier of \(G\) is of odd order, then \(M\) bounds a compact manifold.  

In particular, if the \(2\)-Sylow subgroup of \(G\) is cyclic, generalized quaternionic, or coincides with the \(2\)-Sylow subgroup of any finite simple group listed in Example~\ref{simple-ex}, then \(M\) is the boundary of a compact manifold.
\end{theorem}

