The main theorem of this paper is as follows.

For each capillary convex body $\widehat{\S}$, by \eqref{measure} we introduce a \textit{$k$-th capillary area measure} on $\C_{\theta}$, which is given by \begin{eqnarray}\notag
 dS_k^c \coloneqq \ell\sigma_{k}(\n^{2}h+h\sigma)d\mathcal{H}^{n}, ~~~0\leq k\leq n,
 \end{eqnarray} 
 where $$\ell(\xi) \coloneqq \sin^{2}\theta+\cos\theta\<\xi, e\>,$$ and $h$ is the support function of $\S$. In particular, when $\theta=\frac \pi 2$, $dS_k^c$ coincides with the classical $k$-th area measure for the convex body, see for instance \cite[Section 5.1]{Sch}. The main goal of this paper is to identify a capillary convex body $\widehat{\S}$, such that the $k$-th capillary area measure is prescribed on $\C_{\theta}$. We formulate the problem as follows.

It is worth noting that, compared to the definition of homotopy given in \cite[Definition 1.1]{GM}, our setting includes an additional requirement: a Neumann boundary condition will be imposed. This condition plays a crucial role in establishing the constant rank theorem for ensuring the convex solutions of Eq. \eqref{eq-k}.

\

In this section, we establish the a priori estimates for the strictly convex solution of Eq. \eqref{eq-k}. 
For any solution $h$ to Eq. \eqref{eq-k}, it is easy to verify that 
\begin{eqnarray*}
 h(\xi)+\<\xi,E_\alpha\> ,\quad \text{ for all } 1\leq \a\leq n,
\end{eqnarray*} is still a solution. Up to a horizontal translation, we assume $h$ satisfies the following orthogonal condition:
\begin{eqnarray}\label{orth cond}
 \int_{\C_\theta} h(\xi) \<\xi,E_\alpha\> d\H^{n}=0, \quad \text{ for all } 1\leq \a\leq n.
\end{eqnarray}
Under the condition \eqref{orth cond}, we are able to establish the following a priori estimates.
\begin{thm}\label{priori estimate}
Let $\theta\in (0, \frac{\pi}{2})$. Suppose that $h$ is a strictly convex solution of Eq. \eqref{eq-k} and satisfies the condition \eqref{orth cond}. For any integer $m\geq 2$ and $\gamma\in(0,1)$, there exists a constant $C>0$ depending on $n, k,$ $\min\limits_{\C_{\theta}} f$ and $\|f\|_{C^{m}(\C_\theta)}$, such that
 \begin{eqnarray}\label{sch est}
 \|h\|_{C^{m+1,\gamma}(\C_\theta)}\leq C.
 \end{eqnarray}
\end{thm}

\begin{lem}\label{c0 est}
Let $\theta\in(0, \pi)$ and $h$ be a strictly convex solution of Eq. \eqref{eq-k} that satisfies \eqref{orth cond}. 
Then there exists a positive constant $C$ depending on $n, \min\limits_{\C_{\theta}}f$, and $\max\limits_{\C_\theta} f$, such that
\begin{eqnarray*}
 0<\min_{\C_\theta} h\leq \max_{\C_\theta} h\leq C.
\end{eqnarray*} 
\end{lem}
\begin{proof} 
First of all, due to \eqref{orth cond}, by \cite[Lemma 3.1]{MWW-AIM}, we have $h>0$ and the origin lies in the interior of $\widehat{\partial\Sigma}$. 
Let $R_{0}>0$ be the smallest number of $R$ such that 
 \begin{eqnarray}\label{enclosed}
 \widehat \S\subset \widehat{R\C_\theta},
 \end{eqnarray}where $R\C_\theta\coloneqq \{\xi \in \ov{\RR^{n+1}_+}: |\xi-\cos\theta R e|=R\}$. It is clear that there exists $X_0\in \Sigma \cap R_0\C_{\theta } $. Denote $\widehat{X}_0\coloneqq \frac{X_0 }{R_0}\in \C_\theta$.
For any $\xi \in \C_\theta$, we have 
 \begin{eqnarray}\label{lower bdd of h}
 h(\xi)&=&\max_{Y\in \S}\<\xi-\cos\theta e, Y\>\notag \\
 &\geq& \max \left\{0, \<\xi-\cos\theta e,X_0\> \right\}\notag \\
 &=& \max \left\{0, R_0\<\xi-\cos\theta e,\widehat X_0\> \right\}.
 ~~~\end{eqnarray} 
Multiplying $f$ on both sides of \eqref{lower bdd of h} and integrating over $ \C_\theta$, we see
\begin{eqnarray}\label{R1}
 R_0\leq \left(\int_{\C_\theta}h(\xi)\cdot f(\xi)d \H^{n}\right) \left(\int_{\C_\theta}\max \left\{0, \<\xi-\cos\theta e,\widehat X_0\> \right \}\cdot f(\xi) d \H^{n}\right) ^{-1}.
\end{eqnarray}
Note that 
\begin{eqnarray}\label{R2}
 \int_{\C_{\theta}}h(\xi)\cdot f(\xi) d \H^{n}=
\int_{\tilde{\nu}(\Sigma)}h(\xi)\cdot f(\xi)d\H^{n}=\int_{\S}\<X, \nu\>\sigma_{n-k}(\kappa)d\mu.
\end{eqnarray}
Together with the Alexandrov-Fenchel inequalities for convex capillary hypersurfaces \cite[Theorem~1.2]{MWWX} for $\theta\in(0, \pi)$ and the Minkowski formulas for capillary hypersurfaces \cite[Proposition~2.6]{WWX22}, we obtain
\begin{eqnarray}
 C_{n, k}\left(\int_{\S}\<X, \nu\>\sigma_{n-k}(\kappa)d\mu\right)^{\frac{1}{k+1}}&\leq& \left(\int_{\Sigma}\<X, \nu\>\sigma_{n-k+1}(\kappa)d\mu\right)^{\frac{1}{k}}\notag \\
 &=&\left(\frac{k}{n-k+1}\int_{\C_{\theta}}f(\xi)d\H^{n}\right)^{\frac{1}{k}}.\label{R3}
\end{eqnarray}
Together with \eqref{R1}, \eqref{R2} and \eqref{R3}, we conclude that 
\begin{eqnarray}
 R_{0}
 &\leq& C_{n,k}\left(\int_{\C_{\theta}}f(\xi)d\H^{n}\right)^{\frac{k+1}{k}}\cdot\left(\inf\limits_{\eta\in \C_{\theta}}\int_{\C_\theta}\max\{0, \<\xi-\cos\theta e, \eta\>\}\cdot f(\xi) d \H^{n}\right) ^{-1}.\quad ~~~\label{upper bound of R0}
\end{eqnarray}
Using \eqref{enclosed} and \eqref{upper bound of R0}, we see 
\begin{eqnarray*}
 h(\xi) =\<\xi-\cos\theta e , \tilde{\nu}^{-1}(\xi)\>\leq |\tilde{\nu}^{-1}(\xi)| <2R_0\leq C(n, \min_{\C_\theta} f,\max_{\C_\theta} f).
\end{eqnarray*}
 We complete the proof of Lemma \ref{c0 est}.
\end{proof}
\subsection{\texorpdfstring{$C^1$ }{}estimate}
 In this subsection, we get the gradient estimate for the strictly convex solution $h$ of Eq. \eqref{eq-k}. This estimate is a direct consequence of the convexity and the $C^{0}$ estimate.
\begin{lem}\label{C1 est}
 Let $\theta\in (0, \pi)$, and let $h$ be a strictly convex solution of Eq. \eqref{eq-k}. Then \begin{eqnarray}\label{gradient ps}
 \max\limits_{\C_{\theta}} |\n h|\leq C,
 \end{eqnarray}
 where the constant $C$ only depends on $\|h\|_{C^{0}(\C_{\theta})}$.
\end{lem}
\begin{proof}
 Consider the function
 \begin{eqnarray*}
 P=|\n h|^{2}+h^{2}.
 \end{eqnarray*}
Suppose that $P$ attains its maximum value at some point, say $\xi_{0}\in \C_{\theta}$. If $\xi_{0}\in \C_{\theta}\setminus \partial\C_{\theta}$, by the maximal condition, we have
\begin{eqnarray*}
 0=\n_{e_i}P=2h_{k}h_{ki}+2hh_{i},\quad \text{for}~1\leq i\leq n.
\end{eqnarray*}
Since $h$ is a strictly convex function, we have $\n h(\xi_{0})=0$. Combining with Lemma \ref{c0 est}, we conclude that \eqref{gradient ps} holds.

\section{Convexity}\label{sec-convex}
The primary goal of this section is to obtain a strictly convex solution of Eq. \eqref{eq-k}. Based on the celebrated result of Guan-Ma \cite{GM} and with suitable assumptions on the function $f$, we show that the convex solution of Eq. \eqref{eq-k} is strictly convex. To begin with, we establish the following key lemma.
\begin{lem}\label{lem-def}
 Let $\theta\in (0, \frac{\pi}{2})$ and $\tilde{F}(W) \coloneqq \sigma_{k}(W)$. Suppose that $h\in C^{2}(\C_{\theta})$ is a solution of Eq. \eqref{eq-k}, and assume that $W$ is positive semi-definite on $\C_\theta$. Suppose there exists a positive constant $C_{0}$ such that for a fixed integer $l $ $(k\leq l\leq n-1)$, $\sigma_{l}(W)\geq C_{0}$ for all $\xi\in \C_{\theta}$. If $f\in \mathcal{L}_{-\frac{1}{k}}$ and $\n_{\mu}f\geq 0$ on $\partial \C_{\theta}$, denote $$\phi\coloneqq \sigma_{l+1}(W(\xi)),$$ then there exist constants $C_{1}, C_{2}$ depending only on $n, k, C_{0}, \|h\|_{C^{3}},$ and $\|f\|_{C^{2}}$, such that $\phi$ satisfies 
 \begin{eqnarray}
 & \tilde{F}^{ij}\phi_{ij}\leq C_{1}|\n \phi|+C_{2}\phi, & \quad \rm{in} ~~ \C_{\theta} ,\label{Diff-ine}\\
 &\n_{\mu} \phi\geq 0, & \quad {\rm{on}}~\partial \C_{\theta}.\label{boundary ine}
 \end{eqnarray}
 \end{lem}
 \begin{proof}
 The differential inequality \eqref{Diff-ine} follows from \cite[Lemma~4.1]{GM} and $f\in \mathcal{L}_{-\frac{1}{k}}$. We just need to prove the boundary condition \eqref{boundary ine}.

