Throughout we suppose that $\Omega$ is a connected bounded open subset of $\RR^d$, $d\ge 2$, with boundary $\partial\Omega$.
Given a function $\phi\in C(\partial\Omega)$, the \emphdef{Dirichlet problem} asks to
\begin{equation}
 \tag*{$D(\varphi)$}
 \label{eq:D}
 \left\{
 \begin{aligned}
 &\text{find $u\in C(\clos{\Omega})$ which is harmonic on $\Omega$} \\
 &\text{such that $\restrict{u}{\partial\Omega}=\phi$.}
 \end{aligned}
 \right.
\end{equation}
We call such a function $u$ a \emphdef{classical solution} of~\ref{eq:D}.
However, a classical solution does not always exist.

In this section we develop variational solutions of the Dirichlet problem on the basis of the following result~\cite[Corollary~4.3]{AtES24}.
\begin{thm}[Extension result]\label{thm:2.1}
Let $\phi\in C(\partial\Omega)$. Then there exist an extension $\Phi\in C(\clos{\Omega})$ of $\phi$ and $M \ge 0$ such that
\begin{equation}\label{eq:2.1}
 \abs*{\int_\Omega\Phi\Delta w\dx} \le M\norm{w}_{H^1(\Omega)}
\end{equation}
for all $w\in C^\infty_\cpt(\Omega)$. This means that $\Delta\Phi\in H^{-1}(\Omega)$, the dual space of $H^1_0(\Omega)$.
\end{thm}
Note that for $u\in H^1(\Omega)$ one has
\[
 \abs*{\int_\Omega u\Delta w\dx} = \abs*{-\int_\Omega\nabla u\nabla w\dx}\le\norm{u}_{H^1(\Omega)}\norm{w}_{H^1(\Omega)}
\]
for all $w\in C^\infty_\cpt(\Omega)$ and therefore $\Delta u\in H^{-1}(\Omega)$.

Let $\phi\in C(\partial\Omega)$ and $\Phi\in C(\clos{\Omega})$ be an extension of $\phi$ satisfying~\eqref{eq:2.1}.
By the Riesz--Fréchet representation theorem there exists a unique $v\in H^1_0(\Omega)$ such that
\[
 \int_\Omega \Phi\Delta w\dx = -\int_\Omega\nabla v\nabla w\dx = \int_\Omega v\Delta w\dx
\]
for all $w\in C^\infty_\cpt(\Omega)$. This means that $u:=\Phi-v$ satisfies $\Delta u=0$ weakly. Hence $u\in C^\infty(\Omega)$ by Weyl's theorem and $\Delta u=0$ in the classical sense;
that is, $u$ is a harmonic function.
We call $u$ the \emphdef{variational solution} of~\ref{eq:D} and set $u_\phi := u$.
To do so, we have to show that the function does not depend on the extension $\Phi$ of $\phi$. This follows from the next lemma.

Next we talk about the Dirichlet principle.
We start by mentioning that the variational solution $u_\phi$ is obtained by a minimising process.
In fact, let $\phi\in C(\partial\Omega)$ and $\Phi\in C(\clos{\Omega})$ be an extension of $\phi$ satisfying the estimate~\eqref{eq:2.1}, i.e.\ $\Delta\Phi\in H^{-1}(\Omega)$.
The solution $v\in H^1_0(\Omega)$ of $\Delta v=\Delta\Phi$ is the unique function $v\in H^1_0(\Omega)$ such that
\begin{equation}\label{eq:2.5}
 \frac{1}{2}\int_\Omega\abs{\nabla v}^2\dx + \langle\Delta\Phi,v\rangle = \min\Bigl\{\frac{1}{2}\int_\Omega\abs{\nabla w}^2\dx + \langle\Delta\Phi,w\rangle \setcolon w\in H^1_0(\Omega)\Bigr\}
\end{equation}
(see e.g.~\cite[Theorem~4.24]{AU23}).
Now we can characterise when $\int_\Omega\abs{\nabla u_\phi}^2\dx<\infty$; i.e.\ when $u_\phi$ has finite energy.
Since $u_\phi\in C^\infty(\Omega)\cap C_\bdd(\Omega)$, this is equivalent to saying that $u_\phi\in H^1(\Omega)$.

\begin{thm}\label{thm:2.7}
Let $\phi\in C(\partial\Omega)$. The following statements are equivalent.
\begin{romanenum}
\item\label{en:t2.7-i}
The variational solution $u_\phi$ of~\ref{eq:D} is an element of $H^1(\Omega)$.
\item\label{en:t2.7-ii}
There exists $\Phi\in C(\clos{\Omega})\cap H^1(\Omega)$ with $\restrict{\Phi}{\partial\Omega}=\phi$.
\end{romanenum}
In that case
\[
 \int_\Omega\abs{\nabla u_\phi}^2\dx = \min\Bigl\{\int_\Omega\abs{\nabla w}^2\dx \setcolon w\in H^1(\Omega),\ \Phi-w\in H^1_0(\Omega)\Bigr\}.
\]
\end{thm}
\begin{proof}
\begin{parenum}
\item[\ref{en:t2.7-ii}$\Rightarrow$\ref{en:t2.7-i}.]
Since $\Phi\in H^1(\Omega)$, $u_\phi=\Phi-v\in H^1(\Omega)$, where $v\in H^1_0(\Omega)$ is such that $\Delta v=\Delta\Phi$.
Moreover, by~\eqref{eq:2.5} and considering $W:=\{w\in H^1(\Omega)\setcolon \Phi-w\in H^1_0(\Omega)\}$,
\begin{align*}
 \frac{1}{2}[u_\phi,u_\phi] -\frac{1}{2}[\Phi,\Phi] &= \frac{1}{2}[v,v]-[\Phi,v] \\
 &= \min\Bigl\{\frac{1}{2}[\Phi-w,\Phi-w] - [\Phi,\Phi-w] \setcolon w\in W\Bigr\} \\
 &= \min\Bigl\{\frac{1}{2}[w,w] - \frac{1}{2}[\Phi,\Phi] \setcolon w\in W\Bigr\} \\
 &= \frac{1}{2} \min\Bigl\{[w,w] \setcolon w\in W\Bigr\}-\frac{1}{2}[\Phi,\Phi].
\end{align*}
Thus $[u_\phi,u_\phi] = \min\{[w,w]\setcolon w\in W\}$ and this property characterises $u_\phi$.
\item[\ref{en:t2.7-i}$\Rightarrow$\ref{en:t2.7-ii}.]
Let $\Phi\in C(\clos{\Omega})$ be such that $\restrict{\Phi}{\partial\Omega}=\phi$ and $\Delta\Phi\in H^{-1}(\Omega)$.
Let $v\in H^1_0(\Omega)$ be such that $\Delta v=\Delta\Phi$.
Then $u_\phi=\Phi-v$.
Since $u_\phi\in H^1(\Omega)$ by hypothesis, it follows that $\Phi\in H^1(\Omega)$.\qedhere
\end{parenum}
\end{proof}

If $\Omega$ is more regular, the following holds.
\begin{thm}\label{thm:2.9}
Assume that $\Omega$ has Lipschitz boundary and let $\phi\in C(\partial\Omega)$. The following statements are equivalent.
\begin{romanenum}
\item $u_\phi\in H^1(\Omega)$
\item $\phi\in H^{1/2}(\partial\Omega)$
\end{romanenum}
\end{thm}
Here, since $\Omega$ has Lipschitz boundary, $H^{1/2}(\partial\Omega)=\{\operatorname{tr}\Phi \setcolon \Phi\in H^1(\Omega)\}$, where $\operatorname{tr}\colon H^1(\Omega)\to L^2(\partial\Omega,\mathcal{H}^{d-1})$ is the trace operator and $\mathcal{H}^{d-1}$ denotes the $(d-1)$-dimensional Hausdorff measure.
If $\phi\in C(\partial\Omega)\cap H^{1/2}(\partial\Omega)$, there even exists a $\Phi\in C(\clos{\Omega})\cap H^1(\Omega)$ such that $\restrict{\Phi}{\partial\Omega}=\phi$.
We refer to~\cite[Theorem~1.2]{AtE19:dp} for this and a proof of Theorem~\ref{thm:2.9}.
A more general result on very rough domains is~\cite[Theorem~5.8]{AtES24}.

Theorem~\ref{thm:5.1} is contained in Landkof~\cite[p.\,243, lines 1--5]{La72}.
We will give a very different proof based on the following result. We assume that $d\ge 3$.
\begin{thm}\label{thm:5.2}
Let $z_0\in \partial\Omega$ be a singular point of $\Omega$.
Then there exists an open set $\Omega_0\subset\RR^d$ such that $\clos{\Omega_0}\subset\Omega\cup\{z_0\}$, $z_0\in\partial\Omega_0$ and $z_0$ is a singular point of $\Omega_0$.
\end{thm}
We postpone the proof of Theorem~\ref{thm:5.2} but note that in the case of Lebesgue's domain it readily follows from its construction.
More precisely, given the potential $V\colon D\to(0,\infty)$ from Lemma~\ref{lem:lebesgue-potential-basics}, we had $\Omega=\{x\in D\setcolon \frac{1}{2}<V(x)<2\}$. We can choose e.g.~$\Omega_0=\{x\in D\setcolon \frac{1}{c}<V(r,z)<c\}$ for any $c\in (1,2)$.
Now we can easily prove Theorem~\ref{thm:5.1} using the following criterion for a boundary point to be regular, see~\cite[Theorem~6.74]{AU23}.
\begin{prop}\label{prop:5.4}
Let $z_0\in \partial\Omega$. Then $z_0$ is regular if there exists a \emphdef{global $H^1$-barrier} $b$ at $z_0$; i.e.\ a function $b\in C(\clos{\Omega})\cap H^1(\Omega)$ such that $b(x)>0$ for all $x\in\clos{\Omega}\setminus\{z_0\}$, $b(z_0)=0$ and $-\Delta b\ge 0$ weakly on $\Omega$.
\end{prop}
\begin{proof}[Proof of Theorem~\ref{thm:5.1}]
Let $z_0\in \partial\Omega$ be a singular point for $\Omega$.
By Theorem~\ref{thm:5.2} there exists an open set $\Omega_0\subset\RR^d$ such that $\clos{\Omega_0}\subset\Omega\cup\{z_0\}$ and $z_0\in\partial\Omega_0$ is a singular point with respect to $\Omega_0$.
Let $0\le\phi\in C(\partial\Omega)$ be such that $\phi(z_0)=0$ and $\phi(w)>0$ at a regular point $w\in \partial\Omega$.
Then there exists $0\le\Phi_0\in C^\infty_\cpt(\RR^d)$ such that $\phi_0:=\restrict{\Phi_0}{\partial\Omega}$ satisfies $\phi_0\le\phi$ and $\phi_0(w)>0$.
Let $u_\phi$ and $u_{\phi_0}$ be the variational (equivalently Perron) solutions with respect to $\Omega$.
Then $u_\phi\ge u_{\phi_0}\ge 0$ on $\Omega$ by the maximum principle, and $u_{\phi_0}\ne 0$.
Moreover, $u_{\phi_0}\in H^1(\Omega)$ by Theorem~\ref{thm:2.7}.

