ref_dict.thm:Strichartz:
\begin{theorem}\label{thm:Strichartz}

        Fix
		$0<\tau<\tfrac13$ and $F\in L^{\tilde q'}(\mathbb R;\ell^{\tilde r'}(\mathbb Z))$. Let $(q,r)$ and $(\tilde q,\tilde r)$ be two $\tau$--admissible pairs with $q,\tilde q<\infty.$  Then the Cauchy
		problem \eqref{eq: inhomogegeneous} has a unique global solution
		$
		u\in C(\mathbb R;\ell^2(\mathbb Z))
		$
		and \begin{equation}\label{eq:inhom-Strichartz}
			\|u\|_{L^q_t(\mathbb R;\ell^r(\mathbb Z))}
			\;\le\; C\Bigl(
			\|\varphi\|_{\ell^2(\mathbb Z)}
			+\|\psi\|_{\ell^2(\mathbb Z)}
			+\|F\|_{L^{\tilde q'}_t(\mathbb R;\ell^{\tilde r'}(\mathbb Z))}
			\Bigr),
		\end{equation}
		where $\tilde q'$ and $\tilde r'$ denote the Hölder conjugates of
		$\tilde q$ and $\tilde r$, respectively, and the constant $C$ is
		independent of $\theta$, $\varphi$, $\psi$ and $F$. 

	\end{theorem}

