 \begin{aligned}
 &\int_\Sigma \left(g_1(E,t){\cK}_n(E)+g_2(E,t){\cJ}_n(E)\right)\, \rho^{\prime}\d E\\
 =&\frac{1}{2} \int_\Sigma e^{{\rm i}\Omega(E)t} \sum_{k\in\Z} \left(\varphi(k) + \frac{\psi(k)}{{\rm i}\Omega(E)}\right) \left({\cK}_k(E){\cK}_n(E)+{\cJ}_k(E){\cJ}_n(E)\right)\, \rho^{\prime}\d E \\
