We assume in this paper, even without further reference, that $u\ge 0$, $u_{0}\ge 0$, $u_{0}\in L^{\infty}(\R^{\SpDim})$ is compactly supported, and that
\begin{equation}
 \label{eq:degen}
 1<p<N
 \,,
 \qquad
 p+m-3>0
 \,.
\end{equation}
On $g$ we assume that $g\in C([0,+\infty])\cap C^{1}((0,+\infty))$ is such that $g(0)=0$, $g(s)>0$ for $s>0$, and for given $0<\alpha_{1}\le \alpha_{2}<p$
\begin{equation}
 \label{eq:powerlike}
 \alpha_{1}
 \frac{g(s)}{s}
 \le
 g'(s)
 \le
 \alpha_{2}
 \frac{g(s)}{s}
 \,,
 \qquad
 s>0
 \,.
\end{equation}

\begin{definition}
 \label{d:weaksol}
 A function $u\ge 0$ is a weak solution to \eqref{eq:pde} if
 \begin{equation*}
 u\in C([0,+\infty); L^{1}_{f}(\R^{\SpDim})) \cap L^{\infty}(\R^{\SpDim}\times(\bar t,+\infty))
 \end{equation*}
 for all $\bar t>0$, and
 \begin{equation*}
 \operatorname{\nabla} u^{\frac{p+m-2}{p-1}}
 \in
 L^{p}_{\textup{loc}}
 (S_{\infty})
 \,.
 \end{equation*}
 In addition we require the standard integral formulation, i.e., for all $\eta\in C_{0}^{\infty}(S_{\infty})$,
 \begin{equation}
 \label{eq:weaksol_a}
 \int_{0}^{+\infty}
 \int_{\R^{\SpDim}}
 \{
 -
 u
 \eta_{t}
 +
 u^{m-1}
 \lvert\operatorname{\nabla} u\rvert^{p-2}
 \operatorname{\nabla} u
 \operatorname{\nabla} \eta
 \}
 f(x)
 \di x
 \di t
 =
 0
 \,.
 \end{equation}
 \\
 If we also have $u_{t}\in L^{\infty}_{\textup{loc}}(0,+\infty); L^{1}_{f\,\textup{loc}}(\R^{\SpDim}))$, then $u$ is a strong solution.
 \\
 Supersolutions [respectively, subsolutions] to \eqref{eq:pde} are defined similarly, with the difference that, for $\eta\ge0$, we require in \eqref{eq:weaksol_a} an inequality sign $\ge $ [respectively, $\le$].
 \\
 Solutions to the Cauchy problem \eqref{eq:pde}--\eqref{eq:initd} are solutions to \eqref{eq:pde} satisfying $u(0)=u_{0}$ in the sense of $C([0,+\infty); L^{1}_{f}(\R^{\SpDim}))$.
\end{definition}

When we consider radial solutions of the form $u(x,t)=U(r,t)$,
$r=\lvertx\rvert$, the equation \eqref{eq:pde} can be written as
\begin{equation}
 \label{eq:pde_rad}
 r^{N-1}
 f(r)
 \pder{U}{t}
 =
 \pder{}{r}
 \big[
 r^{N-1}
 f(r)
 U^{m-1}
 \abs{U_{r}}^{p-2}
 U_{r}
 \big]
 \,,
 \qquad
 r>0
 \,,
 t>0
 \,,
\end{equation}
which in turn can be rephrased as
\begin{equation}
 \label{eq:sss_rad}
 \begin{split}
 \pder{U}{t}
 &=
 \pder{}{r}
 \big[
 U^{m-1}
 \abs{U_{r}}^{p-2}
 U_{r}
 \big]
 \\
 &\quad+
 \Big(
 \frac{N-1}{r}
 +
 g'
 \Big)
 \big[
 U^{m-1}
 \abs{U_{r}}^{p-2}
 U_{r}
 \big]
 \,,
 \qquad
 r>0
 \,,
 t>0
 \,.
 \end{split}
\end{equation}
Of course the differential inequalities characterizing radial supersolutions and subsolutions can be rephrased similarly.
Specifically, we consider supersolutions and subsolutions of the form
\begin{alignat}2
 \label{eq:sss_sup}
 \widetilde u(x,t)
 &=
 \frac{C_{*}}{(t+t_{0})^{\frac{1}{p+m-3}}}
 \Big[
 E(\tau)^{\frac{1}{p-1}}
 -
 J(r)^{\frac{1}{p-1}}
 \Big]^{\frac{p-1}{p+m-3}}_{+}
 \,,
 &\quad&
 r\ge \rpol_{0}
 \,,
 \\
 \label{eq:sss_ups_2}
 \widetilde u(x,t)
 &=
 \frac{C_{*}}{(t+t_{0})^{\frac{1}{p+m-3}}}
 \Big[
 E(\tau)^{\frac{1}{p-1}}
 -
 I(r)
 \Big]^{\frac{p-1}{p+m-3}}_{+}
 \,,
 &\quad&
 r<\rpol_{0}
 \,,
\end{alignat}
where $r=\lvertx\rvert$, and
\begin{gather*}
 G(r)
 =
 \int_{0}^{r}
 \frac{g(s)}{s}
 \di s
 \,,
 \quad
 r\ge 0
 \,;
 \qquad
 J(r)
 =
 \frac{r^{p}}{G(r)}
 \,,
 \quad
 r>0
 \,.
 \\
 \tau
 =
 \varGamma
 \log(t+t_{0})
 \,,
 \quad
 t\ge 0
 \,;
 \\
 E(\tau)
 =
 J(G^{(-1)}(\tau))
 =
 \frac{G^{(-1)}(\tau)^{p}}{\tau}
 \,,
 \quad
 \tau>0
 \,;
 \\
 I(r)
 =
 \nu_{0}
 \Big(
 \frac{r^{p}}{G(\rpol_{0})}
 \Big)^{\frac{1}{p-1}}
 +
 (1-\nu_{0})
 J(\rpol_{0})^{\frac{1}{p-1}}
 \,,
 \quad
 r>0
 \,.
\end{gather*}
Note that the integral defining $G$ converges according to \eqref{eq:powerlike_lt}.

We also remark that the radius $\tilde r(t)$ of the support of $\widetilde u(t)$ is characterized by $E(\tau)=J(\tilder(t))$, i.e., by $\tilder(t)=G^{(-1)}(\tau)$; according to Lemma~\ref{l:sss_excf} and \eqref{eq:sss_powerlike_gt_excf} this yields
\begin{equation}
 \label{eq:sup_sub_radius}
 \gamma_{1}
 g^{(-1)}(\log t)
 \le
 \tilde r(t)
 \le
 \gamma_{2}
 g^{(-1)}(\log t)
 \,,
 \qquad
 t>t_{0}
 \,,
\end{equation}
for two suitable constants $\gamma_{1}$, $\gamma_{2}>0$.

\begin{proposition}
 \label{p:main_sup_sub}
 The constants $C_{*}$, $\varGamma$, $t_{0}> 1$, $\rpol_0$ and
 $\nu_{0}$ can be selected so that $\widetilde u$ as defined in
 \eqref{eq:sss_sup}--\eqref{eq:sss_ups_2} is a strong supersolution to
 \eqref{eq:pde}. Alternatively, we may select such constants so that
 $\widetilde u$ is a strong subsolution to \eqref{eq:pde}.
\end{proposition}

\begin{theorem}
 \label{t:sub_sub_dens}
 Let $v$ be a strong solution to \eqref{eq:rad_N}, for the specific $\rw$ found in Theorem~\ref{t:transform}, under assumptions \eqref{eq:degen} and \eqref{eq:powerlike}, such that $v(x,0)$ is compactly supported, bounded and
$v(x,0)\ge \eps>0$ for $\abs{x}\le\ell$, $\ell>0$.
 \\
 Then there exist constants $t_{0}$, $C_{*}$, $\rpol_{0}$ and $\varGamma$ such that $\ups(\rpolf(\abs{x}),t)$ as in \eqref{eq:sss_sup}--\eqref{eq:sss_ups_2} is a subsolution \eqref{eq:rad_N}, and
 \begin{equation}
 \label{eq:sub_sub_dens_n}
 v(x,t)
 \ge
 \ups(\rpolf(\abs{x}),t)
 \,,
 \qquad
 (x,t)\in S_{\infty}
 \,.
 \end{equation}
 We have also
 \begin{equation}
 \label{eq:sub_sub_dens_nn}
 \supp v(t)
 \supset
 B_{\tilde R(t)}(0)
 \,,
 \quad
 \log\tilde R(t)
 \sim
 \log t
 \,,
 \qquad
 t>t_{0}
 \,,
 \end{equation}
 The constants involved in \eqref{eq:sub_sub_dens_n}--\eqref{eq:sub_sub_dens_nn} depend on the parameters appearing in the assumptions and on $v(x,0)$.
\end{theorem}

We work in the set $\trb>0$. Then we compute
\begin{equation}
 \label{eq:sss_ups_diffs}
 \begin{split}
 L_{1}
 &:=
 \ups^{m-1}
 \abs{\ups_{\rpol}}^{p-2}
 \ups_{\rpol}
 \\
 &=
 -
 \frac{
 C_{*}^{p+m-2}
 (\nu_{0}p)^{p-1}
 }{
 (p+m-3)^{p-1}
 }
 \,
 \frac{
 \trb(\rpol,\tau)^{\frac{p-1}{p+m-3}}
 }{
 (t+t_{0})^{\frac{p+m-2}{p+m-3}}
 }
 \frac{\rpol}{\excf(\rpol_{0})}
 \,.
 \end{split}
\end{equation}
We recall that, in order for $\ups$ to be a supersolution, we need to check (see also \eqref{eq:sss_ups_ineq})
\begin{equation}
 \label{eq:sss_ups_ineqs}
 \pder{\ups}{t}
 \ge
 \pder{L_{1}}{\rpol}
 +
 L_{1}
 \Big(
 \frac{N-1}{\rpol}
 +
 \exw'(\rpol)
 \Big)
 \,,
 \qquad
 \rpol<\rpol_{0}
 \,.
\end{equation}
The time derivative $\ups_{t}$ is given by \eqref{eq:sss_ups_tder},
when we formally substitute $\brt(\rpol,\tau)$ with $\trb(\rpol,\tau)$.
Next we calculate
\begin{equation}
 \label{eq:sss_ups_diffs2}
 \begin{split}
 \pder{L_{1}}{\rpol}
 &=
 \frac{
 C_{*}^{p+m-2}
 (\nu_{0}p)^{p-1}
 }{
 (p+m-3)^{p-1}
 }
 \,
 \frac{
 \trb(\rpol,\tau)^{\frac{p-1}{p+m-3}-1}
 }{
 (t+t_{0})^{\frac{p+m-2}{p+m-3}}
 \excf(\rpol_{0})
 }
 \\
 &\quad\times
 \Big[
 \frac{p\nu_{0}}{p+m-3}
 \frac{\rpol^{\frac{p}{p-1}}}{\excf(\rpol_{0})^{\frac{1}{p-1}}}
 -
 \trb(\rpol,\tau)
 \Big]
 \,.
 \end{split}
\end{equation}
Upon dividing both sides of \eqref{eq:sss_ups_ineqs} by
\begin{equation*}
 \frac{C_{*}}{p+m-3}
 \,
 \frac{\trb(\rpol,\tau)^{\frac{p-1}{p+m-3}-1}}{(t+t_{0})^{\frac{p+m-2}{p+m-3}}}
 \,,
\end{equation*}
we obtain the equivalent version of \eqref{eq:sss_ups_ineqs} (here $K_{0}$ is as in \eqref{eq:sss_ups_ineq2})
\begin{equation}
 \label{eq:sss_ups_ineqs2}
 \begin{split}
 K_{0}&=
 (p-1)
 (t+t_{0})
 \der{}{t}
 \big(
 \tar(\tau)^{\frac{1}{p-1}}
 \big)
 \ge
 \trb(\rpol,\tau)
 \\
 &\quad+
 \frac{C_{*}^{p+m-3}(\nu_{0}p)^{p-1}}{(p+m-3)^{p-2}}
 \frac{1}{\excf(\rpol_{0})}
 \Big[
 \frac{p\nu_{0}}{p+m-3}
 \frac{\rpol^{\frac{p}{p-1}}}{\excf(\rpol_{0})^{\frac{1}{p-1}}}
 -
 \trb(\rpol,\tau)
 \Big]
 \\
 &\quad
 -
 \Big(
 \frac{N-1}{\rpol}
 +
 \exw'(\rpol)
 \Big)
 \frac{C_{*}^{p+m-3}(\nu_{0}p)^{p-1}}{(p+m-3)^{p-2}}
 \frac{\trb(\rpol,\tau)\rpol}{\excf(\rpol_{0})}
 =:
 K_{3}
 \,.
 \end{split}
\end{equation}
On recalling \eqref{eq:sss_ups_k0}, we see that $K_{0}>0$, so that we need only show
\begin{equation}
 \label{eq:sss_ups_ineqs3}
 0
 \ge
 K_{3}
 \,.
\end{equation}
Clearly, this is implied by
\begin{equation}
 \label{eq:sss_ups_ineqs4}
 \begin{split}
 & \Big(
 \frac{(N-1)C_{*}^{p+m-3}(\nu_{0}p)^{p-1}}{(p+m-3)^{p-2}\excf(\rpol_{0})}
 -
 1
 \Big)
 \trb(\rpol,\tau)
 \ge
 \\
 &\quad
 \frac{C_{*}^{p+m-3}(\nu_{0}p)^{p-1}}{(p+m-3)^{p-2}}
 \frac{1}{\excf(\rpol_{0})}
 \Big[
 \frac{p\nu_{0}}{p+m-3}
 \frac{\rpol^{\frac{p}{p-1}}}{\excf(\rpol_{0})^{\frac{1}{p-1}}}
 -
 \trb(\rpol,\tau)
 \Big]
 \,.
 \end{split}
\end{equation}
The left hand side of \eqref{eq:sss_ups_ineqs4} is nonnegative, owing to our choice of $C_{*}$ and to \eqref{eq:sss_ups_c1} (we use the second term in the $\max$ function in \eqref{eq:sss_ups_C} here). Thus we only need to show that the right hand side there is nonpositive for $\rpol<\rpol_{0}$. According to the definitions of $\tau$ and of $\trb(\rpol,\tau)$ this in turn follows from
\begin{equation}
 \label{eq:sss_ups_ineqs5}
 \begin{split}
 &\frac{p\nu_{0}}{p+m-3}
 \frac{\rpol_{0}^{\frac{p}{p-1}}}{\excf(\rpol_{0})^{\frac{1}{p-1}}}
 +
 \ram(\rpol_{0})
 \le
 \tar(\log t_{0})^{\frac{1}{p-1}}
 \\
 &\quad\le
 \tar(\varGamma \log t_{0})^{\frac{1}{p-1}}
 \le
 \tar(\tau)^{\frac{1}{p-1}}
 \,,
 \end{split}
\end{equation}
where the last two inequalities follow trivially from the increasing character of $\tar(\tau)$ and $\varGamma\ge 1$. But since $\rpol_{0}$ has been fixed, this amounts simply to choosing $t_{0}=t_{0}(\rpol_{0})$ so that both \eqref{eq:sss_ups_t0r0} and \eqref{eq:sss_ups_ineqs5} are satisfied; actually it is easily seen that \eqref{eq:sss_ups_t0r0} follows from \eqref{eq:sss_ups_ineqs5}. Note that $r_{0}$, $C_{*}$ and $t_{0}$ are independent of $\varGamma$.

We look for subsolutions in the radial form
\eqref{eq:sss_sup}--\eqref{eq:sss_ups_2}. We use here the same
notation introduced in Section~\ref{s:sss}, and we look at the set
where $\ups>0$. In this Section, the choice of the constants is more
delicate; we find it convenient to establish it from the beginning. In
this connection, let us note that the constant $\tilde\mu_{1}>0$ is
defined in \eqref{eq:sss_ubs_mu1}, $\tilde\mu_{2}>0$ in
\eqref{eq:sss_ubs_mu2}, and $\tilde\mu_{3}\ge 0$ in
\eqref{eq:sss_ubs_mu3}; the $\tilde\mu_{i}$ depend on $p$, $m$,
$\alpha_{1}$, $\alpha_{2}$ only. The constant $\nu_{0}$ is chosen as
in \eqref{eq:sss_ups_c1}. We also introduce for future reference a
given constant $\lambda>0$.
\\
We fix $t_{0}>1$ such that
\begin{equation}
 \label{eq:sss_ubs_t0}
 \begin{split}
 \log t_{0}
 \ge
 \max&\Big\{
 4
 \frac{p-\alpha_{1}}{\alpha_{1}}
 \,,
 \tilde\mu_{4}^{-1}
 \,,
 \frac{2\tilde\mu_{1}(N-1)+\tilde\mu_{3}
 +
 2\tilde\mu_{1}
 \alpha_{2}^{2}}
 {\tilde\mu_{4}}
 \,,
 \\
 &\quad
 \frac{2(\nu_{0}p)^{p-1}}{\tilde\mu_{4}(p+m-3)^{p-2}}
 (
 N
 +
 \alpha_{2}^{2}
 )
 \Big\}
 \,,
 \end{split}
\end{equation}
where
\begin{equation}
 \label{eq:ssb_ups_mu4}
 \tilde\mu_{4}
 =
 2^{-\frac{\alpha_{2}(p-1)}{p-\alpha_{2}}}
 \frac{\tilde\mu_{2}\alpha_{1}}{p-\alpha_{1}}
 >0
 \,. 
\end{equation}
Next we select $\rpol_{0}>0$ such that
\begin{equation}
 \label{eq:ssb_ups_r0}
 \excf(r_{0})
 <
 \min
 \Big\{
 1
 \,,
 \lambda^{p+m-3}
 \,,
 \tilde\mu_{4}
 C_{*}^{p+m-3}
 \log t_{0}
 \Big\}
 \,,
\end{equation}
where we set
\begin{equation}
 \label{eq:ssb_ups_C}
 \begin{split}
 C_{*}^{-(p+m-3)}
 &=
 \max\Big\{
 \lambda^{-(p+m-3)}
 \,,
 2\frac{\tilde\mu_{1}(N-1)+\tilde\mu_{3}}{\excf(\rpol_{0})}
 +
 2\tilde\mu_{1}
 \alpha_{2}^{2}
 \,,
 \\
 &\quad
 \frac{2(\nu_{0}p)^{p-1}}{(p+m-3)^{p-2}}
 \frac{1}{\excf(\rpol_{0})}
 (
 N
 +
 \alpha_{2}^{2}
 \excf(\rpol_{0})
 )
 \Big\}
 \,.
 \end{split}
\end{equation}
Clearly we have to show that \eqref{eq:ssb_ups_r0}, \eqref{eq:ssb_ups_C} are compatible, that is that 
\begin{equation}
 \label{eq:ssb_ups_r0_i}
 \excf(\rpol_{0})C_{*}^{-(p+m-3)}
 <
 \tilde\mu_{4}
 \log t_{0}
\end{equation}
can be fulfilled by choosing a small enough $\rpol_{0}$. Indeed, also invoking $\excf(\rpol_{0})<\min\{1,\lambda^{p+m-3}\}$ which is certainly meaningful, we compute from \eqref{eq:ssb_ups_C}
\begin{equation}
 \label{eq:ssb_ups_r0_ii}
 \begin{split}
 \excf(\rpol_{0})C_{*}^{-(p+m-3)}
 &<
 \max\Big\{
 1
 \,,
 2\tilde\mu_{1}(N-1)+\tilde\mu_{3}
 +
 2\tilde\mu_{1}
 \alpha_{2}^{2}
 \,,
 \\
 &\quad
 \frac{2(\nu_{0}p)^{p-1}}{(p+m-3)^{p-2}}
 (
 N
 +
 \alpha_{2}^{2}
 )
 \Big\}
 \le
 \tilde\mu_{4}
 \log t_{0}
 \,,
 \end{split}
\end{equation}
according to our choice of $t_{0}$.
Finally we select
\begin{equation}
 \label{eq:ssb_ups_Gamma0}
 \varGamma
 =
 2^{\frac{\alpha_{2}(p-1)}{p-\alpha_{2}}}
 \frac{\excf(\rpol_{0})}{\log t_{0}}
 \,.
\end{equation}

