\begin{theorem}
  \label{t:sub_sub}
  Assume \eqref{eq:degen} and \eqref{eq:powerlike}. Let $u$ be a strong solution to \eqref{eq:pde}--\eqref{eq:initd} with a compactly supported and bounded data $u_{0}$, such that $u_{0}(x)\ge \varepsilon>0$ for $\lvertx\rvert\le\ell$, $\ell>0$.
  \\
  Then there exist constants $t_{0}$, $C_{*}$, $\rpol_{0}$ and $\varGamma$ such that $\widetilde u$ as in \eqref{eq:sss_sup}--\eqref{eq:sss_ups_2} is a subsolution and
  \begin{equation}
    \label{eq:sub_sub_n}
    u(x,t)
    \ge
    \widetilde u(x,t)
    \,,
    \qquad
    (x,t)\in S_{\infty}
    \,.
  \end{equation}
  We have also
  \begin{equation}
    \label{eq:sub_sub_nn}
    \supp u(t)
    \supset
    B_{R(t)}(0)
    \,,
    \quad
    R(t)
    =
    \gamma
    g^{(-1)}(\log t)
    \,,
    \qquad
    t>t_{0}
    \,,
  \end{equation}
  for a suitable constant $\gamma>0$. The constants here depend on the parameters appearing in the assumptions and on $\varepsilon$, $\ell$.
\end{theorem}

\begin{proof}[Proofs of Theorems \ref{t:sup_sup} and \ref{t:sub_sub}]
  The proof follows straightforwardly from an application of the method given in the proof of \cite[Theorem~1]{Tsutsumi:1988}, when we take into account Proposition~\ref{p:main_sup_sub} and Lemmas \ref{l:sss_comp} and \ref{l:ssb_comp}.
\end{proof}

Next we apply our results to a different kind of equation, that is \eqref{eq:rad_N}; see also \cite{Vazquez:2015}, \cite{Grillo:Muratori:Vazquez:2017} for the case of the porous media equation.

\begin{theorem}
  \label{t:transform}
Radial solutions $U(r,t)$ [respectively, supersolutions and subsolutions] of \eqref{eq:pde} correspond, thru a suitable transformation of the space variable, to radial solutions $v(s,t)$ [respectively, supersolutions and subsolutions] of \eqref{eq:rad_N},
for a suitable positive function $\rho\in C([0,+\infty))$ such that $\rho(0)=1$ and
\begin{equation}
  \label{eq:rad_rw_est}
  \rho(s)
  \sim
  \frac{g^{(-1)}(\log s)^{p}}{(\log s)^{p}}
  \frac{1}{s^{p}}
  \,.
\end{equation}
In fact, the transformation $r=\hat\rpol(s)$, $s>0$, is such that
\begin{equation}
  \label{eq:rad_r_asy_n}
  \hat\rpol(s)
  \sim
  g^{(-1)}(\log s)
  \,.
\end{equation}
\end{theorem}

Here and in the following we use the notation, for positive functions $F_{1}$, $F_{2}$,
\begin{equation}
  \label{eq:rad_sim}
  F_{1}(s)\sim F_{2}(s)
  \quad
  \text{if and only if}
  \quad
  C_{1}
  \le
  \frac{F_{2}(s)}{F_{1}(s)}
  \le
  C_{2}
  \,,
  \quad
  s\ge \bar s
  \,,
\end{equation}
for suitable $C_{1}$, $C_{2}$, $\bar s>0$.

Owing to Theorem~\ref{t:transform}, supersolutions and subsolutions of the type \eqref{eq:sss_sup}--\eqref{eq:sss_ups_2} yield radial counterparts for equation \eqref{eq:rad_N}. Thus, from our  Theorems \ref{t:sup_sup}, \ref{t:sub_sub} the following comparison results follow immediately.

