    \log\tilde R(t)
    \sim
    \log t
    \,,
    \qquad
    t>t_{0}
    \,,
  \end{equation}
  The constants involved in \eqref{eq:sub_sub_dens_n}--\eqref{eq:sub_sub_dens_nn} depend on the parameters appearing in the assumptions and on $v(x,0)$.
\end{theorem}

\begin{remark}
  \label{r:rad_N}
  Clearly the sup estimate valid for $v$ as in Theorems
  \ref{t:sup_sup_dens} and \ref{t:sub_sub_dens} is the same as in
  \eqref{eq:sup_decay}, which should be compared with the result valid for $\rho(s)\sim s^{-\alpha}$, $\alpha>p$, that is the universal bound $t^{-1/(p+m-3)}$ (see \cite{Andreucci:Tedeev:2021b}). Our present bound however depends on the initial data, as the known bound valid in the subcritical case $\alpha<p$, whose decay rate is $t^{-(N-\alpha)/K}$, $K=(N-\alpha)(p+m-3)+p-\alpha$.
\end{remark}

\textbf{Plan of the paper.}
Section~\ref{s:pre} contains some elementary auxiliary results.
Then Proposition~\ref{p:main_sup_sub} is proved in Sections \ref{s:sss} (supersolutions) and \ref{s:ssb} (subsolutions).
Finally in Section~\ref{s:rad} we carry out the transformation of variables linking \eqref{eq:pde} and \eqref{eq:rad_N}.

