theorem.content:
\label{main1}
Let $\Om$ be a bounded Lipschitz domain in $\mathbb{R}^2$ with Lipschitz constant $L < L_0$, where $0<L_0<1$ is a sufficiently small constant. Assume $b\in L^{2,\infty}(\Omega)^2$ and $\mathop{\rm div}\nolimits b=0$.
Then there exists $p_0(\|b\|_{L^{2,\infty}})>2$ such that for any $p_0'<q<p_0$ and $\mathbb{G}\in L^q(\Om)^{2\times 2}$, there exists a  weak solution pair $u\in W^{1,q}_{0,\si}(\Omega)$ and $\pi\in L^q_0(\Omega)$ of \eqref{drifteq} such that
\EQ{\label{main1-eq}
\|u\|_{ W^{1,q}(\Omega)}+\|\pi\|_{L^q(\Omega)}\le C(\Omega,\|b\|_{L^{2,\infty}})\|\mathbb{G}\|_{L^q(\Omega)}.
}
For $p_0'<q<p_0$, the above pair $(u,\pi)$ is the unique weak solution pair  in $W^{1,q}_0\times L^q_0(\Om)$ without assuming \eqref{main1-eq}.

ref_dict.main1-eq:
\begin{theorem}\label{main1}
Let $\Om$ be a bounded Lipschitz domain in $\R^2$ with Lipschitz constant $L < L_0$, where $0<L_0<1$ is a sufficiently small constant. Assume $b\in L^{2,\infty}(\Omega)^2$ and $\div b=0$.
Then there exists $p_0(\|b\|_{L^{2,\infty}})>2$ such that for any $p_0'<q<p_0$ and $\GG\in L^q(\Om)^{2\times 2}$, there exists a  weak solution pair $u\in W^{1,q}_{0,\si}(\Omega)$ and $\pi\in L^q_0(\Omega)$ of \eqref{drifteq} such that
\EQ{\label{main1-eq}
\|u\|_{ W^{1,q}(\Omega)}+\|\pi\|_{L^q(\Omega)}\le C(\Omega,\|b\|_{L^{2,\infty}})\|\GG\|_{L^q(\Omega)}.
}
For $p_0'<q<p_0$, the above pair $(u,\pi)$ is the unique weak solution pair  in $W^{1,q}_0\times L^q_0(\Om)$ without assuming \eqref{main1-eq}.
\end{theorem}

ref_dict.change-var:
\begin{proof}
Similar to \cite{CT1} we will use the Gehring's lemma approach \cite{Gehring, Gia}. Denote $\Om_{x,R}=\Om \cap B(x,R)$ for $x\in \overline \Om$ and $R>0$. Since $\pd \Om$ is Lipschitz and compact, there
is a radius $R_0\in (0,1]$ such that for every $x_0 \in\pd \Om$,
\EQ{ \label{R0.def}
\Om_{x_0,2R_0}= \{ (x',x_n) \in B_{2R_0}(0) \subset \R^2,\ x_n>\ga(x')\},
}
after suitable coordinate rotation and translation, where $\ga(x')$ is a Lipschitz function defined for $x'\in B_{2R_0}'(0) \subset \R$ with Lipschitz constant $L$ and $\ga(0)=0$.

To prove the a priori estimate \eqref{eq5.1}, we first consider the interior case with $x_0\in\Omega$ and $B_{\rho}=B_{\rho}(x_0)\subset\Omega$. We rescale it to the unit ball $B$ and denote $u_{\rho}(x)=\rho u(\rho x+x_0),b_{\rho}(x)=\rho b(\rho x+x_0),\pi_{\rho}(x)=\rho^2\pi(\rho x+x_0)$ and $\GG_{\rho}(x)=\rho^2 \GG(\rho x+x_0)$. Let $\bar{u}_{\rho}=u_{\rho}-k$ where $k$ is a real constant to be choose later.  By Remark \ref{Wolfpdecom}, we can decompose $\pi_{\rho} - (\pi_{\rho})_{B}=\pi_1+\pi_2+\pi_3$ in $B$, where $\pi_1,\pi_2,\pi_3$ are given by
\EQ{
\nabla\pi_1=\mathcal{W}_{4/3,B}(\Delta \bar{u}_{\rho}),\quad \nabla\pi_2=\mathcal{W}_{4/3,B}(-\div(b_{\rho}\otimes \bar{u}_{\rho})),\quad \nabla\pi_3=\mathcal{W}_{4/3,B}(\div \GG_{\rho}),
}
with $\int_B \pi_i=0$.
Therefore, by Theorem \ref{theoremL2wolf} we have the following pressure bound
\EQ{\label{wolfbound}
\|\pi_1\|_{4/3,B}\le c_1\|\nabla \bar{u}_{\rho}\|_{4/3,B},\quad\|\pi_2\|_{4/3,B}\le c_1 \|b_{\rho}\bar{u}_{\rho}\|_{4/3,B},\quad \|\pi_3\|_{4/3,B}\le c_1\|\GG_{\rho}\|_{4/3,B},
}
where $c_1$ is a global constant.
For simplicity of notations let us drop the subscript $\rho$ for the further calculations, until we need to scale back to ball $B_{\rho}(x_0)$.

Take a smooth cutoff function $\eta$ on $B$ with $\eta=1$ in $B_{\frac{1}{2}}$. Use the test function $\zeta=\eta^4 \bar{u}$ in the weak form \eqref{soln-pair} with $(u,\pi)$ replaced by $(\bar u, \pi - (\pi)_B)$ to get the energy estimate (using \eqref{5.1} due to $b \in L^{2+\de}$)
\EQS{\label{3.1}
\int_{B} |\nabla (\eta^2\bar{u})| ^2
\le &\int_{B} |\bar{u}|^2(|\nabla \eta^2|^2) +\int_{B} |\bar{u}|^2|b||\nabla\eta|\eta^3
\\
&+\int_{B} (|\pi_1|+|\pi_2|+|\pi_3|)|\bar{u}||\nabla\eta|\eta^3+\bka{\div \GG_{\rho}, \bar{u}\eta^4}_B.
}

We will estimate each of the terms on the right hand side separately, using Lemmas \ref{Holder} and \ref{Sobolev} in ball $B$,
\EQS{
\int_{B} |\bar{u}|^2|b||\nabla \eta|\eta^3
&\le \|b\|_{L^{2,\infty}(B)}\|\bar{u}^2\eta^3\|_{L^{2,1}(B)}\le \|b\|_{L^{2,\infty}(B)}\|\bar{u}\eta^{3/2}\|_{L^{4,2}(B)}^2
\\
&\le C \|b\|_{L^{2,\infty}(B)}\|\bar{u}\eta^{3/2}\|^2_{W^{1,4/3}(B)}.
}
For pressure terms we use \eqref{wolfbound} and get the following
\EQN{
\int_{B}|\pi_1||\bar{u}||\nabla\eta|\eta^3 &\le \|\pi_1\|_{4/3,B}\|\eta^2 \bar{u}\|_{L^4(B)}
\\
&\le
c\|\nabla \bar{u}\|_{4/3,B}\|\eta^2 \bar{u}\|_{W^{1,4/3}(B)}\le c\|\nabla \bar{u}\|_{4/3,B}^2+c\|\eta \bar{u}\|^2_{4/3,B},
}
\EQN{
\int_{B}|\pi_2||\bar{u}||\nabla\eta|\eta^3 &\le \|\pi_2\|_{L^{4/3}(B)}\|\eta^2\bar{u}\|_{L^4(B)}\le c\|\bar{u}\|_{L^{4,4/3}(B)}\|b\|_{L^{2,\infty}(B)}\|\eta^2\bar{u}\|_{L^{4}(B)}
\\
&\le c(b)\|\nabla \bar{u}\|_{4/3,B}^2+c(b)\| \bar{u}\|^2_{4/3,B}
}
\EQN{
\int_{B}|\pi_3||\bar{u}||\nabla\eta|\eta^3 &\le \|\pi_3\|_{4/3,B}\|\eta^2 \bar{u}\|_{L^4(B)}\le  c\|\GG\|_{2,B}\|\eta^2 \bar{u}\|_{W^{1,4/3}(B)}
\\
&\le \frac 14 \|\GG\|_{2,B}^2+c\|\eta^2 \bar{u}\|_{W^{1,4/3}(B)}^2.
}
Lastly we estimate the term containing $\GG$,
\EQN{
\bka{\div \GG_{\rho}, \bar{u}\eta^4}_B
&=-\int_{B} \GG :\nabla(\bar{u}\eta^4)=-\int_{B} \GG: \nabla(\eta^2\bar{u})\eta^2-2\int_{B} \GG :\bar{u}\nabla\eta\eta^3
\\
&\le \frac{1}{16}\|\nabla(\eta^2\bar{u})\|^2_{2,B}+c\|\eta^2 \bar{u}\|_{2,B}^2+ \frac 14\|\GG\|_{2,B}^2.
}
Combining these estimates with \eqref{3.1} we get the following
\EQ{
\int |\nabla (\eta^2\bar{u})|^2\le c(b)\|\bar{u}\|^2_{W^{1,4/3}(B)}+c(b)(\|\bar{u}\|_{2,B}^2+\|\bar{u}\|_{4/3,B}^2)+\|\GG\|_{2,B}^2,
}
Here $c(b)$ depends on $b$ only through $\norm{b}_{L^{2,\infty}(\Om)}$. Finally, since $\eta=1$ on $B_{1/2}$ we get that
\EQ{
\int_{B_{1/2}} |\nabla \bar{u}|^2\le c(b)\|\nabla \bar{u}\|^2_{4/3,B}+c(b)\|\bar{u}\|_{2,B}^2+\|\GG\|_{2,B}^2.
}
We now choose $k=(u_{\rho})_{B}$ as the constant in $\bar{u}=u_{\rho}-k$ and apply Poincar\'e inequality to get
\EQ{
\int_{B_{1/2}} |\nabla u_{\rho}|^2\le c(b)\|\nabla u_{\rho}\|^2_{4/3,B}+\|\GG\|_{2,B}^2.
}
Lastly we scale back to $B_{\rho}(x_0)$ and get that
\EQ{\label{5.12}
\frac{1}{|B_{\rho/2}|}\int_{B_{\rho/2}} |\nabla u|^2
\le c(b) \Big(\frac{1}{|B_{\rho}|}\int_{B_{\rho}}|\nabla u|^{4/3}\Big)^{3/2}+\frac{c}{|B_{\rho}|}\|\GG\|_{2,B_{\rho}}^2.
}

\medskip

Next we consider the boundary case, $\Omega_{\rho}=\Omega\cap B_{\rho}(x_0)$ with $x_0\in\pd\Om$, and $0<\rho<R_0$. The significant difference from the internal case is the pressure estimate: Unlike the internal case we can not use Wolf decomposition estimate in a uniform ball, therefore we need to track the dependence of constant $c_1$ when we apply Theorem \ref{theoremL2wolf} to get estimates similar to \eqref{pressure_bound_est}
 and make sure it is uniform across all  $\Omega_{\rho}(x_0)$.
 Rescale the domain as the interior case so that $x_0=0$ and $\rho=1$.
 We will use change of coordinates
 \EQ{\label{change-var}
 y_1=x_1, \quad y_2=x_2-\gamma(x_1),
 }
 to straighten the boundary and map $\Om_{5/8}\subset\Om_1$ into domains $\Om_{5/8}'\subset\Om_1'$ with flat boundary on $y_2=0$. Since $\gamma$ was a Lipschitz curve with sufficiently small Lipschitz constant we can assume that $\Om_{5/8}'\subset B_{6/8}^+\subset B_{7/8}^+\subset\Om_1'$.
  (This is the first place that specifies the smallness of the Lipschitz constant.) By Lemma \ref{geometry} we can fix a smooth $V$ such that $B_{6/8}^+\subset V\subset B_{7/8}^+$. After rewriting the equation \eqref{drifteq} in new variables we get the following system (with all derivatives in $y$) in $\Om_1'$:
\EQS{\label{changed_var}
-\Delta_y u+\div (\gamma' e_1\otimes\partial_{y_2}u)+
\gamma' \pd_1\pd_2 u - (\gamma')^2\partial_{y_2}^2u+
\\
+\div_y(b\otimes u)- \gamma'\partial_{y_2}(b\otimes u)_1+\nabla_y \pi-\gamma'\partial_{y_2}\pi e_1&=\div\GG-\gamma'\partial_2 \GG_1 ,
\\
\div_y u-\gamma'\partial_2 u_1&=0.
}
Above, $(b\otimes u)_1=(b_1u_1,b_1u_2)$ and $\GG_1=(G_{11},G_{12})$ are their first rows. In the second term, $\ga'$ is hidden behind $\div$ to avoid $\ga''$ which we do not assume any bound.

We apply Wolf's local pressure projection $\mathcal{W}_{4/3,V}$ on \eqref{changed_var} in the smooth domain $V$ and get that  $\pi-(\pi)_{V}=\pi_1+\pi_2+\pi_3+\pi_4$ where
\EQS{\label{pressure_decomp_b}
\nabla\pi_1&=\mathcal{W}_{4/3,V}\bkt{\Delta_y u-\div (\gamma' e_1\otimes\partial_{y_2}u)-\gamma' \pd_1\pd_2 u +(\gamma')^2\partial_{y_2}^2u}
\\
\nabla\pi_2&=\mathcal{W}_{4/3,V}\bkt{-\div_y(b\otimes u)+\gamma'\partial_{y_2}(b\otimes u)_1}
\\
 \nabla\pi_3&=\mathcal{W}_{4/3,V}(\gamma' \partial_{y_2}\pi e_1)
 \\
 \nabla\pi_4&= \mathcal{W}_{4/3,V}(\div \GG-\gamma'\partial_2 \GG_1).
}
From Theorem \ref{theoremL2wolf} the local pressure projection  $\mathcal{W}_{4/3,V}$ is well defined, and we have the bound \eqref{pWolfbound} with global constant $c$. Also using $\ga'\pd_2 = \pd_2 \ga'$, and Lemmas \ref{Holder} and \ref{Sobolev} in $V$,
\EQS{\label{pressure_bound_est}
\|\pi_1\|_{4/3,V}&\le c(1+\|\gamma'\|_{\infty}+\|\gamma'\|_{\infty}^2)\|\nabla u\|_{4/3,V}
\\
\|\pi_2\|_{4/3,V}&\le  c(1+\|\gamma'\|_{\infty})\|u\otimes b\|_{4/3,V}
\\
\|\pi_3\|_{4/3,V}&\le  c\|\gamma'\|_{\infty}\|\pi\|_{4/3,V}\le c\|\gamma'\|_{\infty}\|\pi_3\|_{4/3,V}+c\|\gamma'\|_{\infty}\|\pi_1+\pi_2+\pi_4\|_{4/3,V}
\\
\|\pi_4\|_{4/3,V}&\le  c(1+\|\gamma'\|_{\infty})\|\GG\|_{4/3,V}
}
Here we apply our choice of $\gamma$ so that $\|\gamma'\|_{\infty}<1$ and
$ c\|\gamma'\|_{\infty}<1/2$. (This is the second place that specifies the smallness of the Lipschitz constant.) After applying it to \eqref{pressure_bound_est} we get the following
\EQS{\label{pressure_3}
\|\pi_3\|_{4/3,V}\le 2c\|\gamma'\|_{\infty}\|\pi_1+\pi_2+\pi_4\|_{4/3,V}.
}

Let $\Om^\sharp$ be the pre-image of $V$ under the map \eqref{change-var} in $x$-variables.
The pressure component $\pi_i$ can be considered functions on $\Om^\sharp$ and since \eqref{change-var} has determinant 1 and $\|\nabla_y u\|_{4/3,V}\le 2\|\nabla_x u\|_{4/3,\Omega^\sharp}$, by assumption $\|\gamma'\|_{\infty}\le 1$ we have
\EQS{\label{pressure-est}
\norm{\pi-(\pi)_{V}}_{4/3, \Om^\sharp} &\le {\textstyle\sum}_{i=1}^4 \norm{\pi_i}_{4/3, \Om^\sharp}
={\textstyle\sum}_{i=1}^4 \norm{\pi_i}_{4/3, V}
\\
&\le c\|\nabla _y u\|_{4/3,V} +c \|u\otimes b\|_{4/3,V} +c \|\GG\|_{4/3,V}
\\
&\le c(1+ \| b\|_{L^{2,\infty}(V)}) (\|\nabla_y u\|_{4/3,V} +\| u\|_{4/3,V} )+ c \|\GG\|_{4/3,V}
\\
&\le c(1+ \| b\|_{L^{2,\infty}(\Omega)}) (\|\nabla_x u\|_{4/3,\Omega^\sharp} +\| u\|_{4/3,\Omega^\sharp} )+ c \|\GG\|_{4/3,\Omega^\sharp}.
}
This pressure estimate is the only purpose of our change of variables \eqref{change-var}. Noting that $\Om_{5/8}\subset \Om^\sharp\subset \Om_1$, we then proceed the following.

 Let $\eta$ be a cutoff function supported in $B_{5/8}(x_0)$ such that $\eta=1$ on $B_{1/2}(x_0)$. Due to our boundary condition $u|_{\partial\Omega}=0$ we can use function $\eta^4u$ as an admissible test function in \eqref{drifteq}. Therefore we get the following local energy inequality
\EQS{\label{eq5.19}
\int_{\Om_1} |\nabla (\eta^2u)|^2
&\le \int_{\Om_1} |u|^2|\nabla \eta^2|^2+\int_{\Om_1} |u|^2|b||\nabla \eta|\eta^3\\
&\quad +\int_{\Om_1} |\pi-(\pi)_{V}||u||\nabla\eta|\eta^3-\int_{\Om_1} \GG :\nabla(u\eta^4).
}
Using \eqref{pressure-est} to bound the pressure term and similarly to internal case
using Lemmas \ref{Holder} and \ref{Sobolev} in $\Om_1$, with uniform constant $C_2$ in Lemma \ref{Sobolev} using $\eta^4u\in W^{1,2}_0(\Om_1)$, we get
\EQS{\label{5.16}
\int_{\Om_{1/2}} |\nabla u|^2 &\le C(b)(\|\nabla u\|^2_{4/3,\Om_1}+\|u\|_{2,\Om_1}^2)+c\|\GG\|_{2,\Om_1}^2.
}
Notice that here the constant $C(b)$ does not depend on $\Om_1$.
Finally we extend function $u,\GG$ by zero to  $B_1(x_0)\setminus \Omega$. Since $u=0$ on the set $E:=\Om^c\cap B_1(x_0)$ of non zero measure with the ratio $\frac{|E|}{|B_{1}|}$ bounded from below, we can use Poincar\'e inequality to bound $\|u\|_{2,\Om_1}^2 \le c \|\nabla u\|^2_{4/3,\Om_1}$, with a constant independent of $\Om_1$ with the given lower bound of the ratio.
(This version of Poincar\'e inequality follows from Proposition 6.14 of \cite[page 116]{Lieberman},  with $f=\al 1_E$, nt_{B_1} f=1$. It gives $\norm{u}_{4/3,B_1} \le C\al  \norm{\nabla u}_{4/3,B_1} $.
We also have
$\norm{u}_{4,B_1} \le C \norm{u}_{W^{1,4/3}(B_1)}$.)

We also re-scale the inequality for arbitrary $B_r(x_0)$ and get \eqref{5.12}.

\medskip
Lastly we need to consider the case of arbitrary $x_0,r$ such that $\Om^c\cap B_{2r}(x_0)\neq\emptyset$. For any such $x_0$ we can find $y_0\in\partial\Om\cap B_{2r}(x_0)$ such that
\EQ{
B_r(x_0)\subset B_{3r}(y_0)\subset B_{6r}(y_0)\subset B_{8r}(x_0).
}
Using \eqref{5.12} for $B_{3r}(y_0)$ (assuming $6r<R_0$) we get
\EQS{\label{5.17}
\frac{1}{|B_r|}\int_{B_r(x_0)} |\nabla u|^2
&\le \frac{C}{|B_{3r}|}\int_{B_{3r}(y_0)} |\nabla u|^2
\\
&\le c(b) \Big(\frac{1}{|B_{6r}|}\int_{B_{6r}(y_0)}|\nabla u|^{\frac{4}{3}}\Big)^{\frac{3}{2}}+\frac{C}{|B_{6r}|}\|\GG\|_{L^2(B_{6r}(y_0))}^2
\\
& \le c(b) \Big(\frac{1}{|B_{8r}|}\int_{B_{8r}(x_0)}|\nabla u|^{\frac{4}{3}}\Big)^{\frac{3}{2}}+\frac{C}{|B_{8r}|}\|\GG\|_{L^2(B_{8r}(x_0))}^2.
}

For Gehring's lemma we combine the internal estimate \eqref{5.12} and the boundary estimate \eqref{5.17} and conclude that
\EQ{\label{5.19}
\frac{1}{|B_r|}\int_{B_r(x_0)} |\nabla u|^2 \le
c(b) \Big(\frac{1}{|B_{8r}|}\int_{B_{8r}(x_0)}|\nabla u|^{\frac{4}{3}}\Big)^{\frac{3}{2}}+\frac{C}{|B_{8r}|}\|\GG\|_{L^2(B_{8r}(x_0))}^2,
}
for any $x_0$ in a big cube containing $\overline \Om$, and any $r\le R_0/6$.
We can now apply Proposition 1.1 of Giaquinta \cite[page 122]{Gia} (also see \cite[Proposition 3.7]{DongKim}) to get that $\nb u \in L^p_\loc$ for $p \in (2,p_0)$ for some $p_0 >2$, and
\EQ{\label{0619}
nt_{B_r(x_0)} |\nabla u|^p}^{\frac 1p} \le
nt_{B_{8r}(x_0)} |\GG|^p}^{\frac 1p},
}
for all $x_0 \in \overline \Om$ and $r\le R_0/6$, with
$p_0$ and $c_1$ depending only on $c(b)$. Summing \eqref{0619} over a finite cover of $\overline \Om$ of balls of radius $R_0/6$,
we get \eqref{eq5.1}.
\end{proof}

ref_dict.main2-eq:
\begin{theorem}\label{th1.2}
  Let $\Om$ be a bounded Lipschtiz domain in $\RR^2$.  Assume $b\in L^{2,\infty}(\Omega)$ and $\div b=0$.
Then there exists $p_0(\|b\|_{L^{2,\infty}})>2$ such that for any $p_0'<q<p_0$ and $G\in L^q(\Om)$, there exists a  weak solution pair $u\in W^{1,q}_{0,\si}(\Omega)$ of \eqref{scalar.eq} such that
\EQ{\label{main2-eq}
\|u\|_{ W^{1,q}(\Omega)}\le C(\Omega,\|b\|_{L^{2,\infty}})\|G\|_{L^q(\Omega)}.
}
For $p_0'<q<p_0$, the above solution $u$ is the unique weak solution in $W^{1,q}_0(\Om)$ without assuming \eqref{main2-eq}.
\end{theorem}

ref_dict.main1:
\begin{theorem}\label{main1}
Let $\Om$ be a bounded Lipschitz domain in $\R^2$ with Lipschitz constant $L < L_0$, where $0<L_0<1$ is a sufficiently small constant. Assume $b\in L^{2,\infty}(\Omega)^2$ and $\div b=0$.
Then there exists $p_0(\|b\|_{L^{2,\infty}})>2$ such that for any $p_0'<q<p_0$ and $\GG\in L^q(\Om)^{2\times 2}$, there exists a  weak solution pair $u\in W^{1,q}_{0,\si}(\Omega)$ and $\pi\in L^q_0(\Omega)$ of \eqref{drifteq} such that
\EQ{\label{main1-eq}
\|u\|_{ W^{1,q}(\Omega)}+\|\pi\|_{L^q(\Omega)}\le C(\Omega,\|b\|_{L^{2,\infty}})\|\GG\|_{L^q(\Omega)}.
}
For $p_0'<q<p_0$, the above pair $(u,\pi)$ is the unique weak solution pair  in $W^{1,q}_0\times L^q_0(\Om)$ without assuming \eqref{main1-eq}.
\end{theorem}

ref_dict.scalar.eq:
\begin{theorem}\label{main1}
Let $\Om$ be a bounded Lipschitz domain in $\R^2$ with Lipschitz constant $L < L_0$, where $0<L_0<1$ is a sufficiently small constant. Assume $b\in L^{2,\infty}(\Omega)^2$ and $\div b=0$.
Then there exists $p_0(\|b\|_{L^{2,\infty}})>2$ such that for any $p_0'<q<p_0$ and $\GG\in L^q(\Om)^{2\times 2}$, there exists a  weak solution pair $u\in W^{1,q}_{0,\si}(\Omega)$ and $\pi\in L^q_0(\Omega)$ of \eqref{drifteq} such that
\EQ{\label{main1-eq}
\|u\|_{ W^{1,q}(\Omega)}+\|\pi\|_{L^q(\Omega)}\le C(\Omega,\|b\|_{L^{2,\infty}})\|\GG\|_{L^q(\Omega)}.
}
For $p_0'<q<p_0$, the above pair $(u,\pi)$ is the unique weak solution pair  in $W^{1,q}_0\times L^q_0(\Om)$ without assuming \eqref{main1-eq}.
\end{theorem}

\emph{Comments on Theorem \ref{main1}:}
\EN{
\item This theorem extends the higher dimensional result \cite[Theorem 1.5]{CT1} to the dimension 2 case.
In \cite[Theorem 1.5]{CT1} we take $L_0=1/2$. In this paper $L_0$ is specified after \eqref{change-var} and after \eqref{pressure_bound_est}, and is computable.
We skip in this paper the analogous results for small $b$ case (but full range $1<q<\infty$) as in \cite[Proposition 1.3, Theorem 1.4]{CT1}.

\item  Since $\Om$ is Lipschitz we can assume that there exists $R_0>0$ such that for any $x_0\in \partial\Om$ we have
\EQ{
\Om\cap B_{2R_0}(x_0)=\{(x',x_n)\in B_{2R_0}(0),x_n>\gamma(x')\}.
}
The constant $C$ in \eqref{main1-eq} will actually depend only on $R_0$, $\text{diam}~\Om$, and $\|b\|_{L^{2,\infty}}$.

\item If we further assume $b \in L^2(\Om)$
and $b$ has a divergence-free extension to $L^2(\R^2)$,
then there is another way to prove uniqueness of the weak solution in $W^{1,2}_{0,\si}(\Om)$ by using Hardy-BMO duality, even when the Lipschitz constant of $\Om$ is large.
See Theorem \ref{energy_2} in Section \ref{sec3}.

\item We may simply assume $\Om$ is a bounded $C^1$ domain, as for
a bounded $C^1$ domain and any constant $\lambda>0$, each point $x$ on $\pd\Om$ has a neighborhood $U_x$ such that $\pd \Om \cap U_x$ is the graph of a Lipschitz function with a Lipschitz constant less than $\lambda$.

}

For corresponding results on scalar equations
\EQ{\label{scalar.eq}
-\Delta u +b\cdot\nabla u=\div  G, \quad u|_{\pd \Om}=0,
}
with critical drift coefficient $b \in L^n$, see
Kim \& Kim \cite{KK}. When $b \in L^{n,\infty}(\Om)$ for $n \ge 3$, see \cite{KiTs,KPT} which also cover more general assumptions on drift $b$ as well as \cite{CS20,CS24} and Kwon \cite{Kwon} for $n=2$ case or drift in Morrey spaces which include $L^{n,\infty}$.
There are also results on H\"older continuity of the solutions, for example with $b\in BMO^{-1}(\R^3)$, $\div b=0$, see Seregin-Sverak-Silvestre-Zlatos \cite{SSSZ}.

Using the same proof scheme we can also prove the following theorem for the  scalar equation \eqref{scalar.eq}.
\begin{theorem}\label{th1.2}
  Let $\Om$ be a bounded Lipschtiz domain in $\RR^2$.  Assume $b\in L^{2,\infty}(\Omega)$ and $\div b=0$.
Then there exists $p_0(\|b\|_{L^{2,\infty}})>2$ such that for any $p_0'<q<p_0$ and $G\in L^q(\Om)$, there exists a  weak solution pair $u\in W^{1,q}_{0,\si}(\Omega)$ of \eqref{scalar.eq} such that
\EQ{\label{main2-eq}
\|u\|_{ W^{1,q}(\Omega)}\le C(\Omega,\|b\|_{L^{2,\infty}})\|G\|_{L^q(\Omega)}.
}
For $p_0'<q<p_0$, the above solution $u$ is the unique weak solution in $W^{1,q}_0(\Om)$ without assuming \eqref{main2-eq}.
\end{theorem}

