\section{Transformation maps}
\label{TransMaps}

In this section, we introduce the transformation maps that serve as real-valued versions of the conformal maps $z \mapsto z^\al$.
Once the maps are defined, we show how they transform solutions to elliptic PDEs and how they transform balls.
These results will be used at the beginning and at the end of the proof of Theorem \ref{mainThm}.

Given $z = (x,y) \in \R^2$ in Cartesian coordinates, the polar coordinates for $z$ are $(r, \te) \in \R_+ \times (-\pi, \pi]$, where $r = \sqrt{x^2 + y^2}$ and $\te = \sgn(y) \arccos\pr{\frac x r}$.
Let $\R^2_+ = \set{z = (r,\te) : r > 0, \te \in (- \frac \pi 2, \frac \pi 2)}$ denote the right half-plane.
For $\al \in (1, \iny)$, we define $T_\al : \R^2 \to \R^2$ to be the map associated to the conformal transformation on $\C$ given by $z \mapsto z^\al$. 
In polar coordinates, $T_\al$ is described as
\begin{equation}
\label{TalDefn}
T_\al(r, \te) = (r^\al, \al \te).
\end{equation}
To avoid continuity issues at $\te = \pi$, we restrict the domain and only consider $T_\al : \R^2_+ \to \R^2$.

\begin{lem}[Transformation of PDEs]
\label{transformEqLemma}
If $u : \R^2 \to \R$ is a solution to \eqref{ellipEq}, then with $v : \R^2_+ \to \R$ and $W : \R^2_+ \to \R$ defined by $v(z) = u(T_\al(z))$ and $W(z) = \al^2 \abs{z}^{2\al - 2} V(T_\al(z))$, it holds that
$$-\LP v + W v = 0 \; \text{ in } \R^2_+.$$
\end{lem}

\begin{proof}
Let $w := T_\al(z)$ be given in polar coordinates by $\pr{\rho, \vp}$.
Since $u$ is defined on $\R^2$, then in polar coordinates, $u(\rho, \vp)$ can be defined for all $\rho \in \R^+$ and all $\vp \in \R$ using periodicity.
We then see that $v(z) = v(r, \te) = u(r^\al, \al \te) = u(T_\al(z))$ is well-defined on $\R^2_+$. 
Since
\begin{align*}
\del_r v(r, \te) &= \al r^{\al - 1} \del_\rho u(\rho, \vp) \\
\del_{r}^2 v(r, \te) &= \al^2 r^{2\al - 2} \del_{\rho}^2 u(\rho, \vp) + \al \pr{\al - 1} r^{\al - 2} \del_\rho u(\rho, \vp) \\
\del_{\te}^2 v(r, \te) &= \al^2 \del_{\vp}^2 u(\rho, \vp),
\end{align*}
then
\begin{align*}
\LP v(z)
&= \del_{r}^2 v(r, \te) + \frac 1 r \del_{r} v(r, \te) + \frac 1 {r^2} \del_{\te}^2 v(r, \te) \\
&= \al^2 r^{2\al - 2} \del_{\rho}^2 u(\rho, \vp) + \al \pr{\al - 1} r^{\al - 2} \del_\rho u(\rho, \vp)
+ \al r^{\al - 2} \del_\rho u(\rho, \vp)
+ r^{-2} \al^2 \del_{\vp}^2 u(\rho, \vp) \\
&= \al^2 r^{2\al - 2} \brac{\del_\rho^2 u(\rho, \vp) + \rho^{-1} \del_\rho u(\rho, \vp) + \rho^{-2}\del_{\vp}^2 u(\rho, \vp)} \\
&= \al^2 r^{2\al - 2} \LP u(w) 
=  \al^2 r^{2\al - 2} V(w) u(w),
\end{align*}
where we have used \eqref{ellipEq}.
With $W(z) = \al^2 \abs{z}^{2\al - 2} V(T_\al(z)) = \al^2 r^{2\al - 2} V(w)$ as given, the conclusion follows.
\end{proof}

\begin{lem}[Ball containment]
\label{ballContainLemma}
Let $z_0 = (r_0, 0)$ and set $\disp \tilde r = \frac{r_0^{1 - \al}}{2 \sqrt 3 \al}$.
There exists $r_\al > 0$ so that whenever  with $r_0 \ge r_\al$, it holds that $T_\al(B_{\tilde r}(z_0)) \su B_1(T_\al(z_0))$ and $B_1(T_\al(z_0)) \su T_\al\pr{B_1(z_0)}$.
\end{lem}

\begin{proof}
With $\tilde r$ as given, it can be shown that
\begin{equation}
\label{ballIn} 
\begin{aligned}
B_{\tilde r}(z_0) 
&\su \set{r \in [r_0 - \tilde r, r_0 + \tilde r], \abs{\te} \le \frac {2\tilde r} {\sqrt 3 r_0}} \\
&= \set{r \in \brac{r_0\pr{1 -  \frac{r_0^{- \al}}{2 \sqrt 3 \al}}, r_0\pr{1 +  \frac{r_0^{- \al}}{2 \sqrt 3 \al}}}, \abs{\te} \le \frac {1} {3 \al r_0^\al}}.
\end{aligned}
\end{equation}
With $w_0 = T_\al(z_0)= \pr{r_0^\al, 0} = \pr{\rho_0, 0}$, it follows from \eqref{ballIn} that
\begin{align*}
T_\al(B_{\tilde r}(z_0)) 
&\su \set{r^\al \in \brac{r_0^\al\pr{1 -  \frac{r_0^{- \al}}{2 \sqrt 3 \al}}^\al, r_0^\al \pr{1 +  \frac{r_0^{- \al}}{2 \sqrt 3 \al}}^\al}, \abs{\al \te} \le \frac {\al} {3 \al r_0^\al}} \\
&= \set{\rho \in \brac{\rho_0 \pr{1 - \frac{\rho_0^{- 1}}{2 \sqrt 3 \al}}^\al, \rho_0 \pr{1 + \frac{\rho_0^{- 1}}{2 \sqrt 3 \al} }^\al}, \abs{\vp} \le \frac {1} {3 \rho_0} }.
\end{align*}
Since
\begin{align*}
\rho_0 \pr{1 \pm \frac{\rho_0^{- 1}}{2 \sqrt 3 \al} }^\al
&= \rho_0 \pm \frac{1}{2 \sqrt 3} + \frac{(1 - \frac 1 \al)}{24} r_0^{- \al} + \ldots 
\end{align*}
then there exists $r_1(\al) \gg 1$ so that whenever $r_0 \ge r_1$, we have $\rho_0 - \frac 1 2 \le \rho_0 \pr{1 - \frac{\rho_0^{- 1}}{2 \sqrt 3 \al} }^\al$ and $\rho_0 \pr{1 + \frac{\rho_0^{- 1}}{2 \sqrt 3 \al} }^\al \le \rho_0 +\frac 1 2$.
Because,
\begin{align}
&B_1(w_0)  \supset \set{\rho \in \brac{\rho_0 - \frac 1 2, \rho_0 + \frac 1 2}, \abs{\vp} \le \frac 1 {3\rho_0} },
\label{ballOf}
\end{align}

