\subsection{The negative eigenvalues of $\mathcal{L}_n$ :Proof of Theorem \ref{th1.3}}
In this subsection, our goal is to prove the Theorem \ref{th1.3}.
\begin{proof}[\textbf{Proof of Theorem \ref{th1.3}}]
 The linearized operators around the $n$-solitons $\mathcal{L}_{n} = S_{n}^{\prime\prime}(U^{(n)})$ possess $\left[\frac{n+1}{2}\right]$ negative eigenvalues, as previously verified in (\ref{3.47}). We now prove the expression (\ref{negetive}) for these eigenvalues. As $t\to \infty$, the spectrum $\sigma(\mathcal{L}_{n}(t))$ converges to the union of the spectra $\sigma(\mathcal{L}_{n,j})$ where $\mathcal{L}_{n,j} = S_{n}^{\prime\prime}(Q_{c_{j}})$, that is
 \begin{align}
 \sigma(\mathcal{L}_{n}(t)) \rightarrow \bigcup_{j=1}^{n} \sigma(\mathcal{L}_{n,j}), \quad \text{as} \quad t \rightarrow +\infty.
 \end{align}
 Since the operators $\mathcal{L}_{n}(t)$ are isoinertial for each $n$, the spectrum $\sigma(\mathcal{L}_{n}(t))$ is independent of $t$. Thus, the negative eigenvalues of $\mathcal{L}_{n}$ match those of $\mathcal{L}_{n,j}$ for all $j = 1, 2, \dots, n$. According to Lemma \ref{lem3.5}, $\mathcal{L}_{n,j}$ has negative eigenvalues when $j = 2k-1$ and $1 \leq k \leq \left[\frac{n+1}{2}\right]$. Specially, when $n=1$, one has $\mathcal{L}_1=L_1$. Therefore, (\ref{n=1}) indicates that $\mathcal{L}_1$ has the negative $\lambda_1<0$. With the methods in \cite{BBSSB}, we could compute $\lambda_1$, which is
 \begin{align}\label{1.30}
 \lambda_1=-\frac{c-\frac{1}{\delta}}{2a^2\sin^2(a\delta)}<0,
 \end{align}
 Then for $n=2$, we have
 \begin{align}\label{lamb}
 \mathcal{L}_{2,1}=(\mathcal{R}(Q_{c_1})+c_2)\mathcal{S}_1''(Q_{c_1}).
 \end{align}
In terms of Lemma \ref{lem3.2}, the operator $(\mathcal{R}(Q_{c_1}) + c_{2})$ has an eigenvalue $c_{2} - c_{1} > 0$, with continuous spectrum $(c_2, +\infty)$ whose generalized eigenfunctions are not in $L^{2}(\mathbb{R})$. Therefore, the unique negative eigenvalues of $\mathcal{L}_{2,1}$ is $(c_2-c_1)\lambda_1<0$.\\
Assuming the result holds for $n = p$, namely, the $\left[\frac{p+1}{2}\right]$-th negative eigenvalue of $\mathcal{L}_{p}$ is
 \begin{align}\label{4.48}
 \lambda_{k}^{(p)} = -M^\delta (c_{2k-1}-\frac{1}{\delta}) \prod_{j \neq 2k-1}^{p} (c_{j} - c_{2k-1}), \quad k = 1, 2, \dots, \left[\frac{p+1}{2}\right].
 \end{align}
Then for $n = p+1$ is even, we have $\left[\frac{p+1}{2}\right] = \left[\frac{p+2}{2}\right]$ and for $k = 1, 2, \dots, \left[\frac{p+1}{2}\right]$, we have
 \begin{align}
 \mathcal{L}_{p+1,2k-1} =(\mathcal{R}(Q_{c_{2k-1}}) + c_{p+1}) \mathcal{S}_{p}^{\prime\prime}(Q_{c_{2k-1}}).
 \end{align}
 By Lemma \ref{lem3.2}, the operator $(\mathcal{R}(Q_{c_{2k-1}}) + c_{p+1})$ has an eigenvalue $c_{p+1} - c_{2k-1} > 0$, with continuous spectrum $(c_{p+1}, +\infty)$ whose generalized eigenfunctions are not in $L^{2}(\mathbb{R})$. Therefore, the $\left[\frac{p+2}{2}\right]$-th negative eigenvalues of $\mathcal{L}_{p+1,2k-1}$ is
 \begin{align}\label{4.50}
 \lambda_{k}^{(p+1)}= -M^\delta (c_{2k-1}-\frac{1}{\delta}) \prod_{j \neq 2k-1}^{p+1} (c_{j} - c_{2k-1}), \quad k = 1, 2, \dots, \left[\frac{p+1}{2}\right].
 \end{align}
For the case where $n = p+1$ is odd, we have $\left[\frac{p+1}{2}\right] + 1 = \left[\frac{p+2}{2}\right]$. The first $\left[\frac{p+1}{2}\right]$ negative eigenvalues of $\mathcal{L}_{p+1}$ are given by expression (\ref{4.50}). We now compute the final negative eigenvalue. Consider
\begin{align}
 \mathcal{L}_{p+1,p+1} =\left( \mathcal{R}(Q_{c_{p+1}}) + c_{j} \right) \tilde{S}_{p}^{\prime\prime}(Q_{c_{p+1}})
\end{align}
where $\tilde{S}_{p}$ denotes the action with wave speed $c_j$ in $S_p$ replaced by $c_{p+1}$ for some $1 \leq j \leq p$. By assumption (\ref{4.48}), the discrete eigenvalue of $\tilde{S}_{p}^{\prime\prime}(Q_{c_{p+1}})$ is
\begin{align}
 -M^\delta (c_{p+1}-\frac{1}{\delta})\prod_{l \neq j}^{p} (c_l - c_{p+1}).
\end{align}
The operator $\mathcal{R}(Q_{c_{p+1}}) + c_j$ has eigenvalue $c_j - c_{p+1} < 0$ by Lemma \ref{lem3.2}, with continuous spectrum $(c_j, +\infty)$ whose generalized eigenfunctions are not in $L^2(\mathbb{R})$. Therefore, the last negative eigenvalue of $\mathcal{L}_{p+1}$ is
\begin{align*}
 \lambda_{\left[\frac{p+2}{2}\right]}^{(p+1)} = -M^\delta (c_{p+1}-\frac{1}{\delta}) \prod_{l=1}^{p} (c_l - c_{p+1}).
\end{align*}
The proof of Theorem \ref{th1.3} is completed by combining the eigenvalue expressions.
\end{proof}

