\begin{theorem}[Preclusion of multiple positive zeros]\label{thm:mono}
 Let $F=( C (\k \circ x^M), Lx-b) \in \R[\k,b,x^\pm]^n$ be an augmented vertical system with $C\in \R^{\bs\times \bar{m}}$ principal and $L$ of full row rank.  Let  $(\tau,r,\gamma')$ and $(\alpha,c,\gamma)$ be  row and column partitions, and consider the  associated simplified reduced matrix $P\in \R^{s\times \ell}$ from \eqref{def:simpif_reduced_matrix}. 

 If $\mathcal{C}_{\mathcal{S}}^\sigma = \varnothing$ for all orientations $\sigma \in \{-1,0,1\}^{2 \times \ell}$   compatible with $\alpha$ and  all  $\mathcal{S}\in \{-1,0,1\}^{s\times \ell}$
 that are feasible with respect to $(P,\sigma)$, then $F$ does not admit multiple positive zeros for any choice of parameter values.
\end{theorem}

ref_dict.thm:full:
\begin{theorem}[Characterization of multiple positive zeros when $P$ induces a forest]\label{thm:full}
Let $F=( C (\k \circ x^M), Lx-b) \in \R[\k,b,x^\pm]^n$ be an augmented vertical system with $C\in \R^{\bs\times \bar{m}}$ principal and $L$ of full row rank. 
Let  $(\tau,r,\gamma')$ and $(\alpha,c,\gamma)$ be  row and column partitions, and assume that the associated simplified reduced matrix $P\in \R^{s\times \ell}$ from \eqref{def:simpif_reduced_matrix} induces a forest. 

 Then, $F$ admits multiple positive zeros for some  parameter values $\k\in \R^{\bar{m}}_{>0}$, $b\in \R^{n-\bs}$  if and only if there exist an orientation $\sigma \in \{-1,0,1\}^{2 \times \ell}$ compatible with $\alpha$ and a sign matrix  $\mathcal{S}\in \{-1,0,1\}^{s \times \ell}$ that is feasible with respect to $(P,\sigma)$  such that 
$ \mathcal{C}_{\mS}^\sigma \neq \varnothing$.
\end{theorem}

