\Lam(\frakp) \arrow[ddd, -] \arrow[uurrrrr, ->, bend right=35, "\sig\, =\, \rho_{\mathrm{tf}}|_{\Lam(\frakp)}" {xshift=6em, yshift=-0.5em}] & & \\
