The homomorphism  $$P_t^{vir}: K_0(Var_\R) \rightarrow \Z[t] \subset \Z((t^{-1}))$$  is constructed by McCrory and Parusinski \cite{MP}.   Since $P_t^{vir}(\mathbb{L} ) = -t$   and $P_t^{vir}(\mathbb{L}^n -1)) = (-t)^n-1$ are both invertible in $\Z((t^{-1}))$, with $((-t)^n-1)^{-1} = (-t)^{-n} (\sum_{k=0}^{\infty} (-t)^{-kn})$, this extends to a homomorphism  $$P_t^{vir}: Mot(\R) \rightarrow   \Z((t^{-1})),$$  
which extends naturally to the dimensional completion.
\end{proof}

The zeta function of a variety $X$ is given by the formal power series
$$Z_X(z)  := \sum_{n=0}^\infty  [X^{(n)} ]z^n  \in  Mot(k) [[z]],  $$
where $X^{(n)}  = X^n/S_n $ denotes the $n$-fold symmetric product of $X$.  The zeta function is multiplicative in the sense that for closed $Y \subseteq X$,  $$ Z(X, z) = Z(Y,z) Z(X\setminus Y, z).$$ 

If $\Sigma/k$ is a smooth projective curve of genus $g$ and $\Sigma(k) \neq \emptyset$, then a theorem of Kapranov (\cite{K}  Theorem 1.1.9) says that

$$ Z_\Sigma(z) =  \frac{P(z)}{(1-z)(1-\mathbb{L}z)} $$ 
where $P(z)$ is a polynomial of degree $2g$ such that  $Z_\Sigma ( 1/\mathbb{L}z) = \mathbb{L}^{1-g} x^{2-2g} Z_\Sigma(z)$. The homomorphism (\ref{evsigma}) is determined by the property that 
$ \prod_{i=1}^g (1-\alpha_i z)(1-\alpha_i^{-1}qz)$ is sent to $P(z)$ in some algebraic extension of $\overline{Mot}(k)$  

\section{Betti numbers of $\Sigma^{(n)}(\R)$}\label{Betti numbers of}

Suppose that $\Sigma$ is a smooth, geometrically connected, projective curve of genus $g$ over $\R$. For $n \geq 0$ denote by $\Sigma^{(n)}$ its $n$-th symmetric product. The set of complex points $\Sigma^{(n)}(\C)$ can be identified with the orbit space $$ Sym^n( \Sigma(\C)) := \Sigma(\C)^n/ S_n, $$  while $\Sigma^{(n)}(\R) \subset \Sigma^{(n)}(\C)$ can be identified with $Gal(\C/\R)$ fixed points. 

If $\Sigma(\R)$ is empty, then  
$$ \Sigma^{(n)}(\R) \cong  \begin{cases}  \emptyset  &  \text{if $n$ is odd} \\  Sym^{n/2}(N_g) & \text{if $n$ is even} \end{cases}$$
where $N_g$ is a non-orientable surface double covered by $\Sigma(\C)$.  We abusively write $ P_t(X)  :=  \sum_{k}  (-t)^k H_{cpt}^k(X;\Z_2)$.  By Macdonald's formula \cite{Mac},
\begin{equation}\label{MacDs}
 \sum_{m=0}^\infty P_t( Sym^{m}(N_g)) z^m = \frac{ (1-tz)^{g+1} }{(1-z)(1-t^2z)},
 \end{equation}
 so

$$ P_t^{vir}(Z_\Sigma (z)) := \sum_{n=0}^{\infty} P_t ( \Sigma^{(n)} ) z^n =  \frac{ (1-tz^2)^{g+1} }{(1-z^2)(1-t^2z^2)}.$$

When $\Sigma(\R) \neq \emptyset$, $P_t(\Sigma^{(n)})$ was calculated in \cite{B}.  

\begin{prop}
If $\Sigma(\R)$ is non-empty, with $b+1$ many connected components, then
\begin{equation}\label{zetahom}
 P_t^{vir}(Z_\Sigma (z)) =   \sum_{n=0}^{\infty} P_t ( \Sigma^{(n)}) z^n   =  \frac{(1-tz^2)^{g-b} (1+z)^{b} (1-tz)^{b} }{(1-z)(1+tz)} .
 \end{equation}
\end{prop}

\begin{proof}

Suppose first that $ \Sigma(\C) \setminus \Sigma(\R)$ is connected.  For each pair of integers $k,s \geq 0$ such that $k+2s = n$, $\Sigma^{(n)}(\R)$ has $ { b+1 \choose k}$ connected components with Poincar\'e polynomial isomorphic to $(1-t)^k P_t( Sym^s(N_{g-k}))$.  Therefore, setting $a=b+1$, we have 

\begin{eqnarray*}
\sum_{n=0}^{\infty}  P_t(\Sigma^{(n)}) z^m  &=&  \sum_{0 \leq k \leq a} \sum_{s \geq 0}   z^{k+2s} { a \choose k}  (1-t)^k  P_t(  Sym^s(N_{g-k}))\\
&\stackrel{(\ref{MacDs})}{=}&  \sum_{0 \leq k \leq a}   z^{k} { a \choose k}   (1-t)^k \frac{(1-tz^2)^{g-k+1}}{(1-z^2)(1-t^2z^2)}\\
&=& \left(  (z -zt) + (1-tz^2) \right)^a  \frac{(1-tz^2)^{g-a+1}}{(1-z^2)(1-t^2z^2)} \\
&=&  \frac{(1-tz^2)^{g-a+1} (1+z)^{a-1} (1-tz)^{a-1}}{(1-z)(1+tz)} \\
\end{eqnarray*}

In case $\Sigma(\C) \setminus \Sigma(\R)$ is not connected, the calculation is the same except that whenever $k=a$, the corresponding component has Poincar\'e polynomial $(1-t)^{b+1}P_t(Sym^s(\Sigma_{(g-b)/2})) $, where $\Sigma_g$ is an orientable surface of genus $g$. But this equals $(1-t)^{b+1} P_t( Sym^s( N_{g-b-1}))$  (\cite{B} Remark 3.14) so the same formula holds.
\end{proof}

