\begin{equation} \label{codim k pde}
F(p, M):=\inf\bigg\{\!-\frac{1}{2}\mathrm{tr}(Ma):\, a\succeq 0,\, a p = 0,\, \lambda_{(n-k)}(a)\geq 1,\, \lambda_{(1)}(a)\leq L\bigg\}.
\end{equation}

