\begin{lemma}\label{prorot} 
Let $A\subset\R^d$ ($d\geq  3$) be a set with positive reach skewered on a segment $[p,q]\subset \R$ and let $r>0$ be such that  $0< r < \reach A$ and 
\begin{enumerate}
    \item[(a)] $\diam A < r$, or
    \item[(b)] $A\subset \R^2 \subset \R^d$ is a $B$-set.
\end{enumerate}	
Let $\rho$ be a multirotation associated with $T_1(A)$.
Then 
\begin{enumerate}
\item[(i)]
the mapping  $\rho|_A$ is bi-Lipschitz,
\item[(ii)]
 $\rho(A)$ is compact and $\reach \rho(A) > 0$,
\item[(iii)] $T_1(\rho(A))=T_1(A)$ and $\rho(A)$ is skewered on $[p,q]$.
\end{enumerate}  
\end{lemma}

