\begin{theoremL*} [Lytchak]
Let $A \subset \mathbb{R}^d$ be a $k$-dimensional set ($1\leq k\leq d$) with positive reach, $a \in A$, and let the tangent cone of $A$ at $a$ have dimension $k$. Then there exist a convex body $K\subset\mathbb{R}^k\subset \mathbb{R}^d$ (of dimension $k$), an open set $U\subset\mathbb{R}^d$ containing $K$ and a $C^{1,1}$-diffeomorphism $\Phi: U \to \mathbb{R}^d$ such that $\Phi(K)$ is a neighbourhood of $a$ in $A$.
\end{theoremL*}

Consider $r>0$ and Lipschitz functions
$\psi \leq 0 \leq \varphi$ on $[0,r]$ such that $\varphi$ is semiconcave on $(0,r)$, $\psi$
is semiconvex on $(0,r)$, $\varphi(0)= \psi(0)=0$, $\varphi'_+(0)= \psi'_+(0)=0$, and set
$B:= \{(x,y):\, x\in [0,r],\, \psi(x) \leq y \leq \varphi(x)\}$.
Then $B$ has positive reach (see Lemma~\ref{B_set_PR}).
We further perturbe $B\subset\mathbb{R}^2\subset\mathbb{R}^3$ to a set $M\subset \mathbb{R}^3$ by a ``multirotation'' by the following way.
We set $C:= \{x\in [0,r]: \varphi(x)=\psi(x)\}$, denote by $\Lambda$ the set of all components of $(0,r)\setminus C$ and for each $\lambda \in \Lambda$ denote $B_\lambda = \{(x,y) \in B:\ x\in \overline \lambda\}$. Now we rotate each $B_\lambda$ in $\mathbb{R}^3$ around the $x$-axis by an angle $\theta(\lambda)$ in the positive sense to a set $M_\lambda$ and set 
\begin{equation} \label{M}
 M:= (B\setminus \bigcup _{\lambda \in \Lambda} B_\lambda)
 \cup \bigcup _{\lambda \in \Lambda} M_\lambda.
\end{equation} 
Then $M$ has positive reach as well (it follows from Lemma~\ref{prorot}) and its tangent cone at $0$ is a half-line. It is easy to see that if $C$ is totally disconnected and $0$ is its accumulation point, we can choose the rotations $M_\lambda$ of $B_\lambda$ so that no neighbourhood of the origin in $M$ lies on a two-dimensional $C^{1,1}$ surface.

\begin{definition}[B-sets] \label{B-sets}
\begin{enumerate}
 \item[(i)] We call $M\subset \mathbb{R}^2$ a \emph{$\B_-$-set} if there exist $r>0$, Lipschitz functions $\psi \leq 0 \leq \varphi$ on $[0,r]$ such that $\varphi$ is semiconcave on $(0,r)$, $\psi$ is semiconvex on $(0,r)$, $\varphi(0)= \psi(0)=0$, $\varphi'_+(0)= \psi'_+(0)=0$ and $M= \{(x,y):\ x\in [0,r], \psi(x) \leq y \leq \varphi(x)\}$. 
 \item[(ii)] We call $M\subset \mathbb{R}^2$ a \emph{$\B_+$-set} if there exist $r>0$, Lipschitz functions $\psi \leq 0 \leq \varphi$ on $[-r,r]$ such that $\varphi$ is semiconcave on $(-r,r)$, $\psi$ is semiconvex on $(-r,r)$, $\varphi(0)= \psi(0)=0$, $\varphi'(0)= \psi'(0)=0$ and $M= \{(x,y):\ x\in [-r,r], \psi(x) \leq y \leq \varphi(x)\}$. 
 \item[(iii)] We say that $M\subset\mathbb{R}^2$ is a \emph{$\operatorname{B}$-set} if $M$ is a $\B_-$-set or a $\B_+$-set.
\end{enumerate}
\end{definition}

\begin{definition}[multirotations] \label{multrot}
Let $\emptyset\neq C\subset\operatorname{span}\{e_1\}\subset\mathbb{R}^d$ ($d\geq 3$) be a compact set and $\Lambda$ the family of all components (open intervals) of $\operatorname{span}\{e_1\}\setminus C$.
