Note that if $B$ is a B-set then, since it has positive reach, $T_1(B)$ is a compact subset of $\R=\spa\{e_1\}$ by Lemma~\ref{T_k}~(iii).

\begin{remark}
 It is easy to see that Theorem~\ref{T_main} holds if we replace ``$\dim A\leq 2$'' with ``$\dim A=2$'' at both occurrences. The only difference is in the proof of the ``moreover'' part: While in the first case we set in our proof $A:=\Phi(\rho(B))$, in the latter case we could take $A:=\Phi(\rho(B))\cup D$, where $\reach D>0$, $\dim D=2$ and $\dist(\Phi(\rho(B)),D)>0$. 
\end{remark}

\begin{corollary}
 Let $A\subset\R^d$ ($d\leq 3$) be a two-dimensional compact set. Then $A$ has positive reach if and only if for each non-isolated $a\in A$ there exist a compact set $K\subset\R^d$, an open set $K\subset U\subset\R^d$ and a $C^{1,1}$-diffeomorphism $\Phi:U\to\R^d$ such that $\Phi(K)$ is a neighbourhood of $a$ in $A$ and either 
 \begin{enumerate}
 \item[(a)] $K\subset\R^2\subset\R^d$ is convex two-dimensional, or
 \item[(b)] $K=\rho(B)$, where $B\subset\R^2\subset\R^d$ is a $\B$-set and $\rho:\R^d\to\R^d$ is a multirotation associated with $T_1(B)$.
 \end{enumerate} 
\end{corollary}

\begin{proposition} \label{T}
 Let $A\subset\R^d$ ($d\geq 3$) have positive reach, $\dim A\leq 2$ and $a\in T_1(A)$. Then there exists a $\B$-set $B$ and a multirotation $\rho$ associated with $T_1(B)$ such that $(A,a)\approx(\rho(B),0)$.
\end{proposition}

\begin{proposition} \label{T3}
 Let $S\subset\R^d$ ($d\geq 3$) with positive reach be a set skewered on $[c,d]$, $c<0<d$, with planar leaves, and $0\in T_1(S)$. Then there exists a $\B_+$-set $B$ and a multirotation $\rho$ associated with $T_1(B)$ such that $(S,0)\sim(\rho(B),0)$.
