\end{equation}
Further, there exists $0<\delta<r/4$ such that
\begin{equation} \label{S_delta}
 B(a,\delta)\subset U\text{ and }\Phi(B(a,\delta))\subset B(0,\ep).
\end{equation}
Denote $S_\delta:=S\cap B(a,\delta)=\{a+tu:\, -\delta< t< 0\}$.
Since $S\subset T_1(A^*)$, we obtain
$$\Phi(S_\delta)\subset \Phi(T_1(A^*)\cap U)\cap B(0,\ep) \subset T_1(\rho^*(B^*))$$
using Lemma~\ref{tkdif} and \eqref{AB}.
We have further $T_1(\rho^*(B^*))=T_1(B^*)\subset W$ by Lemma~\ref{prorot}~(iii) and Remark~\ref{Rem_listky}~(b), hence we get $\Phi(S_\delta)\subset W$. Since $\Phi(S_\delta)$ is homeomorphic to $(0,1)$ and $0\in\overline{\Phi(S_\delta)}\setminus \Phi(S_\delta)$, we have (a) $\Phi(S_\delta)=(-\ep',0)$ or (b) $\Phi(S_\delta)=(0,\ep')$ for some $0<\ep'\leq \ep$.
We claim that we can choose $B^*,\rho^*,\Phi,U,\ep$ and $\delta$ as above satisfying \eqref{AB} and \eqref{S_delta} such that the case (a) occurs. Indeed, if $B^*,\rho^*,\Phi,U,\ep$ and $\delta$ satisfy \eqref{AB}, \eqref{S_delta} and (b), consider the reflection $G:(x,z)\mapsto(-x,z)$ ($(x,z)\in\R\times\R^{d-1}$) and set $\tilde{B}^*:=G(B^*)$, $\tilde{\rho}^*:=G\circ\rho^*\circ G$, $\tilde{\Phi}:=G\circ\Phi$, $\tilde{U}:=U$, $\tilde{\ep}:=\ep$ and $\tilde{\delta}:=\delta$. Then both \eqref{AB} and \eqref{S_delta} remain true and it is easy to see that $\tilde{B}^*$ is again a $\B_+$-set (using Remark~\ref{rem_semicon}) and that $\tilde{\rho}^*$ is a multirotation associated with
 $T_1(\tilde{B}^*)$. Moreover, $\tilde{\Phi}(S_{\tilde{\delta}})=-\Phi(S_\delta)=(-\ep',0)$, i.e., case (a) occurs.

For the second statement of Theorem~\ref{T_main}, assume that $B\subset\R^2\subset\R^d$ is a $\B$-set, $\rho$ a multirotation associated with $T_1(B)$, $U$ an open neighbourhood of $\rho(B)$ and $\Phi:U\to\R^d$ a $C^{1,1}$-diffeomorphism. Then $B$ has positive reach by Lemma~\ref{B_set_PR} and it is clearly compact, hence $\rho(B)$ is compact and has positive reach by Lemma~\ref{prorot}~(ii). Setting $A:=\Phi(\rho(B))$, we have $\reach A>0$ by Lemma~\ref{reach_C11} and $a\in T_1(A)$ by Lemma~\ref{prorot}~(iii) and Lemma~\ref{tkdif}~(iii). This implies the second assertion of Theorem~\ref{T_main} and completes the proof.
\end{proof}

\begin{proof}[Proof of Corollary~\ref{bilip}] \hskip 2mm
 Let $A\subset\R^d$ be a two-dimensional set with positive reach and $a\in A$. 
 If $a\in T_0(A)$ then $a$ is an isolated point in $A$ and the assertion is obvious.
 If $a\in T_1(A)$ then we apply Theorem~\ref{T_main} and obtain a $\B$-set $B\subset\R^2$, a multirotation $\rho$ associated with $T_1(B)$, a neighbourhood $U$ of $\rho(B)$ in $\R^d$ and a $C^{1,1}$-diffeomorphism $\Phi:U\to\R^d$ such that $\Phi(\rho(B))$ is a neighbourhood of $a$ in $A$. 
 The set $\rho(B)$ is compact by Lemma~\ref{prorot}~(ii), hence $\Phi(\rho(B))$ is compact as well. Since both $\Phi$ and $\Phi^{-1}$ are locally Lipschitz (see Remark~\ref{stability}~(i)), their restrictions to compact sets $\rho(B)$ and $\Phi(\rho(B))$ (respectively) are Lipschitz by \cite[Proposition~A48]{Lee}, i.e., $\Phi$ is bi-Lipschitz on $\rho(B)$.
 Since $\rho$ is bi-Lipschitz on $B$ by Lemma~\ref{prorot}~(i), we can choose $\Psi:=\Phi\circ\rho|_B$ and the assertion follows.

