\begin{theorem}\label{mainth}
Let $\Sigma_{D_\alpha}$ be a family of cones as above, $\alpha\in(0,\alpha^*)$ and assume that $\lambda_1({D_1})=N-1$ is a simple eigenvalue. Then the point $(1,U)$ is a bifurcation point for the trivial curve $\alpha\mapsto(\alpha,U)$ of solutions to \eqref{printro}. More precisely there exist $\epsilon>0$ and a $C^1$ curve  $(-\epsilon,\epsilon)\ni s\to (\alpha_s,v_s)$,  such that $\alpha_0=1$, $v_0=U$, $D_{\alpha_s}\ne D_{\alpha_1}$ and
$$
\begin{cases}
   -\Delta v_s=v_s^{2^*-1} &\text{in }\Sigma_{D_{\alpha_s}}\\
    v_s\in \mathcal{{D}}^{1,2}(\Sigma_{D_{\alpha_s}}),
\end{cases}$$
and $v_s$ is positive and nonradial.
\end{theorem}

ref_dict.thvecchio:
\begin{theorem}\label{thvecchio}\cite{CPP}
    Let $\Sigma_D$ be a cone such that $\bar D\subset \S^{N-1}_+$ and $\lambda_1(D)<N-1$, where $\S^{N-1}_+$ is the half-sphere. Then the minimizers of the Sobolev quotient are nonradial and hence there exist nonradial solutions $v$ of \eqref{printro} which are also fast decaying, i.e.
    $$
    v(x)=O(|x|^{2-N}) \quad \text{as }|x|\to\infty.
    $$
\end{theorem}

ref_dict.CRT:
\begin{theorem}[Crandall-Rabinowitz Bifurcation Theorem] \label{CRT}
Let $X$ and $Y$ be Banach spaces, and let $\Omega\subset X$ and $I \subset \mathbb{R}$ be open domains, where we assume $0 \in \Omega$. Denote the elements of $\Omega$ by $v$ and the elements of $I$ by $t$. Let $F: I \times \Omega \to Y$ be a $C^2$ operator such that

\begin{itemize}
    \item[(i)] $F(t, 0) = 0$ for all $t \in I$,
    \item[(ii)] $\text{Ker} D_v F(t_*, 0) = \mathbb{R}w$ for some $t_* \in I$ and some $w \in X \setminus \{0\}$;
    \item[(iii)] $\text{codim} \, \text{Im} D_v F(t_*, 0) = 1$;
    \item[(iv)] $D_t D_v F(t_*, 0)(w) \notin \text{Im} D_v F(t_*, 0)$.
\end{itemize}

Then there exists a nontrivial $C^1$ curve
$$\quad (-\epsilon, \epsilon) \ni s \mapsto (t(s), v(s)) \in I \times X,
$$
for some $\epsilon > 0$, such that:
\begin{itemize}
    \item[(1)] $t(0) = t_*, \, t'(0) = 0, \, v(0) = 0, \, v'(0) = w$;
    \item[(2)] $F(t(s), v(s)) = 0$ for all $s \in (-\epsilon, +\epsilon)$.
\end{itemize}

Moreover, there exists a neighborhood $N$ of $(t_*, 0)$ in $X \times Y$ such that all solutions of the equation $F(t, v) = 0$ in $N$ belong to the trivial solution line $\{(t, 0)\}$ or to the curve. The intersection $(t_*, 0)$ is called a bifurcation point.

\end{theorem}

pre_theorem_intro_text:
Let $D$ be a smooth domain on the unit sphere $\mathbb{S}^{N-1}\subset\mathbb R^N$, with $N\geqslant 3,$ and let $\Sigma_D\subset\mathbb R^N$ be the cone spanned by $D$:
\begin{equation}\label{cono}
\Sigma_D=\{x\in\mathbb R^N: x=\rho p,p\in D,\rho\in(0,+\infty)\},
\end{equation}
and assume that $\Sigma_D$ is a Lipschitz domain.
We consider the following semilinear critical Neumann problem
\begin{equation}\label{printro}
\begin{cases}
    -\Delta u=u^{2^*-1}&\text{in }\Sigma_D,\\
    \frac{\partial u}{\partial\nu}=0&\text{on }\partial\Sigma_D\setminus\{0\},\\
    u>0&\text{in }\Sigma_D,
\end{cases}
\end{equation}
where $2^*=\frac{2N}{N-2}$ is the critical Sobolev exponent for the immersion $\mathcal{D}^{1,2}(\Sigma_D)$ into $L^{2^*}(\Sigma_D)$ and
$$
\mathcal{D}^{1,2}(\Sigma_D)=\{u\in L^{2^*}(\Sigma_D):|\nabla u|\in L^2(\Sigma_D)\}.
$$
