	\section{A priori estimates and zero mode estimates}\label{priori estimate}
	\subsection{Elliptic estimates for $c$}
	\begin{lemma}\label{lem:ck}
		Suppose that $|k|\geq 1$. Let
		\begin{equation}\label{eq:ck}
			\Big(\partial_{r}^{2}-\frac{k^{2}-\frac14}{r^{2}} \Big)c_{k}+n_{k}-c_{k}=0,\quad c_{k}|_{r=1,R}=0.
		\end{equation}
		Then it holds that
		\begin{equation*}
			\begin{aligned}
				&	\|\partial_{r}c_{k}\|_{L^{2}}+k\big\|\frac{c_{k}}{r} \big\|_{L^{2}}+\|c_{k}\|_{L^{2}}\leq C\|n_{k}\|_{L^{2}},\\
				&\|r^{2}\partial_{r}^{2}c_{k}\|_{L^{2}}+k^{2}\|c_{k}\|_{L^{2}}+k\|r\partial_{r}c_{k}\|_{L^{2}}\leq C(R) \|n_{k}\|_{L^{2}}
			\end{aligned}
		\end{equation*}
		and 
		\begin{equation*}
			\|c_{k}\|_{L^{\infty}}\leq C(R) \|n_{k}\|_{L^{2}}.
		\end{equation*}
	\end{lemma}
	\begin{proof}
		Multiplying (\ref{eq:ck}) by $-c_{k}$, the energy estimate shows that
		\begin{equation*}
			\|\partial_{r}c_{k}\|_{L^{2}}^{2}+\Big(k^{2}-\frac14 \Big)\big\|\frac{c_{k}}{r} \big\|_{L^{2}}^{2}+\|c_{k}\|_{L^{2}}^{2}=\langle n_{k}, c_{k} \rangle\leq \|n_{k}\|_{L^{2}}\|c_{k}\|_{L^{2}}.
		\end{equation*}
		This gives that
		\begin{equation}\label{ck kck}
			4\|\partial_{r}c_{k}\|_{L^{2}}^{2}+4k^{2}\big\|\frac{c_{k}}{r} \big\|_{L^{2}}^{2}+\|c_{k}\|_{L^{2}}^{2}\leq 2\|n_{k}\|_{L^{2}}^{2}.
		\end{equation}
		Due to (\ref{eq:ck}), there holds
		\begin{equation}\label{ck''}
			\begin{aligned}
				&\quad\|r^{2}\partial_{r}^{2}c_{k}\|_{L^{2}}^{2}+k^{4}\|c_{k}\|_{L^{2}}^{2}-2k^{2}\langle r^{2}\partial_{r}^{2}c_{k}, c_{k}\rangle=\|r^{2}\partial_{r}^{2}c_{k}-k^{2}c_{k}\|_{L^{2}}^{2}\\&=\Big\|\Big(r^{2}-\frac14 \Big)c_{k}-r^{2}n_{k} \Big\|_{L^{2}}^{2}\leq C\left(\|r^{2}c_{k}\|_{L^{2}}^{2}+\|r^{2}n_{k}\|_{L^{2}}^{2} \right).
			\end{aligned}
		\end{equation}
		Using integration by parts, $-2k^{2}\langle r^{2}\partial_{r}^{2}c_{k}, c_{k}\rangle$ can be controlled as
		\begin{equation*}
			\begin{aligned}
				2k^{2}\langle r^{2}\partial_{r}c_{k},\partial_{r}c_{k} \rangle+2k^{2}\langle 2r\partial_{r}c_{k}, c_{k}\rangle=2k^{2}\|r\partial_{r}c_{k}\|_{L^{2}}^{2}-2k^{2}\|c_{k}\|_{L^{2}}^{2}.
			\end{aligned}
		\end{equation*}
		This along with (\ref{ck kck}) and (\ref{ck''}) implies that
		\begin{equation}\label{ck k2}
			\begin{aligned}
				&\quad\|r^{2}\partial_{r}^{2}c_{k}\|_{L^{2}}^{2}+k^{4}\|c_{k}\|_{L^{2}}^{2}+2k^{2}\|r\partial_{r}c_{k}\|_{L^{2}}^{2}\\&\leq C\left(k^{2}\|c_{k}\|_{L^{2}}^{2}+\|r^{2}c_{k}\|_{L^{2}}^{2}+\|r^{2}n_{k}\|_{L^{2}}^{2} \right) \leq C R^{4}\|n_{k}\|_{L^{2}}^{2}.
			\end{aligned}
		\end{equation}
		By applying (\ref{ck kck}) and Gagliardo-Nirenberg inequality, one deduces
		\begin{equation*}
			\begin{aligned}
				\|c_{k}\|_{L^{\infty}}\leq C(R)\|c_{k}\|_{L^{2}}^{\frac12}\|\partial_{r}c_{k}\|_{L^{2}}^{\frac12}\leq C(R) \|n_{k}\|_{L^{2}}.
			\end{aligned}
		\end{equation*}
		By combining  (\ref{ck kck}) and (\ref{ck k2}), the proof is complete.
	\end{proof}

