\section{The $L^{\infty}$ estimate of the density and proof of Proposition \ref{prop:n infty}}\label{estimate infty}
 \begin{proof}[Proof of Proposition \ref{prop:n infty}] Multiplying $(\ref{ini1})_{1}$ by $2pn^{2p-1}$ with $p=2^{j} ~(j\geq 1)$, and integrating by parts the resulting equation over $[1,R]\times\mathbb{S}^{1}$, one obtains
 \begin{align}
 &\frac{d}{dt}\|n^{p}\|_{L^{2}}^{2}+\frac{2(2p-1)}{Ap}\Big\|\Big(\partial_{r}, \frac{1}{r}\partial_{\theta}\Big)n^{p}\Big\|_{L^{2}}^{2}\nonumber\\=&\frac{1}{A}\Big\|\frac{n^{p}}{r} \Big\|_{L^{2}}^{2}+\frac{1}{A}\int_{0}^{2\pi}\int_{1}^{R}\frac{1}{r^{2}}\partial_{\theta}\varphi n^{2p}dr d\theta+\frac{4p}{A}\int_{0}^{2\pi}\int_{1}^{R}\frac{1}{r}n^{p}c\partial_{r}n^{p}drd\theta\nonumber\\&-\frac{2p}{A}\int_{0}^{2\pi}\int_{1}^{R}\frac{1}{r^{2}}n^{2p}cdrd\theta+\frac{2(2p-1)}{A}\int_{0}^{2\pi}\int_{1}^{R}n^{p}\Big(\partial_{r}, \frac{1}{r}\partial_{\theta} \Big)c\cdot\Big(\partial_{r}, \frac{1}{r}\partial_{\theta} \Big)n^{p}drd\theta\nonumber\\\leq&\frac{1}{A}\left(1+\|\partial_{\theta}\varphi\|_{L^{\infty}L^{\infty}}+2p\|c\|_{L^{\infty}L^{\infty}} \right)\|n^{p}\|_{L^{2}}^{2}+\frac{4p}{A}\|n^{p}c\|_{L^{2}}\|\partial_{r}n^{p}\|_{L^{2}}\nonumber\\&+\frac{2(2p-1)}{A}\Big\|n^{p}\Big(\partial_{r},\frac{1}{r}\partial_{\theta}\Big)c\Big\|_{L^{2}}\Big\|\Big(\partial_{r},\frac{1}{r}\partial_{\theta}\Big)n^{p} \Big\|\nonumber\\\leq&\frac{1}{A}\left(1+\|\partial_{\theta}\varphi\|_{L^{\infty}L^{\infty}}+2p\|c\|_{L^{\infty}L^{\infty}} \right)\|n^{p}\|_{L^{2}}^{2}+\frac{Cp^{2}}{A}\Big\|n^{p}\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c\Big\|_{L^{2}}^{2}\nonumber\\&+\frac{2p-1}{Ap}\Big\|\Big(\partial_{r},\frac{1}{r}\partial_{\theta} \Big)n^{p} \Big\|_{L^{2}}^{2}.\label{np 1}
 \end{align}
 Due to (\ref{assumption}), Lemma \ref{lem:varphi k>0} and $\varphi_{k}=r^{\frac12}{\rm e}^{ikt}\widehat{\varphi}_{k}$, there holds
 \begin{equation*}
 \begin{aligned}
 \|\partial_{\theta}\varphi\|_{L^{\infty}L^{\infty}}\leq&\sum_{k\neq 0, k\in\mathbb{Z}}|k|\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\widehat{\varphi}_{k}\|_{L^{\infty}L^{\infty}}\\\leq& R^{\frac12}\sum_{k\neq 0, k\in\mathbb{Z}}|k|\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}r^{-\frac12}\varphi_{k}\|_{L^{\infty}L^{\infty}}\\\leq &C(R)\sum_{k\neq 0, k\in\mathbb{Z}}|k|^{-\frac12}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}rw_{k}\|_{L^{\infty}L^{2}}\\\leq&C(R)\sum_{k\neq 0, k\in\mathbb{Z}}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}w_{k}\|_{L^{\infty}L^{2}}\leq C(R)\mathcal{Q}_{1}.
 \end{aligned}
 \end{equation*}
 Using (\ref{assumption}), Lemma \ref{lem:ck}, Lemma \ref{lem:c0} and Lemma \ref{lem:n0 w0}, we get
 \begin{equation*}
 \begin{aligned}
 \|c\|_{L^{\infty}L^{\infty}}\leq&\|\widehat{c}_{0}\|_{L^{\infty}L^{\infty}}+\sum_{k\neq 0, k\in\mathbb{Z}}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}c_{k}\|_{L^{\infty}L^{\infty}}\\\leq&C(R)\Big(\|r^{\frac12}\widehat{n}_{0}\|_{L^{\infty}L^{2}}+\sum_{k\neq 0, k\in\mathbb{Z}}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}n_{k}\|_{L^{\infty}L^{2}} \Big)\leq C(R)\left(D_{1}+\mathcal{Q}_{1} \right).
 \end{aligned}
 \end{equation*}
 Moreover, it follows from H$\ddot{\rm o}$lder's and Nash inequalities that
 \begin{equation*}
 \begin{aligned}
 \Big\|n^{p}\Big(1,\partial_{r}, \frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{2}}^{2}\leq&\|n^{p}\|_{L^{4}}^{2}\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{4}}^{2}\\\leq& C\|n^{p}\|_{L^{2}}\|\nabla n^{p}\|_{L^{2}}\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{4}}^{2}.
 \end{aligned}
 \end{equation*}
 Substituting the above estimates into (\ref{np 1}), we arrive at
 \begin{align*}
 &\frac{d}{dt}\|n^{p}\|_{L^{2}}^{2}+\frac{2(2p-1)}{Ap}\Big\|\Big(\partial_{r}, \frac{1}{r}\partial_{\theta} \Big)n^{p}\Big\|_{L^{2}}^{2}\\\leq&\frac{C(R)}{A}\Big(1+pD_{1}+p\mathcal{Q}_{1} \Big)\|n^{p}\|_{L^{2}}^{2}+\frac{Cp^{2}}{A}\|n^{p}\|_{L^{2}}\|\nabla n^{p}\|_{L^{2}}\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^4}^{2}\\&+\frac{2p-1}{Ap}\Big\|\Big(\partial_{r},\frac{1}{r}\partial_{\theta} \Big)n^{p} \Big\|_{L^{2}}^{2}\\\leq&\frac{C(R)}{A}\Big(1+pD_{1}+p\mathcal{Q}_{1} \Big)\|n^{p}\|_{L^{2}}^{2}+\frac{Cp^{4}}{A}\|n^{p}\|_{L^{2}}^{2}\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{4}}^{4}\\&+\frac{5(2p-1)}{4Ap}\Big\|\Big(\partial_{r},\frac{1}{r}\partial_{\theta} \Big)n^{p} \Big\|_{L^{2}}^{2}.
 \end{align*}
 This implies that
 \begin{equation}\label{np 2}
 \begin{aligned}
 &\frac{d}{dt}\|n^{p}\|_{L^{2}}^{2}+\frac{1}{2A}\Big\|\Big(\partial_{r},\frac{1}{r}\partial_{\theta} \Big)n^{p} \Big\|_{L^{2}}^{2}\\\leq&\frac{C(R)p^{4}}{A}\|n^{p}\|_{L^{2}}^{2}\Big[\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{4}}^{4}+\mathcal{Q}_{1}+D_{1}+1 \Big].
 \end{aligned}
 \end{equation}
 Using the Nash inequality again
 \begin{equation*}
 \|n^{p}\|_{L^{2}}\leq C(R)\|n^{p}\|_{L^{1}}^{\frac12}\Big\|\Big(\partial_{r},\frac{1}{r}\partial_{\theta} \Big)n^{p} \Big\|_{L^{2}}^{\frac12},
 \end{equation*}
 we infer from (\ref{np 2}) that
 \begin{equation}\label{np 3}
 \begin{aligned}
 \frac{d}{dt}\|n^{p}\|_{L^{2}}^{2}\leq&-\frac{\|n^{p}\|_{L^{2}}^{4}}{2AC(R)\|n^{p}\|_{L^{1}}^{2}}+\frac{C(R)p^{4}}{A}\|n^{p}\|_{L^{2}}^{2}\Big[\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{4}}^{4}+\mathcal{Q}_{1}+D_{1}+1 \Big]
 \end{aligned}
 \end{equation}
 Using (\ref{assumption}), Lemma \ref{lem:ck}, Lemma \ref{lem:c0}, Lemma \ref{lem:n0 w0} and Gagliardo-Nirenberg inequality, one obtains
 \begin{equation*}
 \begin{aligned}
 &\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{\infty}L^{4}}\leq\|(1,\partial_{r})\widehat{c}_{0}\|_{L^{\infty}L^{4}}+\sum_{k\neq 0, k\in\mathbb{Z}}\Big\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\Big(1,\partial_{r},\frac{|k|}{r} \Big)c_{k} \Big\|_{L^{\infty}L^{4}}\\\leq&C\|(1,\partial_{r})\widehat{c}_{0}\|_{L^{\infty}L^{2}}^{\frac34}\|(1,\partial_{r})\partial_{r}\widehat{c}_{0}\|_{L^{\infty}L^{2}}^{\frac14}\\+&C\Big(\sum_{k\neq 0, k\in\mathbb{Z}}\Big\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}c_{k}\Big\|_{L^{2}} \Big)^{\frac12}\Big(\sum_{k\neq 0, k\in\mathbb{Z}}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\Big(\partial_{r},\frac{|k|}{r} \Big)c_{k}\Big\|_{L^{2}} \Big)^{\frac12}\\+&C\Big(\sum_{k\neq 0, k\in\mathbb{Z}}\Big\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\Big(\partial_{r},\frac{|k|}{r} \Big)c_{k}\Big\|_{L^{2}} \Big)^{\frac12}\Big(\sum_{k\neq 0, k\in\mathbb{Z}}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\Big(\partial_{r}^{2}, \frac{1}{r}\partial_{r},\frac{|k|^{2}}{r^{2}} \Big)c_{k}\Big\|_{L^{2}} \Big)^{\frac12}\\\leq&C(R)\big(\|\widehat{n}_{0}\|_{L^{\infty}L^{2}}+\sum_{k\neq 0, k\in\mathbb{Z}}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}n_{k}\|_{L^{\infty}L^{2}}\big)\leq C(R)\left(D_{1}+\mathcal{Q}_{1} \right).
 \end{aligned}
 \end{equation*}
 This along with (\ref{np 3}) gives that
 \begin{equation}\label{np 4}
 \begin{aligned}
 \frac{d}{dt}\|n^{p}\|_{L^{2}}^{2}\leq-\frac{\|n^{p}\|_{L^{2}}^{4}}{2AC(R)\|n^{p}\|_{L^{1}}^{2}}+\frac{C(R)p^{4}}{A}\|n^{p}\|_{L^{2}}^{2}\Big(D_{1}^{4}+\mathcal{Q}_{1}^{4}+1 \Big).
 \end{aligned}
 \end{equation}

