\label{thm:main}
		Assume that the initial data $0\leq n_{\rm in}\in L^{\infty}\cap H^{1}(\mathcal{D})$ and $u_{\rm in}\in H^{2}(\mathcal{D})$. There exists a positive $A_{1}$
		depending on $\|n_{\rm in}\|_{L^{\infty}\cap H^{1}(\mathcal{D})}$ and $\|u_{\rm in}\|_{H^{2}(\mathcal{D})}$, such
		that if $A\geq A_{1}$, then the solutions of
		\begin{equation}\label{ini1}
		\left\{
		\begin{array}{lr}
			\partial_{t}n-\frac{1}{A}(\partial_{r}^{2}+\frac{1}{r}\partial_{r}+\frac{1}{r^{2}}\partial_{\theta}^{2})n+(1+\frac{1}{r^{2}})\partial_{\theta}n+\frac{1}{Ar}(\partial_{r}\varphi\partial_{\theta}n-\partial_{\theta}\varphi\partial_{r}n)\\\qquad\qquad\qquad\qquad\qquad\qquad
			=-\frac{1}{Ar}\partial_{r}(rn\partial_{r}c)-\frac{1}{Ar^{2}}\partial_{\theta}(n\partial_{\theta}c), \\
			(\partial_{r}^{2}+\frac{1}{r}\partial_{r}+\frac{1}{r^{2}}\partial_{\theta}^{2})c+n-c=0,\\
			\partial_{t}w-\frac{1}{A}(\partial_{r}^{2}+\frac{1}{r}\partial_{r}+\frac{1}{r^{2}}\partial_{\theta}^{2})w+(1+\frac{1}{r^{2}})\partial_{\theta}w+\frac{1}{Ar}(\partial_{r}\varphi\partial_{\theta}w-\partial_{\theta}\varphi\partial_{r}w)=-\frac{1}{Ar}\partial_{\theta}n, \\
			(\partial_{r}^{2}+\frac{1}{r}\partial_{r}+\frac{1}{r^{2}}\partial_{\theta}^{2})\varphi=w,
		\end{array}
		\right.
	\end{equation}
		with boundary conditions
		\begin{equation}\label{boundary condition}
		\begin{aligned}
			n|_{r=1,R}=0,\quad c|_{r=1,R}=0,\quad w|_{r=1,R}=0,\quad \varphi|_{r=1,R}=0
		\end{aligned}
	\end{equation}
		are globally bounded and satisfy the follow stability estimates:
		\begin{itemize}
			\item[(i)]  Uniform bounded-ness estimates: 
			\begin{equation*}
				\begin{aligned}
					&\|u\|_{L^{\infty}L^{\infty}}\leq C(\|n_{\rm in}\|_{H^{1}(\mathcal{D})}, \|u_{\rm in}\|_{H^{2}(\mathcal{D})},R),\\
					&\|n\|_{L^{\infty}L^{\infty}}\leq C(\|n_{\rm in}\|_{L^{\infty}\cap H^{1}(\mathcal{D})}, \|u_{\rm in}\|_{H^{2}(\mathcal{D})},R).
				\end{aligned}
			\end{equation*}
			\item[(ii)] Enhanced dissipation estimates:
			\begin{equation*}
				\begin{aligned}
					&\Big\|{\rm e}^{aA^{-\frac13}|\partial_\theta|^{\frac23}R^{-2}t} \Big(n-\frac{1}{2\pi}\int_{0}^{2\pi}n d\theta\Big)
					\Big\|_{L^{2}}\leq C(R)\|n_{\rm in}\|_{H^{1}(\mathcal{D})},\\
					&\Big\|{\rm e}^{aA^{-\frac13}|\partial_\theta|^{\frac23}R^{-2}t} \Big(w-\frac{1}{2\pi}\int_{0}^{2\pi}w d\theta\Big)
					\Big\|_{L^{2}}\leq C(R)\|u_{\rm in}\|_{H^{2}(\mathcal{D})}.
				\end{aligned}
			\end{equation*}
		\end{itemize}

