 \begin{align*}
 F_1 &\lesssim \sum_{n\geq 2} \sum_{j\leq n-1} \sum_{Q\in\mQ_{n-j}}
 \lbracket{ \big(H_2^2(n-1) + H_2^2(n) + 2^{-2(n-1)}\big) \tau(p_Q) \phi(fp_Q \chi_{Q}) }^{\frac{1}{2}} (|Q| \lambda)^{\frac{1}{2}} \\
 &\lesssim \sum_{n\geq 2} \lbracket{2H_2(n-1)+2^{-n+1}} \sum_{j\leq n-1} \sum_{Q\in\mQ_{n-j}}\big(\tau(p_Q) \phi(fp_Q \chi_{Q}) |Q| \lambda \big)^{\frac{1}{2}} \\
 &\lesssim \sum_{m\geq 1} \sum_{Q\in\mQ_m} \big( \tau(p_Q) \phi(fp_Q \chi_{Q}) |Q| \lambda \big)^{\frac{1}{2}}.
 \end{align*}
Finally, applying the Cauchy-Schwarz inequality twice, we estimate $F_1$ as follows:
 \begin{align*}
 F_1 \lesssim \Big(\sum_{m=1}^{\infty} \lambda \phi(p_m)\Big)^{\frac{1}{2}}
 \Big(\sum_{m=1}^{\infty} \phi(f p_m)\Big)^{\frac{1}{2}}
 = \big(\lambda \phi(1-q)\big)^{\frac{1}{2}} \big(\phi(f(1-q))\big)^{\frac{1}{2}}
 &\lesssim \norm{f}_{L_1(\mN)}.
 \end{align*}

