\subsection{Main results and structure of the article} With the previous framework in hand, our goal here is to prove the local and global well-posedness for the initial boundary value problem (IBVP) \eqref{kdV}. The first main result establishes the local well-posedness for this system in sharp spaces.

\begin{lemma}\label{lemma for v}
 Let $(u^0,g_0, g,p)\in \mathbb{X}_{3,T}$, $f\in W^{1,1}(0,T;\mathbb{L}^2(\mathcal{T}))\cap L^2(0,T;\mathbb{H}^1(\mathcal{T}))$ and $v$ the solution of \eqref{v_j}. Then for $\beta=0,1,2,3$ we have:
 \begin{enumerate}
 \item[i.] The function
 \begin{align*}
 \begin{array}{rcl}
 [0,T]&\rightarrow&\mathcal{D}'(0,l_j)\\
 s&\mapsto&\partial_x^\beta v_j(s,\cdot)
 \end{array}
 \end{align*}
 is integrable in $[0,T]$.
 \item[ii.]For any $t \in [0,T]$ we have $\displaystyle\int_0^tv_j(s,\cdot)ds \in H^4(0,l_j)$ and for $\beta=0,1,2,3$ we have
 \begin{align*}
 \partial_x^\beta\int_0^tv_j(s,\cdot)ds=\int_0^t\partial_x^\beta v_j(s,\cdot)ds.
 \end{align*}
 \end{enumerate}
\end{lemma}
The previous lemma can give us the regularity for $u$.
\begin{proposition}\label{W.P._s=3}
Let $(u^0,g_0,g,p) \in \mathbb{H}^3(\mathcal{T})\times H^{\frac{3-1}{3}}(0,T)\times [H^\frac{3}{3}(0,T)]^N\times [H^{\frac{3+1}{3}}(0,T)]^N$ satisfying the linear compatibility conditions for $s=3$ and $f\in W^{1,1}(0,T;\mathbb{L}^2(\mathcal{T}))\cap L^2(0,T;\mathbb{H}^1(\mathcal{T}))$ be. For $j=1,...,N$ the function $t\mapsto u_j(t,\cdot)$ given by \eqref{u_j} satisfies the following items:
