 &\left.+\|p\|_{[H^\frac{3+1}{3}(0,T)]^N}+\|f\|_{W^{1,1}(0,T;\mathbb{L}^2(\mathcal{T}))\cap L^2(0,T;\mathbb{H}^1(\mathcal{T}))}\right)
\end{split}
 \end{equation*}
 for some constant $C>0$.
 \item[iii.] $u \in H^1(0,T;\mathbb{H}^1(\mathcal{T}))$ and
