\section{Local well-posedness of the nonlinear problem}\label{sec4}
Now, we are in a position to prove the first main result of the article, namely, the local well-posedness of the following problem
\begin{align}\label{NLKdV}
 \left\{
 \begin{array}{ll}
 \partial_t u_j+\partial_x [(a_j+1)u_j]+\partial_x^3 u_j+u_j\partial_x u_j=f_j,&t \in (0,T),\ x \in (0,l_j),\\
 u_j(t,0)=u_1(t,0),&t\in (0,T),\\
 \displaystyle\sum_{j=1}^N\partial_x^2 u_j(t,0)=-\alpha u_1(t,0)-\frac{N}{3}(u_1+a_1)^2(t,0)+g_0(t),&t \in (0,T)\\ 
 u_j(t,l_j)=p_j(t),\ \ \ \ \ \partial_x u_j(t,l_j)=g_j(t),&t\in (0,T),\\
 u_j(0,x)=u_j^0(x),&x \in (0,l_j),
 \end{array}
 \right.
\end{align}
where $j=1,...,N$ and $a$ is a given function. Remember that: for $s\geq 0$ and $T>0$ the space
\begin{align*}
\mathcal{X}_{s,T}=\left\{v \in \mathbb{B}_{s,T}^*;\ \partial_x^ku_j\in L_x^\infty(0,l_j;H^\frac{s+1-k}{3}(0,T)),\ k=0,1,2,\ j=1,2,...,N\right\}
\end{align*}
is a Banach space with the norm
\begin{align*}
\|v\|_{\mathcal{X}_{s,T}}=\|v\|_{\mathbb{B}_{s,T}^*}+\sum_{k=0}^2\|\partial_x^kv\|_{\prod_{j=1}^NL_x^\infty(0,l_j;H^\frac{s+1-k}{3}(0,T))}.
\end{align*}
Note that \eqref{kdV} is a particular case of \eqref{NLKdV} with $a=0$.
\begin{proof}[Proof of Theorem \ref{main}] Fix $\theta \in (0,T)$ and define $\Gamma_a:\mathcal{X}_{s,\theta}\rightarrow \mathcal{X}_{s,\theta}$ putting, for each $u \in \mathcal{X}_{s,\theta}$, $\Gamma_au$ as being the solution $v$ of
\begin{align*}
 \left\{
 \begin{array}{ll}
 \partial_t v_j+\partial_x [(a_j+1)v_j]+\partial_x^3 v_j=-u_j\partial_x u_j+f_j,&t \in (0,\theta),\ x \in (0,l_j),\ j=1,...,N,\\
 v_j(t,0)=v_1(t,0),&t\in (0,\theta),\ j=1,...,N,\\
 \displaystyle\sum_{j=1}^N\partial_x^2 v_j(t,0)=-\alpha v_1(t,0)-\frac{N}{3}(u_1+a_1)^2(t,0)+g_0(t),&t \in (0,\theta,)\\ 
 v_j(t,l_j)=p_j(t),\ \ \ \ \ \partial_x v_j(t,l_j)=g_j(t),&t\in (0,\theta),\ j=1,...,N,\\
 v_j(0,x)=u_j^0(x),&x \in (0,l_j),\ j=1,...,N.
 \end{array}
 \right.
\end{align*}
From Proposition \ref{W.P.LKdV-a} we have
\begin{align*}
& \|\Gamma_au\|_{\mathcal{X}_{s,\theta}}\leq C\left(\|u^0\|_{\mathbb{H}^s(\mathcal{T})}+\|g_0-\frac{N}{3}(u_1+a_1)^2(\cdot,0)\|_{H^\frac{s-1}{3}(0,\theta)}+\|g\|_{[H^\frac{s}{3}(0,\theta)]^N}\right.\\
&\left.+\|p\|_{[H^\frac{s+1}{3}(0,\theta)]^N}+\|u\partial_xu\|_{W^{\frac{s}{3},1}(0,\theta;\mathbb{L}^2(\mathcal{T}))\cap L^\frac{6}{6-s}(0,\theta;\mathbb{H}^\frac{s}{3}(\mathcal{T}))}+\|f\|_{W^{\frac{s}{3},1}(0,\theta;\mathbb{L}^2(\mathcal{T}))\cap L^\frac{6}{6-s}(0,\theta;\mathbb{H}^\frac{s}{3}(\mathcal{T}))} \right).
\end{align*}
Using Lemma \ref{lemma 2.4} we obtain
\begin{align*}
 \|\partial_xu v\|_{W^{\frac{s}{3},1}(0,\theta;\mathbb{L}^2(\mathcal{T}))\cap L^\frac{6}{6-s}(0,\theta;\mathbb{H}^\frac{s}{3}(\mathcal{T}))}\leq C(\theta^\frac{1}{2}+\theta^\frac{1}{3})\|u\|_{\mathbb{B}_{s,\theta}^*}\|u\|_{\mathbb{B}_{s,\theta}^*}.
\end{align*}
Furthermore, Lemma \ref{lemma 2.1} gives us
\begin{align*}
\left\|\frac{N}{3}(u_1+a_1)^2(\cdot,0)\right\|_{H^\frac{s-1}{3}(0,\theta)}&\leq C\theta^\alpha\frac{N}{3}\left\|(u_1+a_1)(\cdot,0)\right\|_{H^\frac{s+1}{3}(0,\theta)}^2\\
&\leq C\theta^\alpha\frac{N}{3}\|u+a\|_{\mathcal{X}_{s,\theta}}^2\\
&\leq \frac{4}{3}CN\theta^\alpha \left(\|u\|_{\mathcal{X}_{s,\theta}}^2+\|a\|_{\mathcal{X}_{s,\theta}}^2\right),
\end{align*}
where $\alpha>0$ is a constant. Thus,
\begin{align*}
 \|\Gamma_au\|_{\mathcal{X}_{s,\theta}}\leq& C\left(\|u^0\|_{\mathbb{H}^s(\mathcal{T})}+\|g_0\|_{H^\frac{s-1}{3}(0,T)}+\|g\|_{[H^\frac{s}{3}(0,T)]^N}\right.\\
&+\|p\|_{[H^\frac{s+1}{3}(0,T)]^N}+\|f\|_{W^{\frac{s}{3},1}(0,T;\mathbb{L}^2(\mathcal{T}))\cap L^\frac{6}{6-s}(0,T;\mathbb{H}^\frac{s}{3}(\mathcal{T}))}\\
&\left.+C(\theta^\frac{1}{2}+\theta^\frac{1}{3})\|u\|_{\mathcal{X}_{s,\theta}}^2+\frac{4}{3}CN\theta^\alpha \|u\|_{\mathcal{X}_{s,\theta}}^2+\frac{4}{3}CN\theta^\alpha\|a\|_{\mathcal{X}_{s,\theta}}^2 \right).
\end{align*}
Defining
\begin{align*}
r=&4C\left(\|u^0\|_{\mathbb{H}^s(\mathcal{T})}+\|g_0\|_{H^\frac{s-1}{3}(0,T)}+\|g\|_{[H^\frac{s}{3}(0,T)]^N}\right.\\
&\left.+\|p\|_{[H^\frac{s+1}{3}(0,T)]^N}+\|f\|_{W^{\frac{s}{3},1}(0,T;\mathbb{L}^2(\mathcal{T}))\cap L^\frac{6}{6-s}(0,T;\mathbb{H}^\frac{s}{3}(\mathcal{T}))}\right),
\end{align*}
it follows that, for $u \in B=\{v \in \mathcal{X}_{s,\theta};\ \|v\|_{\mathcal{X}_{s,\theta}}\leq r\}$,
\begin{align}\label{eq 3.2}
\|\Gamma_au\|_{\mathcal{X}_{s,\theta}}\leq \frac{r}{4}+C^2(\theta^\frac{1}{2}+\theta^\frac{1}{3})r^2+\frac{4}{3}C^2N\theta^\alpha r^2+\frac{4}{3}C^2N\theta^\alpha\|a\|_{\mathcal{X}_{s,T}}^2.
\end{align}

post_theorem_intro_text:
The proof of the previous theorem relies on several analytical tools combined with a fixed-point argument. In addition, a new notion of $s$-compatibility adapted to the graph structure is introduced (see Section \ref{sec2}), inspired by the single-edge KdV framework in \cite{BSZ 2003}. This theorem provides a sharp local well-posedness result, along with regularity properties, for the associated functions. Furthermore, we establish the existence of global solutions at the $H^s$-norm, which enables applications to control problems on star graphs and resolves several open questions that will be addressed in a forthcoming paper. The second main result of this work can be stated as follows.

\begin{theorem}\label{global_(0,3)}
Let $T>0$ and $\lambda\geq 1$ be. Consider $(u^0,g_0,g,p)\in \mathbb{X}_{s,T}^\lambda$, where $\mathbb{X}_{s,T}^\lambda$ is the set of $s$-compatible data
$$u^0 \in \mathbb{H}^{s}(\mathcal{T}), g_0 \in H^{\frac{s+\lambda-1}{3}}(0,T),\ g \in [H^\frac{s}{3}(0,T)]^N\quad \text{and}\quad p\in [H^\frac{s+\lambda+1}{3}(0,T)]^N.$$
Thus, the problem \eqref{kdV} has a unique solution $u\in \mathcal{X}_{s,T}$ which satisfies
\begin{align*}
	\|u\|_{\mathcal{X}_{s,T}}&\leq C\left(\|(u^0,g_0,g,p)\|_{0,\lambda}\right)\left(
	\begin{array}{c}
		\|u^0\|_{\mathbb{H}^s(\mathcal{T})}+\|g_0\|_{H^\frac{s+\lambda-1}{3}(0,T)}+\|g\|_{[H^\frac{s}{3}(0,T)]^N}+\|p\|_{[H^\frac{s+\lambda+1}{3}(0,T)]^N}
	\end{array}
	\right)
\end{align*}
where $C>0$ is a positive constant. 
\end{theorem}
Together, these two theorems provide, for the first time, a comprehensive framework for the well-posedness of general graph structures with boundary controls. Moreover, they extend the classical result for a single KdV equation \cite{BSZ 2003} to star-shaped graphs composed of $N$ equations.
\vspace{0.2cm}

The paper is organized as follows. In Section \ref{sec2}, we introduce a general notion of $s$-compatibility for star graphs. Building on this framework, Section \ref{sec3} addresses the well-posedness of the linear system associated with \eqref{kdV}. After that, Section \ref{sec4} is devoted to proving the local well-posedness result for the system \eqref{kdV}, giving the proof of Theorem \ref{main}. The second main result, concerning global well-posedness, in the $H^s$-regime, for the system \eqref{kdV} is established in Section \ref{sec6}.

