\begin{theorem}[Hirose--Maesaka--Seki--Watanabe~\cite{HiroseMaesakaSekiWatanabe2025+}]
The drop 1 operator $\cD$ satisfies the following properties$:$
\label{thm:drop1}
\begin{enumerate}[label=\textnormal{(\roman*)}]
\item\label{it:HMSW1} $\{w-\cD(w) \mid w\in \cH^0\}=\Ker(Z^{\diamondsuit})\subset\Ker(Z)$,
\item\label{it:HMSW2} $\cD(w)=w$ for $w\in\cH^{\geq 2}$,
\item\label{it:HMSW3} $\cD(w)=\cD(\tau(w))$ for $w\in \cH^0$.
\end{enumerate}
\end{theorem}

ref_dict.def:drop1operator:
\begin{definition}[Hirose--Maesaka--Seki--Watanabe~\cite{HiroseMaesakaSekiWatanabe2025+}]\label{def:drop1operator}
We define the \emph{drop 1 operator} $\cD\colon\cH^0\to\cH^{\geq 2}$ to be a $\ZZ$-linear map given as follows.
It suffices to define $\cD(w)$ for each word $w\in\cH^0$.
For $\bc=(c_1,\dots, c_{2t})$, we write $\fD(\bc)=\cD(y^{c_1}x^{c_2}\cdots y^{c_{2t-1}}x^{c_{2t}})$.
The image $\fD(\bc)$ is defined inductively as follows:
\begin{align*}
\fD(\bc)&=\sum_{\substack{A\in\cP^{\text{eo}}([2t]^1_{\bc}) \\ B\in\cP^{\smallxcancel{\text{eo}}}([2t]^{>1}_{\bc}) \\ \#A+\#B\geq 1}}(-1)^{\#B-1}\fD(\bc_{(-A)}-\bdelta_B)x^{\#A+\#B}\\
