We now bound the probability appearing on the r.h.s of \eqref{eq:proof2point1}. Let $L,M\geq 1$ be parameters to be chosen later (in particular, they will coincide with the choice in \eqref{eq:ML_choice_ub}). And for $\delta\in(0,1)$ to be fixed later, set
\begin{equation}\label{def:xi_delta}
 \xi_\delta\defeq N{e^{-\delta a^2g_N}} 
\end{equation}
and note that $\xi_1=\xi$.
Consider the sets
\begin{align}
\begin{split}
\label{eq:defLell}
\mathcal{L}_{L} \defeq \bigcup_{i=0}^{\lceil 2N/L\rceil} \widetilde{B}\Bigl((iL/2,0),L\Bigr),
\cL^\prime_L\defeq \tB_{10ML}\cup \cL_L, \text{ and }
\cL^{\prime\prime}_L=\cL^{\prime\prime}_L(\delta)\defeq\cL^\prime_L\setminus \tB_{ \xi_\delta}.
\end{split}
\end{align}
For any compact and connected $K\subset \tB_\xi$, define $\mathbb{P}^K_{\ba,L,\delta}$ as the law of
$(\varphi_x + \ba\,\overline{h}_{L}(x))_{x\in \tilde \Z^2\setminus K}$ under $\mathbb{P}^K_N$, where $\overline{h}_{L}(x)=P_x(H_{\mathcal{L}^{\prime\prime}_{L}} < H_K)$.
Then, as in \cite[(6.17)]{drewitz_critical_2023}, a change of measure via the Cameron-Martin formula yields
\begin{equation}
\label{eq:proof2point3}
\P^K_N\bigl(A(K,\ba,N)\bigr)
\ge 
\P^K_{\ba,L,\delta}\bigl(A(K,\ba,N)\bigr)
\exp\Biggl\{-\frac{\ba^{2}\capacity_N^K(\mathcal{L}^{\prime\prime}_{L}) + 1/e}{2\,\P^K_{\ba,L,\delta}(A(K,\ba,N))}\Biggr\}.
\end{equation} 
From now on take (cf.~\eqref{eq:ML_choice_ub})
\begin{equation}\label{eq:ML_choices}
 L=\frac{N}{a^2\log(N)} \text{ and }M=\frac{a^2\log(N)}{\log(a^2\log(N))^2}.
\end{equation}
It remains to bound the quantities on the r.h.s of \eqref{eq:proof2point3} with $L,M$ as in \eqref{eq:ML_choices}. These results are collected in the following two Lemmas.
\begin{lemma} \label{lem:cap_ll}
There exists $\Cl[c]{delta_dist}\in(0,1)$ such that for all $\eta\in(0,1)$, $a^2\in(0,1)$ and $N\geq 1$ such that $a^2\log(N)\geq \Cr{lb}$, we have that with $L,M$ chosen as in \eqref{eq:ML_choices} and with $\delta=\Cr{delta_dist}$ , 
\begin{equation}\label{eq:cap_ll}
 \sup_K \capacity_N^K(\mathcal{L}^{\prime\prime}_{L}(\delta))\leq 
 (1+\eta) {\capacity_{\R^2}^{\tau}([0,1])},
\end{equation}
where the supremem is over all compact and connected $K\subset \tB_\xi$. 
\end{lemma}
\begin{lemma} \label{lem:li_connect}
Let $K\subset \tB_\xi$ be compact and connected. For all $\eta\in(0,1)$, $a^2\in(0,1)$ and $N\geq 1$ such that $a^2\log(N)\geq \Cr{lb}$, we have that with $L,M$ chosen as in \eqref{eq:ML_choices}, $\delta$ chosen as in \eqref{lem:cap_ll},
\begin{equation} \label{eq:li_connect}
 \P^K_{\ba,L,\delta}(A(K,\ba,N))\geq 1-\eta.
\end{equation}
\end{lemma}
Before presenting the proofs of Lemma \ref{lem:cap_ll} and \ref{lem:li_connect} , first note that by combining these lemmas with \eqref{eq:proof2point1}, \eqref{eq:lb_crit_cost} and \eqref{eq:proof2point3}, one obtains
\begin{equation*}
 \theta((1-\eta)\ba,N)\geq c(1-\eta)\theta(0,\xi)
 \exp\left\{-(1+\eta)\frac{\ba^2}{2} \capacity_{\R^2}^{\tau}([0,1])\right\},
\end{equation*}
from which \eqref{eq:prop_lb_asymp} follows using the fact that $\ba^2=\log(N/\xi)$ and a change of variable in $\eta$.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:li_connect}]
We follow the proof of \cite[Lemma 6.4]{drewitz_critical_2023}.
Let $\tau$ be an independent exponential random variable of rate $N^{-2}$. By the definitions of
$\P^K_{\ba,L,\Cr{delta_dist}}$ and $A(K,\ba,N)$, we have that
\begin{equation}
\label{eq:proof2point6}
\begin{aligned}
\P^K_{\ba,L,\Cr{delta_dist}}(A(K,\ba,N))
&\ge \mathbb{P}^K_N\bigl(K \leftrightarrow \partial B_N \text{ in } \{x\in \tilde\Z^2\setminus K : 
\varphi_x \ge \ba(1-\eta - h_{K}(x) - \overline{h}_{L}(x))\}\bigr)
\\
&\ge \mathbb{P}^K_N\bigl(K \leftrightarrow \partial B_N\text{ in } 
\{x\in \mathcal{L}'_{L}\cap \tilde\Z^2\setminus K : \varphi_x \ge -2\eta\ba\}\bigr),
\end{aligned}
\end{equation}
since for all $x\in \mathcal{L}'_{L}$, we have by \eqref{eq:defLell}, \cite[(2.51)]{lawler_random_2010} and the tail of exponential distribution that,
\begin{align*}
 h_{K}(x) + \overline{h}_{L}(x)
&= P_x(H_{K}<\infty) + P_x(H_{\mathcal{L}''_{L}}<H_{K})
=P_x(H_{K\cup \mathcal{L}''_{L}}<\infty)\\
&\ge P_x(H_{B(x,2\xi_{\Cr{delta_dist}})^{c}}<L^2)P(\tau>L^2) \geq (1-ce^{-c^\prime L^2/\xi_{\Cr{delta_dist}}^2}) e^{-L^2/N^2} \\
&\geq (1-ce^{-c^\prime \frac{e^{2\Cr{delta_dist}\ba}}{\ba^2}}) e^{-\frac{1}{\ba^2}} \geq 1-\eta ,
\end{align*}
where the last inequality holds upon taking $a^2\log(N)\geq \Cr{lb}(\eta)$ with $\Cr{lb}(\eta)$ large enough.
It's easy to see that there exists an integer $1\leq p\leq cM$ and a set of vertices $(z_0,z_1,\dots ,z_p)\subset \Z^2$ (which corresponds to the collection of vertices constructed in \cite[(7.14)]{drewitz_critical_2023}) such that,
 \begin{align} \label{eq:defS}
 \begin{split}
 &\begin{array}{r} 
 B(z_0,L/2)\subset B((3ML,0),L), \partial B_{3ML}\subset\bigcup_{i=1}^pB(z_i,L/4),
 \end{array} \\[0.3em] 
 &\begin{array}{r}
 B(z_i,L/4) \cap \partial B_{3ML}\neq \emptyset,
 d(z_i,B_\xi)\geq 2ML \text{ and } B(z_i,L/2)\subset B(z_{i-1},L) \text{ for all }i\in\{1,\dots,p\}.
 \end{array} \\[0.3em] 
 \end{split}
 \end{align}
We next define a suitable event implementing the desired connection in \eqref{eq:proof2point6}, which will be similar to the one illustrated in \cite[Figure 1]{drewitz_critical_2023}. 
The main difference from the setting of \cite{drewitz_critical_2023} is that the multiplicative scales $\sigma, \sigma'$ used there are replaced by substantially larger ones, and additional care is required for connection between $K$ to $\partial B_{\sqrt{\sigma'}\ell}$ due to the presence of a positive killing measure on our graph.
Let $u=(\eta \ba)^2$ and $\mathcal{P}=\{z_0,\dots ,z_p\}\cup \bigcup_{i=6M}^{\lceil 2N/L \rceil}(iL/2,0) $. By \eqref{eqcouplingintergff}, there exists a coupling $\P^K_N\otimes \bar\P^K_N$ of $\varphi$ under $\P^K_N$ with $\mathcal{I}^{2u}$ under $\bar\P^K_N$ such that $\{ \varphi \geq -2\eta \ba \} \supset \mathcal{I}^{2u}$, and $\I^{2u}$ splits as $\I^{2u}=\I^{u,1}\cup\I^{u,2}$ into two independent interlacement sets at level $u$. 
We denote by $\text{LocUniq}_{u,L}^{(2)}(x)$ the event from \eqref{def:local_uniqueness} with $\lambda = \frac{N}{Le^{\Cr{lu_lambda}^{-1}\log(N/L)}}$, defined for the interlacements $\I^{u,2}$. We define $\I^{u,1}_{-}$ as the set of vertices visited by trajectories of the interlacement associated with $\I^{u,1}$ whose backward parts are killed on $K$. Let $\I^{u,1,L}_{-}$ be the set of vertices in $\I^{u,1}_{-}$ visited before the first exit time from $B_{4ML}$. Consider the (good) event
\begin{equation}
\label{eq:lb15}
G= \Big\{\I^{u,1,L}_{-}\cap\I^{u,2}\cap\bigcup_{i=0}^pB(z_i,L/2)\neq\emptyset\Big\} \cap \bigcap_{x\in \mathcal{P}} \big( \big\{ \text{LocUniq}^{(2)}_{u,L}(x)\big\} \cap \{\I^{u,2} \cap B(x,L/2) \neq \emptyset\} \big).
\end{equation}
We also define, for all $s\in [0,1]$,
\[
G_s'=\Big\{\exists\,i\in \{0,\dots,p\}:\,\capacity_N^K(\I^{u,1,L}_{-}\cap B(z_i,L/2))\geq s\, \capacity_N^K(B(z_i,L/2))\Big\}.
\]
It then follows from the same reasoning as for \cite[(7.16)]{drewitz_critical_2023} that,
\begin{equation}
\label{eq:lb16}
\P^K_{\ba,L,\Cr{delta_dist}}(A(K,\ba,N))\geq \bar\P^K_N(G)\geq \bar\E^K_N\big[ \bar\P^K_N(G\,|\,\I^{u,1})1_{G_s'}\big].
\end{equation}
We will bound $ \bar\P^K_N(G_s')$ for a suitable $s$ and $ \bar\P^K_N(G\,|\,\I^{u,1})$ on $G_s'$ separately from below.

expanded_sketch:
To prove the main theorem, we combine separate upper and lower bounds for $\theta(\bar a,N)$.

We first prove the following theorem.
\begin{theorem}\label{prop:upper_bound}
    For all $a\in(-1,1)$ and $N\geq 1$, we have that with $\xi$ as in \eqref{def:correlation_length},
    \begin{equation} \label{eq:prop_ub}
        \theta(\ba,N)\leq \theta(0,\xi)\exp\left\{-c\,\log\big((N/\xi)\vee 2\big)\right\}.
    \end{equation}
    Furthermore, for all $\eta\in(0,1)$, there exists $\Cl[c]{ub}(\eta)<\infty$ such that when $a^2\log(N)\geq \Cr{ub}$,
    \begin{equation} \label{eq:prop_ub_asymp}
    \theta(\ba,N)\leq  \theta(0,\xi)\exp\left\{-\frac{1-\eta}{2} \capacity_{\R^2}^{\tau}\big([0,1]\big)\log(N/\xi)\right\}.
    \end{equation}
\end{theorem}

We next prove the following theorem.
\begin{theorem}\label{prop:lower_bound}
    For all $a\in(-1,1)$ and $N\geq 1$, we have that with $\xi$ as in \eqref{def:correlation_length},
    \begin{equation} \label{eq:prop_lb}
        \theta(\ba,N)\geq \theta(0,\xi)\exp\left\{-c\,\log\big((N/\xi)\vee 2\big)\right\}.
    \end{equation}
    Furthermore, for all $\eta\in(0,1)$, there exists $\Cl[c]{lb}(\eta)<\infty$ such that when $a^2\log(N)\geq \Cr{lb}$,
    \begin{equation} \label{eq:prop_lb_asymp}
    \theta(\ba,N)\geq  \theta(0,\xi)\exp\left\{-\frac{1+\eta}{2} \capacity_{\R^2}^{\tau}\big([0,1]\big)\log(N/\xi)\right\}.
    \end{equation}
\end{theorem}

For the **upper bounds** on $\theta$, the text explains that the “transition from fractional logarithmic to polynomial decay” comes from “combining a conditioning argument at scale $\xi$, designed to exhibit the critical cost $\theta(0,\xi)$, and a coarse-graining procedure to estimate the cost of the remaining connection.” The argument uses three scales
\begin{equation}\label{eq:scales}
\xi \ll L \ll ML
\end{equation}
chosen depending on $a$ and $N$. The role of $L\gg \xi$ is to “ensure that the critical cost $\theta(\bar a,\xi)$ can be decoupled,” and it is “delicate” to make this decoupling “multiplicatively” (since “careless additive errors… can easily become too large”).

Lemma~\ref{lem:near_critical} is used here:
\begin{lemma}[Near-critical estimate]\label{lem:near_critical}
For all $a\in\R$ and $L\geq 2r\geq 2$, letting
\begin{equation} \label{eq:f}
    f^L_r(a)\defeq \sqrt{\frac{\log(L/r)}{\log(L)}} \vee  \frac{\textnormal{sign}(a)a^2}{\sqrt{\log(L)\log(L/r)}},
\end{equation}
one has for $a,L, r$ as above and all $N \geq 1$ that
    \begin{equation}\label{eq:crit_isom_bound}
        \P_N^{L}\big( 0 \stackrel{\geqslant -a}{\longleftrightarrow}\partial B_r )\leq cf^L_r(a). 
    \end{equation}
\end{lemma}
This is referenced as yielding that “$\xi$ is maximal such that $\theta(\bar a,\xi)\lesssim \theta(0,N)$,” thereby justifying $\xi$ as the “relevant correlation length.”

The remaining connection beyond scale $L$ (the event $\{\partial B_L \stackrel{\ge \bar a}{\longleftrightarrow} \partial B_N\}$) is handled by coarse-graining. Unlike higher-dimensional settings, here one aims at “polynomial rather than (stretched) exponential decay.” The coarse-graining leads (for $a>0$ and conditioning on the boundary field $\mathcal F$) to a three-term bound
\[
\P_N\big(\partial B_L\stackrel{\geq \bar a}{\leftrightarrow}\partial B_N\mid\mathcal F\big)\le a_1+a_2+a_3.
\]
Here $a_1$ is a “local” term showing the cost of “many independent crossing events at scale $L$,” controlled via an a-priori crossing estimate. The terms $a_2$ and $a_3$ are “deviation events for harmonic averages,” in the spirit of Sznitman-type controls, but in “two-dimensional analogues… no longer of ‘large deviation’ type.” Two deviation terms appear because there is “a harmonic shift” from conditioning on the “anchoring” box (where the critical cost is exhibited) and “another one stemming from decoupling the various boxes,” where “the correct choice of $M$ comes into play.” The “three forces $a_i$” must be “carefully balanced” to obtain the desired upper bounds.

For the **lower bounds** on $\theta$, the text says they “roughly follow the heuristic picture from Drewitz, \emph{Critical} (2023) but now with precisely the scales appearing in the equation above,” and that they “rely on certain local uniqueness estimates in two dimensions.”

