\subsection{Methodology and organization of the paper}
\label{sec-1-3}

\begin{proposition}
 \label{prop-decomposition}
 Let $\psi \in C^0([-t_0,t_0],\mathcal{E})$ be a local solution of the NLS equation (\ref{NLS}) for some $t_0 > 0$ and assume that there is a small fixed $\epsilon_0 > 0$ such that 
 \begin{equation}
\label{bound-bigger}
 \inf_{\alpha,\beta \in \R} \rho_R\left(e^{i \alpha} \psi(t,\cdot + \beta),\phi \right) \leq \epsilon^2_0, \quad t \in [-t_0,t_0]. 
\end{equation}
Then, the solution can be uniquely represented as 
 \begin{equation}
 \label{decomposition}
 e^{i \alpha(t)} \psi(t,\cdot + \beta(t)) = \phi + u(t,\cdot) + i v(t,\cdot), \quad \langle u, \phi' \rangle_{L^2(\R)} = 0, \quad \langle v, \phi \rangle_{\mathcal{H}_R} = 0, 
 \end{equation}
 for every $t \in [-t_0,t_0]$, with some real $\alpha(t),\beta(t) \in C^0([-t_0,t_0])$ and $u,v \in C^0([-t_0,t_0],\mathcal{H}^1_R)$.
\end{proposition}

We start by considering a local solution $\psi \in C^0([-t_0,t_0],\mathcal{E})$ of the NLS equation (\ref{NLS}) satisfying the bound (\ref{bound-bigger}) for some small fixed $\epsilon_0 > 0$. 
By Proposition \ref{prop-decomposition}, the solution can be written in the form (\ref{decomposition}). 
By using coercivity estimates (\ref{coercivity-minus}) and (\ref{coercivity-R}) in Lemmas \ref{lem-operator-minus} and \ref{lem-operator-R}, we get from energy conservation (\ref{energy}) and energy decomposition (\ref{energy-correct}):
\begin{align} 
E(\psi_0) - E(\phi) &= E(\phi + u + i v) - E(\phi) \notag \\
&\geq C (\| u' + i v'\|_{L^2(\R)} + \| u + iv \|^2_{\mathcal{H}_R} + \| \eta \|^2_{L^2(R,\infty)}) \notag \\
& \; - C \left( \| u + i v \|^3_{H^1(-\infty,R)} + \| u + i v \|^6_{H^1(-\infty,R)} + \| \eta \|_{L^{\infty}(R,\infty)} \| \eta \|^2_{L^2(R,\infty)} \right),
\label{energy-control}
\end{align}
for some positive constant $C$. It follows from (\ref{distance}) that 
$$
\| u + i v\|^2_{H^1(-\infty,R)} + \| \eta \|^2_{L^2(R,\infty)} \leq \rho_R(\phi + u + iv, \phi).
$$
By using Proposition \ref{prop-supremum}, as long as the bound (\ref{bound-apriori}) holds, the bound (\ref{energy-control}) can be rewritten as 
$$
E(\psi_0) - E(\phi) \geq C \rho_R(\phi + u + iv, \phi), 
$$
by reducing the value of $C$ compared to (\ref{energy-control}). It follows from the energy decomposition (\ref{energy-decomp}) that 
$$
E(\psi_0) - E(\phi) \leq C \delta^2,
$$
for some $C > 0$ if $\rho_R(\psi,\phi) \leq \delta^2$ is small. This yields 
$$
\rho_R(e^{i \alpha(t)} \psi(t,\cdot + \beta(t)), \phi) \leq C \delta^2, \quad t \in [-t_0,t_0],
$$
for the solution $\psi \in C^0(\R,\mathcal{E})$ decomposed by (\ref{decomposition}). This defines $\epsilon^2 := C \delta^2 \in (0,\epsilon^2_0)$ 
and justifies the bound (\ref{bound-bigger}) beyond the time interval $[-t_0,t_0]$. Hence, the decomposition (\ref{decomposition}) and the energy bound (\ref{energy-control}) can be extended globally in time for every $t \in \R$. This completes the proof of the bound (\ref{bound-distance}) in Theorem \ref{th-main}.

We now consider a generalized case of competing nonlinearities bearing
powers $p+1$ and $q+1$ (with the cubic-quintic representing the special case
of $p=2$ and $q=4$).
For the normalization purposes, similarly to the cubic--quintic NLS equation (\ref{NLS}), 
we set the frequency parameter to unity and consider the kink with the profile 
$\phi(x)$ satisfying $\phi(x) \to 0$ as $x \to -\infty$ and $\phi(x) \to 1$ as $x \to +\infty$. This gives uniquely coefficients 
of the competing nonlinearity with two powers $(p,q)$ satisfying $2 \leq p < q$ in the generalized NLS equation:
\begin{equation}
\label{NLS-power}
i \psi_t = \psi_{xx} - \psi + \frac{q (p+2)}{2 (q-p)} |\psi|^p \psi - \frac{p(q+2)}{2(q-p)} |\psi|^q \psi.
\end{equation}
The conserved energy function is given by
\begin{equation}
\label{energy-power}
E(\psi) = \int_{\mathbb{R}} \left[ |\psi_x|^2 + |\psi|^2 \frac{q(1 - |\psi|^p) - p (1 - |\psi|^q)}{q-p} \right] dx,
\end{equation}
and it is defined in the energy space 
\begin{equation}
\label{energy-space-power}
\mathcal{E} = \{ \psi \in H^1_{\rm loc}(\R) : \;\; 
\psi_x \in L^2(\R), \;\; \psi \sqrt{1 - |\psi|^p} \in L^2(\R), \;\; \psi \sqrt{1 - |\psi|^q} \in L^2(\R)\}.
\end{equation}
Local well-posedness of the initial-value problem for (\ref{NLS-power}) in the energy space $\mathcal{E}$ in (\ref{energy-space-power}) 
can be poven with the same method as in Appendix \ref{S:lwp}, although the global continuation of solutions may depend on the powers 
$(p,q)$ of the competing nonlinearity.

The kink profile is obtained from the zero level curve of the first-order invariant
\begin{equation*}
I(\phi,\phi') = (\phi')^2 - \phi^2 \frac{q(1 - \phi^p) - p (1 - \phi^q)}{q-p} = 0,
\end{equation*}
where $q > p$ and $q(1 - \phi^p) - p (1 - \phi^q) \geq 0$ on $(0,\infty)$ with the only minimum at $\phi = 1$.
The linearized system in (\ref{lin-NLS}) is associated with the linearized operators 
\begin{equation*}
\left\{ \begin{array}{l} \mathcal{L}_- = -\partial_x^2 + 1 - \frac{q (p+2)}{2 (q-p)} \phi^p + \frac{p(q+2)}{2(q-p)} \phi^q, \\
\mathcal{L}_+ = -\partial_x^2 + 1 - \frac{q (p+1) (p+2)}{2 (q-p)} \phi^{p} + \frac{p (q+1) (q+2)}{2(q-p)} \phi^{q}, \end{array} \right. 
\end{equation*}
which have the same spectral properties in $L^2(\mathbb{R})$ as in the cubic--quintic case since $\mathcal{L}_- \phi = 0$ 
and $\mathcal{L}_+ \phi' = 0$. By using (\ref{eta-variable}), we obtain the decomposition of the energy (\ref{energy-power}) in the form 
\begin{equation*}
E(\phi + u + i v) - E(\phi) = Q_-(u) + Q_-(v) + R(\eta),
\end{equation*}
where 
$$
Q_-(u) = \int_{\mathbb{R}} \left[ (u')^2 + u^2 - \frac{q (p+2)}{2 (q-p)} \phi^p u^2 + \frac{p(q+2)}{2(q-p)} \phi^q u^2 \right] dx
$$
and 
\begin{align*} 
R(\eta) &= \frac{p}{q-p} \int_{\mathbb{R}} \left[ (\phi^2 + \eta)^\frac{q+2}{2} - \phi^{q+2} - \frac{q+2}{2} \phi^q \eta \right] dx \\
& \quad - \frac{q}{q-p} \int_{\mathbb{R}} \left[ (\phi^2 + \eta)^\frac{p+2}{2} - \phi^{p+2} - \frac{p+2}{2} \phi^p \eta \right] dx.
\end{align*}
If $2 \leq p < q$, then the mapping $L^2(\mathbb{R}) \cap L^{\infty}(\mathbb{R}) \ni \eta \to R(\eta) \in \mathbb{R}$ is $C^2$ 
such that the decomposition can be expanded in the form:
\begin{align*}
R(\eta) = \frac{pq}{8(q-p)} \int_{\mathbb{R}} \left[ (q+2) \phi^{q-2} - (p+2) \phi^{p-2} \right] \eta^2 dx 
\left( 1 + \mathrm{o}(\| \eta \|_{L^{\infty}}) \right).
\end{align*}
By Proposition \ref{prop-supremum}, the remainder term in the decomposition of $R(\eta)$ is much smaller than the leading-order term 
if $\epsilon_0 > 0$ is small in the bound (\ref{bound-apriori}). 
By picking $R \in \mathbb{R}$ such that 
$$
\phi^{q-p}(R) > \frac{p+2}{q+2},
$$
the line $\mathbb{R}$ can be divided into $(-\infty,R)$ and $(R, \infty)$ with the same energy decomposition as in (\ref{energy-correct}). Lemmas 
\ref{lem-operator-minus} and \ref{lem-operator-R} as well as Proposition \ref{prop-decomposition} remain true so that the orbital stability theorem 
of the kink in $\mathcal{E} \cap \mathcal{H}_R$, where $\mathcal{H}_R$ is given by (\ref{Hilbert-space}) and $\mathcal{E}$ is given by (\ref{energy-space-power}), can be proven for the generalized NLS equation (\ref{NLS-power}) verbatim to the proof of Theorem \ref{th-main}. Note that the orbital stability 
result of Theorem \ref{th-main} only uses the local well-posedness of the initial-value problem in the energy space $\mathcal{E}$ since the solution 
is continued globally near the kink orbit by using the energy estimates.

