The numbers \(c_{d, 0}(j)\) are just unsigned Stirling numbers of the first kind. 
Recall that the (signed) Stirling number of the first kind \(s(m, i)\) is defined by
\begin{equation*}
 s(m, i) \coloneqq (-1)^{m - i} \cdot |\{\sigma \in S_m : \sigma \text{ has } i \text{ cycles}\}|.
\end{equation*}

\begin{proof}
 From the definition of $P_{d, k}$, we see that $P_{d, 0}(n) = \binom{n + d}{d}$. 
 The result now follows from the fact that $s(m, i)$ is the coefficient of $x^i$ in $x(x - 1) \cdots (x - m + 1)$ (see, for example, \cite[Proposition 1.3.7]{ec1}).
\end{proof}

Although we could stop here and say we have given combinatorial meaning to the coefficients $c_{d, 0}(j)$, we would ideally like to give combinatorial meaning to the fact that for any $n \geq 0$,
\begin{equation*}
 d!P_{d, 0}(n) = \sum_{j = 0}^d c_{d, 0}(j)n^j.
\end{equation*}
Especially since the polynomials $P_{d, k}$ are Ehrhart polynomials, it makes more sense to interpret $c_{d, k}(j)$ in this context rather than doing so independently. 
Also note that if we show that $|s(d + 1, j + 1)|$ satisfies the above equation for all $n \geq 0$, then this implies that $c_{d, 0}(j) = |s(d + 1, j + 1)|$.

\begin{lemma}\label{lem:str}
 For any $d \geq 1$ and $k, j \in [0, d]$, we have
 \begin{equation*}
 c_{d, k}(j) = \sum_{i = 0}^k \binom{k}{i} \sum_{\ell = 0}^{d - i} |s(d - i + 1, \ell + 1)|s(i, j - \ell).
 \end{equation*}
\end{lemma}

\begin{proof}
 Note that for any permutation $\sigma \in S_m$ with $i$ cycles, the parity of $m - i$ is the same as the number of even cycles in $\sigma$. 
 We now interpret the expression from Lemma \ref{lem:str} for $c_{d, k}(j)$ as the signed count of the following objects: 
 Permutations of size $d + 1$ with $j + 1$ cycles where
 \begin{itemize}
 \item any cycle with all elements in $[k]$ is colored either red or blue,
 \item any cycle containing an element not in $[k]$ is uncolored, and
 \item the sign associated to the permutation is the number of even cycles that are colored red.
 \end{itemize}

\begin{lemma}
 For any $d \geq 1$ and $k \in [0, d]$, we have $c_{d, k}(0) = d!$ and $c_{d, k}(d) = 2^k$.
\end{lemma}

\begin{lemma}
 For any $d \geq 1$ and $k, j \in [0, d]$, we have $c_{d, k}(j) \leq c_{d + 1, k}(j)$.
\end{lemma}

